INSERT INTO recipes (id, slug, title, description, cuisine, cook_time_minutes, servings, difficulty, image_url, tags, prep_time_minutes, source_type, source_reference, verification_state, version) VALUES
('vn-canh-01', 'canh-chua-ca-loc-nam-bo', 'Canh chua cá lóc Nam Bộ', 'Bát canh chua cá lóc Nam Bộ đậm đà với thịt cá trắng ngọt săn chắc, nước dùng thanh nhẹ hòa quyện vị chua dịu từ me chín, ngọt thanh của dứa chín và rau củ giòn tươi.', 'vietnamese', 25, 4, 'medium', 'https://images.unsplash.com/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=800&q=80', '["Món canh","Nam Bộ","Thanh nhiệt","Cá tươi","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-canh-02', 'canh-cua-dong-rau-day-mong-toi', 'Canh cua đồng rau đay mồng tơi mướp hương', 'Bát canh cua đồng thanh mát chuẩn vị Bắc Bộ với phần riêu cua kết mảng dày béo thơm, gạch cua chưng vàng óng quyện cùng rau đay, mồng tơi mềm mướt và mướp hương ngọt dịu.', 'vietnamese', 20, 4, 'medium', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món canh","Miền Bắc","Mùa hè","Cua đồng","Cơm nhà"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-canh-03', 'canh-kho-qua-nhoi-thit', 'Canh khổ qua nhồi thịt thanh mát', 'Món canh truyền thống thanh mát với từng khoanh khổ qua xanh mềm vừa phải, giảm hẳn vị đắng gắt, bao bọc nhân thịt heo xay đậm đà giòn sần sật mộc nhĩ cùng nước canh ngọt dịu.', 'vietnamese', 30, 4, 'medium', 'https://images.unsplash.com/photo-1603105037880-880cd4edfb0d?auto=format&fit=crop&w=800&q=80', '["Món canh","Nam Bộ","Thanh nhiệt","Truyền thống","Cơm nhà"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-canh-04', 'canh-suon-bi-dao', 'Canh sườn hầm bí đao ngọt thanh', 'Món canh gia đình quen thuộc với nước hầm sườn non trong veo, thịt sườn mềm tơi thấm vị, kết hợp bí đao chín tới trong mướt, giữ trọn vị ngọt mát và thanh nhẹ.', 'vietnamese', 35, 4, 'easy', 'https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=800&q=80', '["Món canh","Cơm nhà","Bổ dưỡng","Thanh mát","Dễ nấu"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-canh-05', 'canh-bi-do-thit-bam', 'Canh bí đỏ thịt bằm hạt sen', 'Tô canh vàng óng bắt mắt với từng miếng bí đỏ mềm bùi tan nhẹ, hạt sen bở thơm quyện cùng thịt heo băm xào tơi đậm đà và mùi thơm dịu của hành lá, ngò gai.', 'vietnamese', 22, 4, 'easy', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Món canh","Bổ dưỡng","Cơm nhà","Trẻ em thích","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-canh-06', 'canh-ngao-nau-chua-thi-la', 'Canh ngao nấu chua thì là', 'Món canh giải nhiệt thanh đạm quen thuộc trong mâm cơm miền Bắc với phần nước luộc ngao trong vắt ngọt tự nhiên, chua dịu hài hòa từ dứa và cà chua cùng mùi thơm quyến rũ của thì là.', 'vietnamese', 20, 4, 'easy', 'https://images.unsplash.com/photo-1534939561126-855b8675edd7?auto=format&fit=crop&w=800&q=80', '["Món canh","Miền Bắc","Hải sản","Thanh mát","Dễ nấu"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-kho-01', 'thit-kho-trung', 'Thịt kho tàu nước dừa trứng gà', 'Nồi thịt kho tàu Nam Bộ mềm rệu với phần mỡ trong veo không ngấy, thịt nạc thấm vị mặn ngọt hài hòa từ nước dừa tươi và nước mắm ngon, quyện cùng trứng gà bùi thơm.', 'vietnamese', 65, 4, 'medium', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', '["Món kho","Nam Bộ","Cơm nhà","Món Tết","Thịt heo"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-kho-02', 'ca-loc-kho-to-tieu-den', 'Cá lóc kho tộ tiêu đen', 'Khứa cá lóc đồng chắc thịt thấm đẫm nước sốt kho sánh bóng màu cánh gián, béo thơm tóp mỡ rán giòn, cay ấm vị ớt hiểm và tiêu đen xay.', 'vietnamese', 35, 3, 'medium', 'https://images.unsplash.com/photo-1617093727343-374698b1b08d?auto=format&fit=crop&w=800&q=80', '["Món kho","Niêu đất","Nam Bộ","Cá lóc","Đậm đà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-kho-03', 'ga-ta-kho-gung-sa', 'Gà ta kho gừng sả', 'Thịt đùi gà ta giữ nguyên da dai giòn, từng thớ thịt thấm đẫm vị mặn ngọt hài hòa quyện mùi thơm cay ấm của gừng thái sợi và sả băm vàng ruộm.', 'vietnamese', 25, 4, 'easy', 'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=800&q=80', '["Món kho","Gà ta","Gừng sả","Ấm bụng","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-kho-04', 'suon-heo-xao-chua-ngot', 'Sườn heo xào chua ngọt', 'Từng dẻ sườn non chiên xém vàng quyện lớp sốt đỏ cam sánh mịn có vị chua thanh từ giấm gạo, ngọt dịu từ đường và cà chua chín, thịt mềm ngọt dễ tách xương.', 'vietnamese', 25, 4, 'medium', 'https://images.unsplash.com/photo-1529193591184-b1d58069ecdd?auto=format&fit=crop&w=800&q=80', '["Sườn non","Chua ngọt","Bắc Bộ","Đưa cơm","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-kho-05', 'tom-rim-man-ngot', 'Tôm rim mặn ngọt tỏi ớt', 'Tôm tươi giữ nguyên vỏ rang săn rồi rim kẹo với nước mắm ngon và đường thắng cánh gián, vị mặn ngọt hài hòa, thịt tôm săn chắc thơm mùi hành tỏi phi.', 'vietnamese', 15, 3, 'easy', 'https://images.unsplash.com/photo-1559742811-822873691df8?auto=format&fit=crop&w=800&q=80', '["Món rim","Hải sản","Nhanh gọn","Đưa cơm","Cơm nhà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-kho-06', 'thit-ba-chi-kho-cu-cai', 'Thịt ba chỉ kho củ cải trắng', 'Những miếng thịt ba chỉ đan xen nạc mỡ mềm tan hòa cùng từng khúc củ cải trắng thấm vị ngọt thanh và nước màu hổ phách đậm đà, cực kỳ hao cơm trong những ngày se lạnh.', 'vietnamese', 45, 4, 'easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=800&q=80', '["Món kho","Bắc Bộ","Mùa đông","Cơm nhà","Thịt heo"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-xao-01', 'rau-muong-xao-toi', 'Rau muống xào tỏi xanh giòn', 'Đĩa rau muống xào tỏi chuẩn vị cơm nhà với cọng rau xanh mướt không bị thâm đen, giòn ngọt tự nhiên quyện vị đậm đà của nước mắm ngon và hương tỏi phi vàng ruộm thơm lừng.', 'vietnamese', 8, 3, 'easy', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', '["Món xào","Rau xanh","Thanh đạm","Dưới 20 phút","Cơm nhà"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-xao-02', 'bo-xao-can-toi-hanh-tay', 'Bò xào cần tỏi hành tây mềm ngọt', 'Món bò xào cần tỏi hành tây kiểu Bắc đậm đà truyền thống với những lát thịt bò thăn mềm mọng, không hề bị dai, hòa quyện cùng sắc xanh giòn của cần tây, tỏi tây và vị ngọt thanh từ hành tây, cà chua.', 'vietnamese', 12, 3, 'easy', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=800&q=80', '["Món xào","Thịt bò","Miền Bắc","Cơm nhà","Giàu đạm"]', 18, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-xao-03', 'muc-xao-can-toi-dua', 'Mực ống xào cần tỏi dứa chua ngọt', 'Món mực ống xào cần tỏi dứa hài hòa sắc màu đỏ cam của cà chua, vàng tươi của dứa chín và xanh mướt của cần tỏi tây. Từng miếng mực giòn ngọt sần sật, thấm vị nước mắm thơm ngon mà không hề bị tanh hay ra nước.', 'vietnamese', 12, 3, 'medium', 'https://images.unsplash.com/photo-1535400255456-984241443b29?auto=format&fit=crop&w=800&q=80', '["Món xào","Hải sản","Chua ngọt","Đãi khách","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-xao-04', 'thit-bo-xao-bong-cai', 'Thịt bò xào bông cải xanh cà rốt', 'Đĩa thịt bò xào bông cải xanh cà rốt bắt mắt với sắc xanh ngọc của súp lơ, cam tươi của cà rốt và lát thịt bò mềm mọng nước thấm sốt dầu hào, vừa thanh mát giàu chất xơ vừa đủ đạm cho bữa cơm gia đình.', 'vietnamese', 12, 3, 'easy', 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', '["Món xào","Thịt bò","Rau xanh","Giàu chất xơ","Cơm nhà"]', 18, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-xao-05', 'su-su-xao-trung-ga', 'Su su xào trứng gà thanh ngọt', 'Su su xào trứng gà là món xào mộc mạc quen thuộc của mâm cơm miền Bắc. Từng sợi su su giữ được độ giòn ngọt thanh mát quyện cùng lớp trứng gà tơi mềm vàng óng và hương thơm dịu của hành lá, ngò rí.', 'vietnamese', 10, 3, 'easy', 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=800&q=80', '["Món xào","Rau củ","Tiết kiệm","Dưới 20 phút","Miền Bắc"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-xao-06', 'dau-cove-xao-thit-bo', 'Đậu cô ve xào thịt bò giòn ngọt', 'Đậu cô ve xào thịt bò là món xào kinh điển của bữa cơm Việt với những khúc đậu giòn sần sật, xanh mướt không bị hăng kết hợp cùng lát thịt thăn bò mềm ngọt đậm vị tỏi phi và dầu hào.', 'vietnamese', 12, 3, 'easy', 'https://images.unsplash.com/photo-1550547660-d9450f859349?auto=format&fit=crop&w=800&q=80', '["Món xào","Thịt bò","Rau xanh","Dưới 20 phút","Cơm nhà"]', 18, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chien-01', 'dau-phu-sot-ca-chua', 'Đậu phụ lướt ván sốt cà chua', 'Đậu phụ lướt ván sốt cà chua là món cơm nhà dân dã quen thuộc khắp ba miền. Miếng đậu phụ trắng được thấm khô và chiên nhanh lửa vừa để lớp vỏ vàng mỏng giòn nhẹ, ruột vẫn mềm béo, sau đó om dịu trong sốt cà chua chín đỏ đậm vị nước mắm và hành lá.', 'vietnamese', 15, 3, 'easy', 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chiên","Đậu phụ","Cơm nhà","Tiết kiệm","Dưới 30 phút"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chien-02', 'trung-chien-thit-bam-nam-rom', 'Trứng chiên thịt bằm nấm rơm', 'Trứng chiên thịt bằm nấm rơm là món ăn nhanh giàu dinh dưỡng rất được yêu thích trong bữa cơm gia đình Việt. Nhân thịt bằm và nấm rơm được xào ráo nước trước khi hòa cùng hỗn hợp trứng gà đánh sữa tươi và chút dầu mè, giúp miếng trứng chiên phồng dày, thơm béo mà không bị chảy nước.', 'vietnamese', 12, 3, 'easy', 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=800&q=80', '["Món chiên","Trứng chiên","Nhanh gọn","Cơm nhà","Dưới 30 phút"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chien-03', 'canh-ga-chien-nuoc-mam', 'Cánh gà chiên nước mắm tỏi ớt', 'Cánh gà chiên nước mắm tỏi ớt là món khoái khẩu của cả trẻ nhỏ lẫn người lớn nhờ lớp da vàng giòn rụm bên ngoài, thịt gà bên trong vẫn giữ độ mọng mềm không khô bã, quyện sốt nước mắm tỏi ớt cân bằng vị mặn, ngọt, cay nhẹ rất bắt cơm.', 'vietnamese', 25, 4, 'medium', 'https://images.unsplash.com/photo-1527477396000-e27163b481c2?auto=format&fit=crop&w=800&q=80', '["Món chiên","Cánh gà","Món nhậu","Trẻ em thích","Đậm đà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chien-04', 'cha-ca-hai-phong', 'Chả cá chiên thì là hạt tiêu', 'Chả cá chiên thì là hạt tiêu mang hương vị đặc trưng của ẩm thực vùng duyên hải Bắc Bộ. Thịt cá tươi được giữ lạnh rồi quết nhuyễn cùng thịt nạc vai và mỡ heo hạt lựu, hòa quyện hương thơm nồng nàn của rau thì là tươi và hạt tiêu xay, tạo nên từng miếng chả vàng phồng dai giòn hấp dẫn.', 'vietnamese', 15, 4, 'medium', 'https://images.unsplash.com/photo-1534766555764-ce878a5e3a2b?auto=format&fit=crop&w=800&q=80', '["Món chiên","Chả cá","Bắc Bộ","Hải sản","Đặc sản"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chien-05', 'nem-ran-truyen-thong-ha-noi', 'Nem rán truyền thống Hà Nội', 'Nem rán truyền thống Hà Nội là món ăn tinh hoa không thể thiếu trong mâm cỗ ngày Tết và bữa cơm sum họp. Nhân nem kết hợp hài hòa thịt nạc vai xay, tôm tươi, mộc nhĩ, nấm hương, miến dong cùng củ đậu, cà rốt, su hào và lòng đỏ trứng, gói bằng bánh đa nem phết nước giấm loãng rồi rán hai lửa để vỏ giòn lâu.', 'vietnamese', 25, 4, 'hard', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', '["Món chiên","Nem rán","Hà Nội","Truyền thống","Tiệc tùng"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chien-06', 'ca-ro-phi-chien-gion-mam-gung', 'Cá rô phi chiên giòn chấm mắm gừng', 'Cá rô phi chiên giòn chấm mắm gừng là món ăn quen thuộc trong mâm cơm Việt nhờ nguyên liệu bình dân nhưng cực kỳ đưa cơm. Cá được làm sạch kỹ màng đen, khía sâu thân, áo lớp bột mì mỏng pha gia vị rồi chiên lửa vừa cho lớp da phồng giòn rụm, thịt cá bên trong vẫn mềm ngọt tự nhiên.', 'vietnamese', 20, 4, 'easy', 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?auto=format&fit=crop&w=800&q=80', '["Món chiên","Cá tươi","Cơm nhà","Dễ làm","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-hap-01', 'ga-ta-hap-la-chanh', 'Gà ta hấp lá chanh da giòn thịt ngọt', 'Gà ta hấp cách thủy giữ trọn vị ngọt thanh tự nhiên của thịt săn chắc, lớp da vàng óng giòn sần sật, thấm đẫm hương thơm ấm nồng từ sả cây, gừng tươi và lá chanh bánh tẻ.', 'vietnamese', 30, 4, 'medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=800&q=80', '["Món hấp","Gà ta","Thanh đạm","Đãi tiệc","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-hap-02', 'thit-ba-chi-luoc-mam-tom', 'Thịt ba chỉ luộc chấm mắm tôm cà pháo', 'Thịt ba chỉ rút sườn nạc mỡ đan xen luộc chín tới giữ được độ trắng ngần và giòn sần sật phần bì, ăn kèm cà pháo muối giòn tan, rau sống mát lành và bát mắm tôm chanh ớt đánh bông thơm lừng.', 'vietnamese', 25, 4, 'easy', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80', '["Món luộc","Cơm nhà","Món Bắc","Thanh đạm","Kinh điển"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-hap-03', 'ca-dieu-hong-hap-hanh-gung', 'Cá điêu hồng hấp hành gừng xì dầu', 'Cá điêu hồng nguyên con làm sạch kỹ hấp cách thủy vừa chín tới cho thớ thịt trắng ngần ngọt dịu, hòa quyện sốt xì dầu dầu hào sánh nhẹ cùng hương thơm nồng nàn của gừng sợi, hành lá và nấm hương.', 'vietnamese', 25, 4, 'medium', 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=800&q=80', '["Món hấp","Cá tươi","Đãi khách","Thanh đạm","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-hap-04', 'rau-cu-luoc-kho-quet', 'Rau củ luộc thập cẩm chấm kho quẹt tóp mỡ', 'Đĩa rau củ luộc giòn ngọt giữ trọn sắc xanh cam tươi tắn chấm ngập trong niêu kho quẹt sánh kẹo mặn ngọt hài hòa, thơm lừng tóp mỡ giòn rụm, tôm khô dai ngọt và tiêu xanh cay nồng.', 'vietnamese', 25, 4, 'easy', 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=800&q=80', '["Món luộc","Rau củ","Kho quẹt","Món Nam","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-hap-05', 'muc-hap-gung-sa', 'Mực ống hấp gừng sả giòn ngọt', 'Mực ống tươi làm sạch khéo léo hấp cách thủy lửa lớn cùng sả cây, gừng non và lá chanh, từng miếng mực trắng ngần giòn sần sật, mọng nước tự nhiên, thơm dịu không hề tanh.', 'vietnamese', 12, 3, 'easy', 'https://images.unsplash.com/photo-1535400255456-984241443b29?auto=format&fit=crop&w=800&q=80', '["Món hấp","Hải sản","Dưới 20 phút","Miền Trung","Tươi ngọt"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-hap-06', 'tom-hap-nuoc-dua-tuoi', 'Tôm sú hấp nước dừa tươi ngọt lịm', 'Tôm sú tươi sống hấp trực tiếp trong nước dừa xiêm ngọt thanh cùng sả cây và gừng lát giúp vỏ tôm lên màu đỏ cam bắt mắt, thịt tôm săn chắc giòn ngọt và thấm vị dừa dịu mát đặc trưng miền Tây.', 'vietnamese', 10, 3, 'easy', 'https://images.unsplash.com/photo-1559742811-822873691df8?auto=format&fit=crop&w=800&q=80', '["Món hấp","Hải sản","Dưới 20 phút","Đặc sản Nam Bộ","Đãi tiệc"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-cuon-01', 'goi-cuon-tom-thit-nam-bo', 'Gỏi cuốn tôm thịt chấm tương phộng Nam Bộ', 'Gỏi cuốn tôm thịt Nam Bộ hấp dẫn với lớp bánh tráng mỏng dai bọc trọn tôm sú đỏ au, thịt ba chỉ luộc thái mỏng, bún tươi, dưa leo giòn mát và hẹ lá xanh, chấm cùng chén tương đen bơ đậu phộng thơm bùi sánh mịn.', 'vietnamese', 20, 4, 'medium', 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=800&q=80', '["Món cuốn","Nam Bộ","Thanh mát","Khai vị","Tương đậu phộng"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-cuon-02', 'pho-cuon-bo-ha-noi', 'Phở cuốn bò xào rau thơm Hà Nội', 'Phở cuốn bò xào rau thơm mang đậm phong vị phố Trúc Bạch Hà Nội với lá bánh phở tươi trắng mượt ôm lấy thịt bò thăn xào tỏi mềm ngọt, quyện cùng xà lách giòn tươi, húng Láng thơm nồng và bát nước mắm dưa góp đu đủ cà rốt chua ngọt thanh tao.', 'vietnamese', 10, 3, 'easy', 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', '["Phở cuốn","Hà Nội","Thịt bò","Khai vị","Món cuốn"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-cuon-03', 'nom-hoa-chuoi-tai-heo', 'Nộm hoa chuối tai heo giòn sần sật', 'Nộm hoa chuối tai heo là món khai vị truyền thống miền Bắc với từng sợi hoa chuối trắng muốt không chát thâm, kết hợp tai heo luộc giòn sần sật, rau củ thanh mát, nước mắm chanh tỏi ớt đậm đà cùng lạc rang và hành phi thơm nức.', 'vietnamese', 20, 4, 'medium', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', '["Món nộm","Khai vị","Giòn sần sật","Miền Bắc","Chống ngán"]', 30, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-cuon-04', 'goi-ga-xe-phay-bap-cai', 'Gỏi gà xé phay bắp cải hành tây', 'Gỏi gà xé phay bắp cải hành tây hài hòa giữa thịt gà ta luộc dai ngọt xé sợi, bắp cải trắng bào mỏng giòn rụm, hành tây ngâm giấm đá dịu hăng và hương thơm đặc trưng của rau răm, lá chanh thái chỉ cùng nước trộn chua ngọt vừa vặn.', 'vietnamese', 25, 4, 'easy', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', '["Gỏi gà","Miền Trung","Thanh mát","Khai vị","Đãi tiệc"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-cuon-05', 'nom-du-du-bo-kho', 'Nộm đu đủ bò khô phố cổ Hà Nội', 'Nộm đu đủ bò khô mang nét đặc trưng ẩm thực phố cổ Hà Nội với sợi đu đủ xanh và cà rốt giòn tan không chát, thấm đẫm nước trộn mắm chanh chua ngọt dịu cay, kết hợp thịt bò khô xé sợi thơm lừng, rau kinh giới và lạc rang bùi ngậy.', 'vietnamese', 10, 3, 'easy', 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món nộm","Phố cổ Hà Nội","Đu đủ xanh","Ăn vặt","Khai vị"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-cuon-06', 'nem-lui-hue-nuong-sa', 'Nem lụi Huế nướng sả cuốn bánh tráng', 'Nem lụi Huế nướng sả thơm nức với lớp nhân thịt nạc vai xay, giò sống và tôm tươi quết dẻo bọc quanh thân sả nướng xém cạnh, quét mật ong dầu điều bóng đẹp, cuốn bánh tráng cùng bún tươi, chuối chát, dứa thơm và rau sống.', 'vietnamese', 30, 4, 'medium', 'https://images.unsplash.com/photo-1529193591184-b1d58069ecdd?auto=format&fit=crop&w=800&q=80', '["Nem lụi Huế","Món nướng","Món cuốn","Miền Trung","Đặc sản"]', 40, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-bun-01', 'pho-bo-tai-lan-ha-noi', 'Phở bò tái lăn Hà Nội', 'Phở bò tái lăn chuẩn vị Hà Nội nổi bật với thịt thăn bò ướp tỏi gừng xào nhanh trên lửa lớn cho mặt thịt săn thơm xém cạnh, hòa cùng nước dùng ninh xương ống bò quyện hương thảo mộc nướng.', 'vietnamese', 180, 4, 'hard', 'https://images.unsplash.com/photo-1582878826629-29b7ad1cdc43?auto=format&fit=crop&w=800&q=80', '["Phở bò","Hà Nội","Nước dùng ninh xương","Bữa sáng"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-bun-02', 'bun-cha-ha-noi-than-hoa', 'Bún chả nướng than hoa Hà Nội', 'Bún chả Hà Nội chuẩn vị với thịt ba chỉ thái miếng và thịt nạc vai xay nặn viên ướp đậm nước cốt sả hành, mắm tôm và nước hàng, nướng than hoa xém cạnh thơm lừng, ăn cùng nước mắm pha ấm, dưa góp giòn và rau sống.', 'vietnamese', 35, 4, 'medium', 'https://images.unsplash.com/photo-1569058242253-92a9c755a0ec?auto=format&fit=crop&w=800&q=80', '["Bún chả","Hà Nội","Món nướng","Đặc sản miền Bắc"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-bun-03', 'bun-bo-hue-chuan-vi', 'Bún bò Huế giò heo chả cua', 'Tô bún bò Huế trứ danh có nước dùng trong veo ánh sắc cam đẹp mắt từ dầu màu điều và sa tế sả ớt, hòa quyện vị thanh ngọt của xương bò giò heo cùng mùi thơm nồng đặc trưng của mắm ruốc Huế.', 'vietnamese', 120, 4, 'hard', 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80', '["Bún bò Huế","Ẩm thực miền Trung","Cay nồng","Món nước"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-bun-04', 'bun-rieu-cua-dong', 'Bún riêu cua đồng bắp bò giấm bỗng', 'Bún riêu cua đồng truyền thống miền Bắc có phần riêu cua đóng tảng xốp mềm, nước dùng đỏ cam tự nhiên từ gạch cua xào cà chua, dậy vị chua thanh từ giấm bỗng và cơm mẻ ăn cùng thịt bò chần mềm và đậu phụ rán vàng.', 'vietnamese', 35, 4, 'medium', 'https://images.unsplash.com/photo-1552611052-33e04de081de?auto=format&fit=crop&w=800&q=80', '["Bún riêu","Cua đồng","Miền Bắc","Món nước"]', 30, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-bun-05', 'bun-thit-nuong-nam-bo', 'Bún thịt nướng Nam Bộ chả giò mỡ hành', 'Tô bún thịt nướng Nam Bộ đầy đặn sắc màu với thịt nạc dăm nướng sả mật ong mềm thơm, chả giò cuốn thịt heo giòn tan, đồ chua củ cải cà rốt, mỡ hành xanh mướt và chén nước mắm tỏi ớt chua ngọt sánh vị.', 'vietnamese', 30, 4, 'medium', 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', '["Bún thịt nướng","Nam Bộ","Chả giò","Món trộn"]', 40, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-bun-06', 'mien-ga-nam-huong', 'Miến gà nấm hương mộc nhĩ', 'Tô miến gà nấm hương mộc nhĩ thanh tao chuẩn vị Bắc có nước dùng trong veo ngọt tự nhiên từ gà ta luộc cùng gừng hành nướng, kết hợp sợi miến dong dai mịn và thịt gà xé xào nấm thơm nức.', 'vietnamese', 45, 4, 'easy', 'https://images.unsplash.com/photo-1612927601601-6638404737ce?auto=format&fit=crop&w=800&q=80', '["Miến gà","Nấm hương","Món nước thanh nhẹ","Ẩm thực miền Bắc"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chay-01', 'dau-phu-kho-nam-dong-co', 'Đậu phụ kho nấm đông cô tiêu đen', 'Đậu phụ chiên vàng giòn bên ngoài nhưng giữ trọn độ mềm béo bên trong, kho liu riu cùng nấm đông cô tươi giòn ngọt trong phần nước sốt tương sánh bóng, thơm lừng hành boa-rô, dầu mè và tiêu đen cay nồng.', 'vietnamese', 20, 3, 'easy', 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chay","Món kho","Đậu phụ","Nấm đông cô","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chay-02', 'canh-nam-hat-sen-tao-do', 'Canh nấm hạt sen táo đỏ thanh lọc', 'Bát canh chay thanh mát giàu dưỡng chất với nước dùng trong veo ngọt dịu tự nhiên từ củ sen giòn bùi, bắp ngọt, cà rốt và táo đỏ, kết hợp hạt sen ninh mềm tơi cùng nấm đùi gà và nấm kim châm giòn sần sật.', 'vietnamese', 30, 4, 'easy', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món chay","Món canh","Thanh lọc","Hạt sen","Bổ dưỡng"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chay-03', 'mi-xao-chay-rau-nam', 'Mì xào giòn chay nấm rau củ', 'Đĩa mì xào giòn chay hấp dẫn với sợi mì vàng chiên phồng giòn tan, không ngấm dầu, kết hợp phần nhân xào nóng hổi gồm nấm đùi gà dai ngọt, cải ngọt xanh mướt, cà rốt giòn sần sật hòa quyện trong lớp sốt dầu hào chay sánh bóng.', 'vietnamese', 15, 3, 'medium', 'https://images.unsplash.com/photo-1585032226651-759b368d7246?auto=format&fit=crop&w=800&q=80', '["Món chay","Mì xào giòn","Nấm đùi gà","Rau củ","Đổi vị"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chay-04', 'ca-tim-nuong-mo-hanh', 'Cà tím nướng mỡ hành nước tương tỏi ớt', 'Món cà tím nướng mỡ hành dân dã chuẩn vị Nam Bộ với phần thịt cà trắng mềm mọng ngọt tự nhiên, thơm nhẹ hương khói, phủ lớp mỡ hành xanh bóng béo ngậy, rưới sốt nước tương tỏi ớt chua mặn ngọt hài hòa và đậu phộng rang giòn bùi.', 'vietnamese', 25, 3, 'easy', 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=800&q=80', '["Món chay","Nam Bộ","Món nướng","Cà tím","Dân dã"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chay-05', 'dau-hu-non-sot-nam-rom', 'Đậu hũ non sốt nấm rơm dầu hào chay', 'Từng khoanh đậu hũ non hấp nóng giữ trọn độ mềm mịn tan ngay đầu lưỡi, kết hợp phần sốt nấm rơm búp giòn ngọt được xào thơm với hành tím, tỏi băm cùng dầu hào chay và nước tương đậm đà sánh bóng.', 'vietnamese', 15, 3, 'easy', 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chay","Đậu hũ non","Nấm rơm","Mềm mịn","Nhanh gọn"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-chay-06', 'canh-cai-nau-dau-phu-non', 'Canh cải xanh gừng đậu phụ thanh mát', 'Bát canh cải bẹ xanh thanh đạm mà ấm bụng với vị hăng ngọt dịu nhẹ đặc trưng của rau cải non, hòa quyện hương gừng già cay thơm nồng giúp làm ấm cơ thể cùng những miếng đậu phụ trắng béo mềm thấm vị.', 'vietnamese', 12, 4, 'easy', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Món chay","Món canh","Cải bẹ xanh","Ấm bụng","Dưới 20 phút"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-sang-01', 'com-chien-trung-toi-hanh-hoa', 'Cơm chiên trứng tỏi phi hành hoa', 'Đĩa cơm chiên trứng tỏi phi vàng ươm với từng hạt cơm săn tơi rời rạc, áo lớp trứng gà mượt mà, thơm nức hương tỏi phi giòn tan, hành lá xanh mát và nước mắm dậy mùi.', 'vietnamese', 12, 2, 'easy', 'https://images.unsplash.com/photo-1603133872878-684f208fb84b?auto=format&fit=crop&w=800&q=80', '["Ăn sáng","Cơm chiên","Nhanh gọn","Tiết kiệm","Cơm nhà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-sang-02', 'banh-mi-op-la-pate', 'Bánh mì ốp la pate dưa leo', 'Món sáng quốc dân chuẩn vị quán Việt với hai ổ bánh mì nóng giòn, lớp pate gan mịn béo phủ đều ruột bánh, trứng gà ốp la lòng đào chiên bơ thơm ngậy cùng dưa leo giòn mát, ngò rí, xì dầu và tương ớt cay dịu.', 'vietnamese', 8, 2, 'easy', 'https://images.unsplash.com/photo-1626804475297-41608ea09aeb?auto=format&fit=crop&w=800&q=80', '["Bánh mì","Ăn sáng","Nhanh gọn","Quốc dân","Dưới 20 phút"]', 6, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-sang-03', 'chao-thit-bam-gung-tia-to', 'Cháo thịt bằm gừng tía tô giải cảm', 'Tô cháo thịt bằm nóng hổi với hạt gạo tẻ kết hợp gạo nếp rang thơm nở bung sánh mịn, thịt heo nạc băm mềm ngọt không vón cục, hòa quyện hương cay ấm của gừng già, tiêu đen và lá tía tô giải cảm hiệu quả.', 'vietnamese', 25, 3, 'easy', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Cháo nóng","Giải cảm","Ăn sáng","Ấm bụng","Dễ tiêu"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-sang-04', 'mi-tom-xao-bo-trung-long-dao', 'Mì gói xào bò trứng lòng đào', 'Món mì xào bò trứng lòng đào hấp dẫn với từng sợi mì săn dai không bết dính, thịt bò thăn xào tái mềm đậm đà nước tương dầu hào, rau cải ngọt giòn xanh và quả trứng ốp la lòng đào tan chảy béo mượt.', 'vietnamese', 12, 2, 'easy', 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80', '["Mì xào","Ăn nhanh","Dưới 20 phút","Bò xào","Sinh viên"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-sang-05', 'trung-cuon-rau-cu-han-quoc', 'Trứng cuộn rau củ mềm mịn', 'Món trứng cuộn rau củ mềm mịn từng lớp, vàng ươm bắt mắt điểm xuyết màu cam tươi của cà rốt, xanh non của hành lá và vị ngọt dịu từ hành tây cùng sữa tươi không đường.', 'vietnamese', 10, 2, 'easy', 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=800&q=80', '["Trứng cuộn","Ăn sáng","Dưới 20 phút","Giàu đạm","Bé thích"]', 8, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-sang-06', 'sup-ga-ngo-non-nam-huong', 'Súp gà ngô non nấm hương trứng hoa', 'Nồi súp gà ngô non nấm hương nóng hổi sánh nhẹ óng ả với vị ngọt tự nhiên từ ức gà ta luộc xé sợi và hạt ngô ngọt, thơm nồng hương nấm hương khô, điểm xuyết những dải vân trứng hoa mềm mượt, dầu mè và tiêu trắng.', 'vietnamese', 20, 4, 'easy', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Súp nóng","Ăn sáng","Khai vị","Thanh nhẹ","Dễ tiêu"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-lau-01', 'lau-rieu-cua-dong-bap-bo-suon-sun', 'Lẩu riêu cua đồng sườn sụn bắp bò', 'Lẩu riêu cua đồng sườn sụn bắp bò là đặc sản trứ danh đất Bắc. Nước lẩu chua thanh thơm nức mùi giấm bỗng và mắm tôm, nổi bật với lớp riêu cua đồng vàng ươm béo bùi, kết hợp sườn sụn ninh mềm giòn, bắp bò hoa thái mỏng, đậu phụ rán vàng và rổ rau sống tươi mát.', 'vietnamese', 45, 6, 'hard', 'https://images.unsplash.com/photo-1547928576-a4a33237cbc3?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Riêu cua đồng","Bắc Bộ","Bắp bò","Tiệc gia đình"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-lau-02', 'lau-ga-la-giang-chua-cay', 'Lẩu gà ta lá giang chua cay Nam Bộ', 'Lẩu gà ta lá giang là món lẩu đặc sản Nam Bộ rất được ưa chuộng trong những bữa tiệc sum họp hay ngày mưa se lạnh. Nước dùng hầm từ thịt gà ta ngọt đậm, kết hợp vị chua thanh tự nhiên của lá giang vò dập cùng hương thơm sả, ớt hiểm và ngò gai, rau ngổ.', 'vietnamese', 40, 5, 'medium', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Gà ta","Lá giang","Nam Bộ","Chua cay"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-lau-03', 'lau-hai-san-thap-cam-chua-cay', 'Lẩu hải sản tôm mực chua cay', 'Lẩu hải sản tôm mực chua cay có nồi nước dùng sóng sánh màu đỏ cam hấp dẫn, hòa quyện hương thơm nồng nàn của sả, riềng, lá chanh cùng vị chua thanh của me chín và dứa. Hải sản tươi sống nhúng vừa chín tới giữ trọn độ giòn ngọt mọng nước.', 'vietnamese', 35, 5, 'medium', 'https://images.unsplash.com/photo-1547928576-a4a33237cbc3?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Hải sản","Tôm mực","Chua cay","Tiệc gia đình"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-lau-04', 'lau-nam-thap-cam-thanh-dam', 'Lẩu nấm thập cẩm gà ta thanh đạm', 'Lẩu nấm thập cẩm gà ta là món lẩu thanh đạm, ít dầu mỡ và giàu dưỡng chất. Nước lẩu ngọt tự nhiên từ xương ống, gà ta thả vườn kết hợp bắp ngọt, củ cải, cà rốt và vị thảo mộc nhẹ của táo đỏ kỷ tử, tôn lên độ giòn ngọt tinh tế của các loại nấm tươi.', 'vietnamese', 45, 5, 'medium', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Lẩu nấm","Gà ta","Thanh đạm","Bổ dưỡng"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('vn-lau-05', 'lau-ca-thac-lac-kho-qua', 'Lẩu cá thác lác khổ qua thanh mát', 'Lẩu cá thác lác khổ qua là món ăn giải nhiệt đặc sắc của miền Nam. Nước lẩu hầm từ xương heo cùng hành tây và cà rốt ngọt thanh trong veo, kết hợp những viên chả cá thác lác quết dai sần sật và từng lát khổ qua ướp lạnh bào mỏng giòn rụm dịu đắng.', 'vietnamese', 35, 4, 'medium', 'https://images.unsplash.com/photo-1603105037880-880cd4edfb0d?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Cá thác lác","Khổ qua","Nam Bộ","Thanh mát"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-01', 'pasta-pomodoro', 'Mì Ý sốt cà chua Pomodoro', 'Mì Ý sốt cà chua Pomodoro là biểu tượng tối giản của ẩm thực Ý với vị chua ngọt tự nhiên từ cà chua chín lột vỏ ninh chậm, thơm dịu tỏi phi dầu ô liu nguyên chất và lá húng quế Tây tươi mát.', 'italian', 25, 2, 'easy', '/frigo/recipes/global/pasta-pomodoro.webp', '["Món Ý","Mì Ý","Sốt cà chua","Thanh đạm","Nấu nhanh"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-02', 'mapo-tofu', 'Đậu phụ sốt Mapo Tofu Tứ Xuyên', 'Đậu phụ sốt Mapo Tofu Tứ Xuyên nổi tiếng với sự kết hợp hài hòa giữa đậu phụ non béo mịn, thịt heo xay săn thơm và lớp sốt đỏ óng từ tương ớt đậu bản, đậu tương đen lên men cùng hoa tiêu tê nồng.', 'chinese', 20, 4, 'medium', '/frigo/recipes/global/mapo-tofu.webp', '["Tứ Xuyên","Cay tê","Đậu phụ","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-03', 'tomato-egg-stir-fry', 'Cà chua xào trứng kiểu Trung Hoa', 'Cà chua xào trứng kiểu Trung Hoa là món ăn gia đình kinh điển với lớp trứng chiên tơi xốp ngấm trọn nước sốt cà chua đỏ sánh, vị chua ngọt dịu nhẹ và mùi thơm thoang thoảng của dầu mè cùng rượu Thiệu Hưng.', 'chinese', 10, 2, 'easy', '/frigo/recipes/global/tomato-egg-stir-fry.webp', '["Trung Hoa","Nhanh gọn","Cà chua trứng","Cơm nhà"]', 8, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-04', 'oyakodon', 'Cơm gà trứng Oyakodon Nhật Bản', 'Oyakodon là món cơm tô gia đình quen thuộc của Nhật Bản, kết hợp thịt đùi gà cắt miếng vừa ăn nấu cùng hành tây ngọt mềm trong nước dùng dashi đậm vị xì dầu và rượu ngọt mirin, phủ lớp trứng đánh nhẹ chín tới mịn mượt.', 'japanese', 15, 2, 'easy', '/frigo/recipes/global/oyakodon.webp', '["Nhật Bản","Cơm donburi","Thịt gà","Nhanh gọn","Bữa trưa"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-05', 'kimchi-fried-rice', 'Cơm chiên kim chi Hàn Quốc', 'Cơm chiên kim chi Hàn Quốc là món ăn nhanh gọn nhưng tròn vị nhờ sự kết hợp giữa cơm nguội hạt săn tơi, kim chi cải thảo ủ chua giòn sần sật và sốt tương ớt Gochujang cay ngọt hài hòa. Lớp trứng ốp la lòng đào bên trên giúp món ăn thêm béo thơm hấp dẫn.', 'korean', 15, 2, 'easy', '/frigo/recipes/global/kimchi-fried-rice.webp', '["Hàn Quốc","Món nhanh","Chua cay","Cơm chiên","Bữa sáng"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-06', 'pad-krapow', 'Thịt heo băm xào lá quế kiểu Thái (Pad Krapow)', 'Pad Krapow là món cơm đĩa đường phố trứ danh của Thái Lan với thịt heo băm xào săn trên lửa lớn cùng tỏi ớt giã dập, đậu que giòn ngọt, sốt nước tương đậm đà và lá húng quế thơm nồng.', 'thai', 12, 2, 'easy', '/frigo/recipes/global/pad-krapow.webp', '["Thái Lan","Món xào","Cay nồng","Cơm đĩa","Nhanh gọn"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-07', 'kimbap-han-quoc', 'Cơm cuộn Kimbap Hàn Quốc', 'Cơm cuộn Kimbap Hàn Quốc hài hòa sắc màu và dinh dưỡng với lớp cơm trắng trộn dầu mè thơm bùi, ôm trọn nhân thịt bò xào xì dầu, trứng gà rán vàng, rau chân vịt chần, cà rốt giòn ngọt và thanh củ cải muối vàng chua dịu.', 'korean', 20, 3, 'easy', '/frigo/recipes/global/kimchi-fried-rice.webp', '["Hàn Quốc","Cơm cuộn","Dã ngoại","Meal prep","Rong biển"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-08', 'tokbokki-cay-ngot', 'Bánh gạo Tokbokki sốt cay ngọt', 'Bánh gạo Tokbokki sốt cay ngọt chuẩn vị đường phố Seoul với từng thỏi bánh gạo dẻo bùi thấm đẫm nước sốt Gochujang đỏ óng sánh mịn, hòa quyện vị ngọt thanh của bắp cải, chả cá mềm dai và trứng gà luộc béo bùi.', 'korean', 20, 2, 'easy', '/frigo/recipes/global/kimchi-fried-rice.webp', '["Hàn Quốc","Ăn vặt","Cay ngọt","Bánh gạo","Đường phố"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-09', 'chawanmushi', 'Trứng hấp Chawanmushi tôm nấm Nhật Bản', 'Chawanmushi là món trứng hấp khai vị tinh tế của ẩm thực Nhật Bản, nổi bật với kết cấu custard mịn màng không rỗ bọt khí nhờ tỷ lệ trứng và nước dùng dashi chuẩn xác cùng kỹ thuật hấp lửa nhỏ cách thủy.', 'japanese', 25, 2, 'easy', '/frigo/recipes/global/oyakodon.webp', '["Nhật Bản","Món hấp","Thanh đạm","Hải sản","Bữa tối nhẹ"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-10', 'thai-green-curry', 'Cà ri xanh thịt gà kiểu Thái (Green Curry)', 'Cà ri xanh (Kaeng Khiao Wan) nổi bật với màu xanh ngọc tự nhiên của ớt xanh và rau thơm, nước sốt cốt dừa tách dầu béo mịn quyện cùng đùi gà mềm ngọt, cà tím và hương lá chanh Thái.', 'thai', 25, 3, 'medium', '/frigo/recipes/global/pad-krapow.webp', '["Thái Lan","Cà ri","Cốt dừa","Cay nồng","Món om"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-11', 'spaghetti-bolognese', 'Mì Ý sốt bò bằm Bolognese', 'Món mì Ý sốt bò bằm Bolognese chuẩn vị với nền rau củ cà rốt, cần tây, hành tây xào ngọt, kết hợp thịt bò xay và ba chỉ xông khói hầm chậm cùng sốt cà chua Passata, rượu vang trắng và sữa tươi tạo độ béo mượt tròn vị.', 'italian', 60, 3, 'medium', '/frigo/recipes/global/carbonara.webp', '["Món Ý","Mì Ý","Thịt bò bằm","Sốt cà chua","Gia đình"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('gl-12', 'chinese-tomato-egg', 'Trứng xào cà chua sốt tương kiểu Quảng Đông', 'Khác với phiên bản truyền thống dùng muối và rượu Thiệu Hưng, trứng xào cà chua kiểu Quảng Đông kết hợp sữa tươi giúp miếng trứng mềm mịn như kem, quyện cùng nước sốt đậm vị từ tương cà, xì dầu nhạt, dầu hào và gừng thơm.', 'chinese', 12, 2, 'easy', '/frigo/recipes/vietnam/dau-phu-sot-ca-chua.webp', '["Quảng Đông","Nhanh gọn","Cà chua trứng","Cơm nhà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-199ff78d3d8c8ab3', 'canh-bi-do-nau-tom-tuoi-ngot-nuoc', 'Canh bí đỏ nấu tôm tươi ngọt nước', 'Món canh dân dã Nam Bộ có màu vàng cam đẹp mắt, vị bùi ngọt tự nhiên của bí đỏ hòa cùng nước ngọt thanh từ đầu tôm ninh kỹ và thịt tôm tươi săn giòn.', 'vietnamese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Bổ dưỡng","Cơm nhà","Dễ nấu"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ab36e38b07f3a57b', 'suon-non-kho-dua-chua-ngot-dam-vi', 'Sườn non kho dứa chua ngọt', 'Từng dẻ sườn non thấm đẫm nước cốt dứa tự nhiên giúp thịt nhanh mềm ngọt, kết hợp cùng miếng dứa xào chín dịu vị chua và nước sốt kho cánh gián sánh bóng.', 'vietnamese', 45, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món kho","Sườn non","Nam Bộ","Chua ngọt","Đưa cơm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-26a36c69306143bc', 'tom-xao-bong-cai-xanh-toi-gion-ngot', 'Tôm xào bông cải xanh tỏi giòn ngọt', 'Tôm tươi lột vỏ rút chỉ xào nhanh lửa lớn giữ được độ ngọt giòn săn chắc, kết hợp cùng bông cải xanh chần sốc nhiệt giòn mát và lớp sốt bột bắp óng ả thơm mùi tỏi phi.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Rau xanh","Dưới 20 phút","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b87b71d57128cc07', 'ca-loc-chien-sa-ot-vang-gion', 'Cá lóc chiên sả ớt vàng giòn', 'Cá lóc chiên sả ớt vàng giòn là món ăn đậm chất miền Tây Nam Bộ, hấp dẫn bởi lớp vỏ ngoài vàng óng màu nghệ và giòn tan quyện sả tỏi phi thơm nức, trong khi thớ thịt cá lóc bên trong vẫn trắng ngọt, săn chắc.', 'vietnamese', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Cá lóc","Nam Bộ","Sả ớt","Đưa cơm"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-511a92d180408e0a', 'trung-hap-thit-bam-nam-huong-mem-min', 'Trứng hấp thịt bằm nấm hương mềm mịn', 'Món trứng hấp thịt bằm nấm hương béo bùi nhưng thanh nhẹ, bề mặt mịn mượt không bị rỗ nhờ lọc rây kỹ và hấp lửa nhỏ, kết hợp vị ngọt đậm của thịt heo xay cùng hương nấm đông cô đặc trưng.', 'vietnamese', 22, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Trẻ em thích","Thanh đạm","Cơm nhà","Dễ nấu"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d02c9b83214f81be', 'goi-dua-leo-tom-thit-gion-mat', 'Gỏi dưa leo tôm thịt giòn mát', 'Gỏi dưa leo tôm thịt là món khai vị thanh mát đặc trưng Nam Bộ với từng lát dưa leo xanh giòn không chảy nước, kết hợp thịt ba chỉ luộc mềm, tôm rim đỏ cam săn ngọt và nước trộn mắm chanh tương ớt chua cay mặn ngọt hài hòa.', 'vietnamese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi dưa leo","Khai vị","Giải ngán","Nam Bộ","Tôm thịt"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9ae951bec7fbf21b', 'hu-tieu-xao-tom-gia-he-kieu-sai-gon', 'Hủ tiếu xào tôm giá hẹ kiểu Sài Gòn', 'Món hủ tiếu xào tôm giá hẹ mang đậm phong vị quán ăn Sài Gòn với sợi hủ tiếu tơi mềm không bết dính, áo màu nâu cánh gián bóng bẩy từ nước tương và dầu hào, kết hợp tôm sú giòn ngọt cùng giá hẹ tươi mát.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hủ tiếu xào","Sài Gòn","Món nhanh","Hải sản"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-5ab5c1053b7371f0', 'dau-phu-chien-sa-ot-chay-dam-da', 'Đậu phụ chiên sả ớt chay đậm đà', 'Đậu phụ trắng chiên vàng giòn bên ngoài nhưng vẫn mềm béo bên trong, xóc đều cùng sả băm, tỏi và ớt tươi phi thơm với nước tương đậm đà, tạo nên món mặn chay dân dã dậy hương sả ớt vô cùng đưa cơm.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Đậu phụ","Chiên sả ớt","Đậm vị","Đưa cơm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-67054d03e5a5b011', 'chao-trung-ga-hanh-la-gung-am-bung', 'Cháo trứng gà hành lá gừng ấm bụng', 'Bát cháo trứng gà nóng hổi với hạt gạo tẻ nấu nhừ sánh quyện, vân trứng gà mềm mịn không tanh, nổi bật hương cay ấm dịu của gừng tươi thái chỉ, hành lá xanh mát và chút dầu mè.', 'vietnamese', 20, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cháo trứng","Ăn sáng","Dưới 20 phút","Dễ tiêu","Ấm bụng"]', 5, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e375595daced53af', 'lau-bo-nhung-dua-chua-thanh', 'Lẩu bò nhúng dứa chua thanh', 'Lẩu bò nhúng dứa chua thanh mang phong vị phóng khoáng của ẩm thực Nam Bộ. Nước dùng kết hợp nước dừa tươi ngọt dịu, dứa chín, cà chua và chút giấm gạo tạo vị chua thanh rất dễ chịu, dùng nhúng thịt thăn bò thái mỏng cuốn cùng bánh tráng, rau sống và chấm mắm nêm đậm đà.', 'vietnamese', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Bò nhúng","Dứa chín","Nam Bộ","Cuốn bánh tráng"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9b4ea97916a44e67', 'canh-rau-muong-nau-tom-thanh-mat', 'Canh rau muống nấu tôm thanh mát', 'Món canh mùa hè thanh mát đậm chất cơm nhà Bắc Bộ với từng cọng rau muống xanh giòn, nước dùng trong ngọt thanh vị tôm tươi giã nhuyễn và mùi thơm dịu nhẹ của hành tím phi.', 'vietnamese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Dưới 20 phút","Thanh mát","Cơm nhà"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6d7fc503ade5df6e', 'thit-ba-chi-xao-sa-ot-kieu-mien-trung', 'Thịt ba chỉ xào sả ớt kiểu miền Trung', 'Thịt ba chỉ xào sả ớt kiểu miền Trung hấp dẫn với phần thịt ba chỉ săn giòn xém cạnh không hề ngấy mỡ, thấm đẫm hương thơm nồng nàn của sả băm, vị cay bùng nổ từ ớt tươi và mặn ngọt hài hòa của nước mắm ngon.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt heo","Miền Trung","Cay nồng","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-364497296cfcf033', 'muc-nhoi-thit-hap-gung-hanh', 'Mực nhồi thịt hấp gừng hành', 'Những khoanh mực ống trắng giòn ôm trọn phần nhân thịt heo xay dẻo ngọt quyện hương nấm hương, hành tím và gừng thơm nồng; món hấp thanh nhẹ nhưng đậm đà, đẹp mắt cho mâm cơm gia đình lẫn tiệc đãi khách.', 'vietnamese', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Hải sản","Đãi khách","Thanh đạm","Miền Trung"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-806780abda4b5205', 'com-chien-dua-tom-hai-san', 'Cơm chiên dứa tôm hải sản', 'Món cơm chiên dứa hải sản Nam Bộ rực rỡ sắc màu với từng hạt cơm tơi vàng ươm hương bột cà ri dịu, tôm tươi và mực giòn ngọt, dứa chín mọng nước cân bằng vị cùng hạt điều rang bùi béo.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Hải sản","Nam Bộ","Ăn sáng","Dứa thơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a48b19224e397cea', 'com-bo-hanh-tay-gyudon-kieu-nhat', 'Cơm bò hành tây Gyudon kiểu Nhật', 'Gyudon là món cơm bò quốc dân của Nhật Bản với những lát thịt bò có vân mỡ mỏng tang được om nhanh cùng hành tây thái múi trong sốt xì dầu, rượu sake, mirin và dashi thanh ngọt.', 'japanese', 20, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Cơm donburi","Thịt bò","Nhanh gọn","Bữa trưa"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-79819e1b0c75f4da', 'mi-udon-xao-thit-heo-bap-cai-yaki-udon', 'Mì Udon xào thịt ba chỉ bắp cải Yaki Udon', 'Yaki Udon là món mì xào trứ danh của ẩm thực đường phố Nhật Bản với sợi mì udon dày mềm dai quyện vị béo thơm của thịt ba chỉ, rau củ tươi giòn và nước sốt xì dầu pha rượu mirin, sake cùng cá bào katsuobushi.', 'japanese', 18, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Mì xào","Yaki Udon","Thịt ba chỉ","Bữa tối"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ac255bcc36d1324e', 'ca-hoi-ap-chao-sot-teriyaki-bong-dep', 'Cá hồi áp chảo sốt Teriyaki kiểu Nhật', 'Cá hồi phi lê còn da được phủ nhẹ lớp bột mì giữ trọn nước ngọt bên trong, áp chảo mặt da giòn vàng với bơ lạt rồi rim nhanh trong sốt Teriyaki tự pha từ nước tương Nhật, rượu mirin, sake và đường.', 'japanese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Cá hồi","Teriyaki","Áp chảo","Bổ dưỡng"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-bb07db73fb381724', 'dau-phu-lanh-hiyayakko-gung-hanh', 'Đậu phụ non lạnh Hiyayakko gừng hành', 'Hiyayakko là món đậu phụ lạnh truyền thống ngày hè của Nhật Bản, giữ trọn vị béo mát nguyên bản của đậu phụ non kết hợp cùng gừng mài cay ấm, hành lá giòn thơm và nước tương pha dầu mè thanh dịu.', 'japanese', 1, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Khai vị","Không cần nấu","Đậu phụ","Thanh mát"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a9398d96945ba6f7', 'canh-kim-chi-dau-phu-thit-ba-chi-kimchi-jjigae', 'Canh kim chi đậu phụ thịt ba chỉ (Kimchi Jjigae)', 'Canh kim chi đậu phụ thịt ba chỉ (Kimchi Jjigae) là món canh hầm quốc dân xứ Hàn với nước dùng đỏ rực sóng sánh vị chua thanh từ kim chi ủ kỹ, béo ngọt từ thịt ba chỉ xào săn và mềm mịn tan nhẹ của từng miếng đậu phụ.', 'korean', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Kim chi","Ấm bụng","Cay đậm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-af8a9cdb17d5e9fd', 'bo-xao-bulgogi-hanh-tay-ca-rot', 'Bò xào Bulgogi hành tây cà rốt', 'Bò xào Bulgogi hành tây cà rốt là món mặn trứ danh của ẩm thực Hàn Quốc với từng lát thịt bò thăn mềm mọng thấm gia vị mặn ngọt hài hòa từ nước tương, đường nâu, rượu ngọt Mirin và dầu mè rang, xào cùng hành tây cà rốt giòn thanh.', 'korean', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món xào","Thịt bò","Bulgogi","Đưa cơm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d3d0c59e0cfa845d', 'banh-kim-chi-chien-kimchi-jeon-gion-rum', 'Bánh kim chi chiên giòn (Kimchi Jeon)', 'Bánh kim chi chiên giòn (Kimchi Jeon) là món bánh dân dã nhưng cực kỳ bắt miệng của Hàn Quốc với lớp bột pha nước lạnh giòn rụm bên ngoài, bên trong đậm vị chua cay của kim chi cải thảo chín, hành tây và hành lá thơm nồng.', 'korean', 20, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món chiên","Kim chi","Ăn vặt","Giòn rụm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-262caf09e6f38c59', 'bong-cai-xanh-xao-toi-kieu-quang-dong', 'Bông cải xanh xào tỏi kiểu Quảng Đông', 'Bông cải xanh xào tỏi kiểu Quảng Đông giữ trọn độ giòn ngọt tự nhiên và màu xanh mướt nhờ kỹ thuật chần nước sôi trước khi xào nhanh trên lửa lớn cùng tỏi băm, gừng thơm và lớp sốt xì dầu sánh nhẹ.', 'chinese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Rau xanh","Xào tỏi","Thanh nhẹ"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-352999f711c710d9', 'ga-xao-gung-hanh-kieu-quang-dong', 'Gà xào gừng hành kiểu Quảng Đông', 'Gà xào gừng hành kiểu Quảng Đông sử dụng thịt đùi gà lọc xương ướp kỹ thuật giữ ẩm, áp chảo xém thơm rồi quyện cùng hương gừng già cay ấm, hành lá giòn ngọt và nước sốt xì dầu dầu hào sánh óng.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Thịt gà","Gừng hành","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b3f99919ea9f17f8', 'canh-bi-dao-thit-bam-kieu-hoa', 'Canh bí đao thịt bằm viên kiểu Hoa', 'Canh bí đao thịt bằm viên kiểu Hoa mang vị thanh tao, nước dùng trong ngọt từ nước dùng gà hòa quyện bí đao mềm mọng và viên thịt heo quết một chiều dai ngọt tự nhiên.', 'chinese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Thanh mát","Trung Hoa","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b6dae711698259d6', 'canh-tom-chua-cay-tom-yum-kieu-thai', 'Canh tôm chua cay Tom Yum kiểu Thái', 'Tom Yum Goong là món canh quốc hồn quốc túy của Thái Lan với nước dùng chiết xuất từ vỏ đầu tôm phi thơm cùng bộ ba thảo mộc sả, riềng, lá chanh Kaffir và vị chua cay bừng vị.', 'thai', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Tom Yum","Chua cay","Hải sản"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f729957329cd75f5', 'mi-xao-pad-thai-tom-gia-do', 'Mì xào Pad Thai tôm giá đỗ', 'Pad Thai chuẩn vị với sự hòa quyện tinh tế giữa sợi bánh phở gạo dai mềm, sốt me chua ngọt nấu từ đường thốt nốt, tôm áp chảo săn ngọt, đậu phụ chiên vàng, trứng gà đánh tơi cùng giá đỗ và hẹ tươi.', 'thai', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad Thai","Mì xào","Hải sản","Chua ngọt"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-04d0b94d17ce080c', 'ga-xao-gung-nam-kieu-thai-gai-pad-khing', 'Gà xào gừng nấm kiểu Thái (Gai Pad Khing)', 'Gai Pad Khing là món xào gia đình thanh đạm nhưng rất bắt cơm của Thái Lan, kết hợp thịt ức gà mềm mọng với hương cay ấm của gừng tươi thái sợi chỉ, vị ngọt tự nhiên từ nấm hương và hành tây giòn nhẹ.', 'thai', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món xào","Ức gà","Gừng nấm","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b01569fd0df22f66', 'mi-y-aglio-e-olio-toi-ot-dau-olive', 'Mì Ý Aglio e Olio tỏi ớt dầu ô liu', 'Mì Ý Aglio e Olio là món mì đêm khuya kinh điển của người Ý chỉ dùng những nguyên liệu mộc mạc nhất: tỏi lát phi vàng dịu trong dầu ô liu nguyên chất, chút ớt sừng cay nhẹ và nước luộc mì giàu tinh bột tạo lớp sốt óng mượt.', 'italian', 15, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Aglio e Olio","Dưới 30 phút","Tối giản"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d463228be1e6e7c0', 'com-risotto-nam-bo-pho-mai-beo-ngay', 'Cơm Risotto nấm bơ phô mai béo ngậy', 'Cơm Risotto nấm bơ phô mai là món cơm kem đặc trưng của miền Bắc nước Ý. Hạt gạo Arborio hạt tròn giàu tinh bột được rang nhẹ rồi om từng vá nước dùng rau củ nóng, hòa quyện vị ngọt umami từ nấm áp chảo và độ béo mịn của bơ lạnh, phô mai Parmesan.', 'italian', 30, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Cơm Risotto","Nấm tươi","Bơ phô mai","Ấm bụng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4)
INSERT INTO recipes (id, slug, title, description, cuisine, cook_time_minutes, servings, difficulty, image_url, tags, prep_time_minutes, source_type, source_reference, verification_state, version) VALUES
('imp-9d575ec5c01896f0', 'mi-y-sot-kem-ca-hoi-rau-bina', 'Mì Ý sốt kem cá hồi rau bina', 'Mì Ý sốt kem cá hồi rau bina mang đến sự cân bằng tinh tế giữa phi lê cá hồi áp chảo béo ngọt, sốt kem tươi sánh mịn thơm mùi phô mai Parmesan và rau bina tươi mát cùng chút vỏ và nước cốt chanh vàng dịu nhẹ.', 'italian', 25, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Cá hồi","Rau bina","Sốt kem"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-810c132a4d2cd4e0', 'canh-chua-tom-dua-nam-bo', 'Canh chua tôm dứa Nam Bộ', 'Tô canh chua tôm Nam Bộ bắt mắt với sắc đỏ cà chua, vàng dứa, xanh mướt của đậu bắp, dọc mùng và vị chua thanh ngọt dịu từ nước cốt me quyện tôm tươi săn giòn.', 'vietnamese', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Chua ngọt","Thanh nhiệt","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-59015074541ba061', 'canh-kho-qua-nhoi-tom', 'Canh khổ qua nhồi tôm thịt', 'Phiên bản nâng tầm của canh khổ qua nhồi truyền thống với phần nhân kết hợp thịt heo xay béo mềm và tôm tươi băm dai ngọt, điểm xuyết nấm hương thơm bùi trong nước canh thanh trong.', 'vietnamese', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Thanh nhiệt","Hải sản","Cơm nhà"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9c678f92a5cb0812', 'canh-bi-dao-tom-tuoi', 'Canh bí đao nấu tôm tươi', 'Món canh giải nhiệt nhẹ nhàng với miếng bí đao vừa chín tới giữ nguyên độ thanh ngọt, hòa quyện thịt tôm tươi băm săn mềm và hương hành tím phi dịu nhẹ.', 'vietnamese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Thanh mát","Dễ nấu","Cơm nhà"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-80ce5736becc08da', 'canh-ca-chua-trung-nha-la', 'Canh cà chua trứng (Canh mây)', 'Món canh dân dã nhanh gọn với nước dùng chua thanh tự nhiên từ cà chua chín xào mềm, nổi bật những dải vân trứng gà mềm mịn vàng ươm và mùi thơm tươi của hành lá, ngò rí.', 'vietnamese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Dưới 20 phút","Dễ nấu","Cơm nhà","Thanh đạm"]', 8, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9473faeacd64d970', 'canh-nam-ga-xe-soi', 'Canh nấm đùi gà ức gà xé sợi', 'Tô canh thanh đạm giàu đạm nhưng nhẹ bụng với nước dùng nấu trực tiếp từ thịt ức gà xào săn, nấm đùi gà xé sợi giòn ngọt tự nhiên và sắc cam tươi của cà rốt.', 'vietnamese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Không xương","Giàu đạm","Dễ nấu","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9ab5767266722397', 'canh-muc-ca-chua-chua-nhe', 'Canh mực cà chua chua nhẹ', 'Món canh biển thanh nhẹ dễ nấu với từng khoanh mực ống giòn sần sật, nước canh ánh đỏ cam từ cà chua xào mềm, dậy hương gừng thái sợi ấm áp và chút chanh tươi chua dịu.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Hải sản","Dưới 20 phút","Dễ nấu","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-61eac17e8f3042a9', 'canh-su-su-bam-thit', 'Canh su su nấu thịt bằm', 'Tô canh su su băm thịt dân dã có nước dùng ngọt trong, thịt heo băm tơi thơm mùi hành phi hòa quyện cùng từng miếng su su non chín tới giữ nguyên độ giòn ngọt mát lành.', 'vietnamese', 18, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Trung","Dễ nấu","Thanh mát","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ad2b55ed85f0d109', 'canh-bap-cai-trung-cuon', 'Canh bắp cải trứng cuộn', 'Món canh gia đình thanh đạm dễ ăn với những sợi bắp cải xanh mướt giòn ngọt tự nhiên, điểm xuyết lát cà rốt cam tươi và những vân trứng gà vàng óng mềm mượt.', 'vietnamese', 12, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Thanh đạm","Dễ nấu","Cơm nhà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-7cfc6a2e9d8bf8a3', 'canh-rau-muong-tom-dong', 'Canh rau muống nấu tôm đồng cà chua', 'Món canh dân dã mang hương vị đồng quê với phần nước dùng ánh đỏ cam dịu nhẹ từ cà chua xào mềm, ngọt thanh đậm vị tôm đồng giã thô cùng từng cọng rau muống xanh mướt giòn ngon.', 'vietnamese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Đồng quê","Dễ nấu","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-24cdd0b61f9ed162', 'canh-cua-dong-dau-phu', 'Canh riêu cua đồng đậu phụ cà chua', 'Món canh riêu cua đậu phụ đậm hương vị đồng bằng Bắc Bộ với phần nước canh chua thanh nhẹ của me và cà chua, từng miếng đậu phụ rán vàng thấm vị quyện mảng riêu cua ngọt béo và rau răm dậy mùi.', 'vietnamese', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Cua đồng","Truyền thống","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-15155ec6cc7b7713', 'ba-chi-nuong-sa-mat-ong', 'Ba chỉ nướng sả mật ong', 'Những dải thịt ba chỉ nạc mỡ hài hòa thấm đẫm hương thơm sả băm, hành tỏi gừng và vị ngọt dịu của mật ong, nướng chín vàng ruộm xém cạnh bên ngoài mà vẫn mềm mọng bên trong.', 'vietnamese', 30, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Ba chỉ nướng","Mật ong","Sả ớt","Cuối tuần","Cuốn bánh tráng"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-363ca9ee2c5f7738', 'bo-kho-banh-mi-dam-vi', 'Bò kho bánh mì đậm vị', 'Thịt nạm bò có gân mỡ đan xen được hầm nhừ cùng nước dừa tươi, cà rốt, sả, hoa hồi, quế thanh và màu điều đỏ cam sóng sánh, tỏa mùi thơm quyến rũ khó cưỡng.', 'vietnamese', 75, 5, 'medium', '/frigo/illustrations/delicious-meal.png', '["Bò kho","Bánh mì","Nam Bộ","Món hầm","Ăn sáng"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3ec27a2b8f5e4345', 'ga-kho-gung-ot-hiem', 'Gà kho gừng ớt hiểm', 'Những miếng đùi gà giữ nguyên da săn chắc thấm đẫm vị mặn ngọt hài hòa, quyện cùng hương thơm cay ấm của gừng tươi thái sợi và vị cay nồng đặc trưng từ ớt hiểm.', 'vietnamese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt gà","Gừng ớt","Đưa cơm","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-323aae415415eb28', 'tom-kho-tieu-xanh', 'Tôm kho tiêu xanh', 'Tôm tươi rang săn rồi kho mở nắp với nước mắm đường và những chùm tiêu xanh tươi đập dập, mang lại vị cay tê dịu nhẹ và hương thơm tinh dầu tiêu đặc trưng miền Nam.', 'vietnamese', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món kho","Hải sản","Tiêu xanh","Nhanh gọn","Nam Bộ"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3f1ad35e1f1ec87f', 'muc-rim-dua-mien-trung', 'Mực rim dứa miền Trung', 'Đặc sản miền Trung với từng thớ mực khô nướng thơm đập mềm thấm đẫm sốt dứa chín chua ngọt quyện tương ớt cay nồng, dầu hào đậm đà và mè rang bùi béo.', 'vietnamese', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món rim","Miền Trung","Hải sản","Mực khô","Đưa cơm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-64e505d497388f4a', 'ca-hoi-ap-chao-toi-chanh', 'Cá hồi áp chảo sốt tỏi chanh', 'Cá hồi áp chảo sốt tỏi chanh là sự kết hợp tinh tế giữa kỹ thuật áp chảo da giòn kiểu Âu và hương vị sốt bơ tỏi chanh pha nước mắm hài hòa theo khẩu vị Việt. Miếng cá giữ được độ béo mọng đặc trưng bên trong, hòa quyện lớp sốt chua thanh thơm lừng giúp ăn không bị ngấy.', 'vietnamese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Áp chảo","Cá hồi","Nhanh gọn","Hiện đại"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6e4c264764981b8b', 'ga-xao-sa-ot-non', 'Gà xào sả ớt Nam Bộ', 'Gà xào sả ớt kiểu Nam Bộ quyến rũ với màu nâu cánh gián óng ả từ đường nâu thắng nhẹ, từng miếng thịt đùi gà mềm ngọt thấm sâu hương sả thơm nồng, vị cay kích thích của ớt hiểm và chút giòn ngọt của hành tây.', 'vietnamese', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Nam Bộ","Cay nồng","Đưa cơm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-53760c13ec1e452b', 'tom-xao-gia-do', 'Tôm xào giá đỗ thanh ngọt', 'Tôm xào giá đỗ là món ăn thanh nhẹ giải ngấy cực nhanh gọn cho bữa cơm hằng ngày. Từng con tôm đỏ cam săn chắc quyện cùng cọng giá đỗ chín tới giòn tan, mọng nước ngọt tự nhiên mà không hề bị nát hay chảy nước.', 'vietnamese', 8, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Thanh đạm","Dưới 20 phút","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a47ef9289f5d0136', 'ca-rot-xao-trung', 'Cà rốt xào trứng gà', 'Cà rốt xào trứng gà là món ăn bình dị, giàu dinh dưỡng với sợi cà rốt mềm ngọt tự nhiên ôm quyện lấy từng mảng trứng gà vàng óng béo nhẹ, thơm mùi nước mắm, tiêu xay và rau ngò rí.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau củ","Trứng","Dưới 20 phút","Cơm nhà"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-abdcd797955a6d6a', 'dau-phu-xao-ca-chua', 'Đậu phụ xào cà chua', 'Đậu phụ xào cà chua hấp dẫn với từng miếng đậu phụ ngoài vàng nhẹ, bên trong béo mềm thấm đẫm phần sốt cà chua đỏ au sóng sánh vị chua ngọt hài hòa, thơm mùi hành lá và ngò rí.', 'vietnamese', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Đậu phụ","Cà chua","Tiết kiệm","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-97f26ff4abe44f9b', 'nem-ran-nhan-cua-thit', 'Nem rán nhân cua thịt', 'Nem rán nhân cua thịt (nem cua bể) là đặc sản trứ danh miền duyên hải Bắc Bộ. Từng chiếc nem gói vuông vức, lớp vỏ bánh đa nem giòn tan ôm trọn phần nhân đầy đặn gồm thịt cua biển tươi, thịt nạc vai xay, nấm hương, mộc nhĩ, miến dong và các loại củ bào sợi ngọt mát.', 'vietnamese', 25, 6, 'hard', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Nem cua bể","Bắc Bộ","Hải sản","Tiệc tùng"]', 40, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-03cb4c492e643034', 'tom-chien-trung-mong', 'Tôm chiên trứng mỏng', 'Tôm chiên trứng mỏng là món ăn đơn giản nhưng rất được lòng trẻ nhỏ và gia đình bận rộn. Tôm tươi bóc vỏ được xào nhanh cho chín đỏ rồi trải đều trên lớp trứng gà đánh cùng chút bột bắp hòa nước, chiên lửa nhỏ đậy vung để mặt trứng mềm mịn, không bị khô xác.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Tôm tươi","Trứng chiên","Trẻ em thích","Dưới 30 phút"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-c4a65718d5cd4b3c', 'cha-gio-chay-nam-dau', 'Chả giò chay nấm đậu', 'Chả giò chay nấm đậu có lớp vỏ giòn tan không thua kém chả giò mặn nhờ bí quyết vắt ráo đậu phụ, hấp khô đậu xanh và chiên hai lần lửa. Nhân nấm đùi gà dai ngọt hòa quyện với đậu xanh bùi béo, khoai lang và củ đậu thanh mát, chấm nước mắm chay chua ngọt cực kỳ bắt vị.', 'vietnamese', 20, 5, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Món chay","Chả giò","Giòn rụm","Thanh đạm"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f3c2431be267b74d', 'ca-hap-dua-gung', 'Cá điêu hồng hấp dứa gừng thanh mát', 'Cá điêu hồng tươi hấp cách thủy cùng những lát dứa chín vàng óng và gừng sợi cay nhẹ tạo nên nước hấp chua ngọt thanh tao, giúp thịt cá trắng mềm thơm ngọt mà hoàn toàn không có vị tanh.', 'vietnamese', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Cá tươi","Thanh mát","Món Nam","Đãi khách"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6118e8aa010584af', 'trung-hap-tom-chung', 'Trứng hấp tôm chưng mềm mượt', 'Món trứng hấp tôm chưng mềm mịn như đậu hũ non, mặt trứng bóng mượt không một vết rỗ hòa quyện vị ngọt tự nhiên của tôm tươi bóc vỏ và hương thơm dịu từ hành lá, dầu mè.', 'vietnamese', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Trứng","Thanh đạm","Dễ nấu","Nhẹ bụng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4ced29ad30507f2c', 'goi-cuon-tom-thit-rau-song', 'Gỏi cuốn tôm thịt rau sống chấm mắm tỏi ớt', 'Gỏi cuốn tôm thịt rau sống mang hương vị thanh nhẹ chuẩn Nam Bộ với bánh tráng mềm dẻo ôm trọn tôm luộc đỏ tươi, thịt ba chỉ béo mềm, bún sợi nhỏ, dưa leo giòn mát, hẹ lá và ngò gai thơm dịu, chấm cùng chén nước mắm chanh tỏi ớt đậm đà.', 'vietnamese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi cuốn","Rau sống","Nam Bộ","Nước mắm tỏi ớt","Khai vị"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3a06ac78b572f3ae', 'nom-dua-leo-tom-chua-cay', 'Nộm dưa leo tôm chua cay', 'Nộm dưa leo tôm chua cay là món khai vị bùng vị với dưa leo và cà rốt ngâm đá giữ trọn độ giòn mát, kết hợp tôm tươi rim muối ngọt thịt và nước mắm chanh tương ớt giã tỏi ớt hiểm cay nồng, rắc lạc rang thơm bùi.', 'vietnamese', 10, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nộm dưa leo","Tôm tươi","Chua cay","Khai vị","Mát lành"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-21f32dccd464c605', 'pho-ga-pho-co', 'Phở gà phố cổ Hà Nội', 'Phở gà phố cổ Hà Nội tinh tế với nước dùng trong vắt thơm hương hạt mùi rang, hành gừng nướng, thịt gà ta chín tới da vàng giòn ngọt mềm, điểm lá chanh thái chỉ thanh mát.', 'vietnamese', 80, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Phở gà","Phố cổ Hà Nội","Nước dùng trong","Bữa sáng"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ba737c5583985a50', 'bun-bo-hue-sa-ot', 'Bún bò Huế sả ớt', 'Bún bò Huế sả ớt phiên bản cay nồng thơm sả nổi bật với nạm bò ướp sả ớt xào săn trước khi hầm mềm, viên giò sống dai giòn, nước dùng đậm đà mắm ruốc Huế cùng chén sa tế sả ớt tự làm đỏ rực bắt mắt.', 'vietnamese', 120, 4, 'hard', '/frigo/illustrations/delicious-meal.png', '["Bún bò Huế","Sả ớt","Cay nồng","Ẩm thực miền Trung"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-37a39eaa1edcd2e4', 'hu-tieu-tom-thit-nam-vang', 'Hủ tiếu tôm thịt Nam Vang', 'Tô hủ tiếu Nam Vang trứ danh đất Sài Gòn gây thương nhớ bởi nồi nước lèo trong veo ngọt dịu từ xương heo hầm củ cải trắng, tôm khô và khô mực nướng, điểm xuyết tỏi phi vàng thơm cùng thịt ba chỉ, tôm tươi, thịt băm và trứng cút.', 'vietnamese', 90, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Hủ tiếu Nam Vang","Tôm thịt","Ẩm thực Nam Bộ","Bữa sáng"]', 30, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0efa407066cdc8dd', 'bun-ca-tom-ca-chua', 'Bún cá nấu dứa cà chua', 'Tô bún cá nấu dứa cà chua ấm bụng với từng khúc cá lóc ướp nghệ chiên áp chảo vàng nhẹ không tanh, thấm nước dùng chua thanh tự nhiên từ cà chua chín và dứa thơm.', 'vietnamese', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Bún cá","Cà chua","Chua thanh","Món nước"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b6aeb931b882e8a3', 'com-chay-dau-kho-nam', 'Cơm chay đậu phụ kho nấm đùi gà', 'Mâm cơm chay giản dị mà tròn vị với phần cơm trắng nấu chín dẻo thơm ăn kèm nồi đậu phụ chiên vàng kho cùng nấm đùi gà thái lát dày, ngấm đượm nước tương sánh đậm, thoảng vị cay ấm của tiêu xay và hành lá.', 'vietnamese', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Cơm nhà","Món kho","Đậu phụ","Nấm đùi gà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f0039d3d3f6299b3', 'nam-kho-dau-phu-tuong', 'Nấm đùi gà kho đậu phụ tương đậm vị', 'Đĩa nấm đùi gà kho đậu phụ thơm nồng quyến rũ với màu nâu cánh gián óng ả từ xì dầu đặc kết hợp nước tương và vị chua ngọt tự nhiên của cà chua chín, giúp từng lát nấm dai giòn và miếng đậu phụ mềm béo thấm trọn gia vị.', 'vietnamese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Món kho","Nấm đùi gà","Đậu phụ","Ngày rằm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e771ef1a49b2aeed', 'bong-cai-xao-nam-chay', 'Bông cải xanh xào nấm đùi gà chay', 'Đĩa rau xào chay đầy màu sắc với từng nhánh bông cải xanh mướt giòn sần sật, cà rốt ngọt thanh và nấm đùi gà thái lát dai giòn, được bao bọc bởi lớp nước sốt nước tương và bột bắp sánh mịn thơm mùi tỏi phi.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Món xào","Bông cải xanh","Nấm đùi gà","Thanh đạm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-43e806b28c7b8bb5', 'com-chien-tom-trung', 'Cơm chiên tôm trứng', 'Đĩa cơm chiên tôm trứng dân dã mà tròn vị với hạt cơm tơi rời bóng nhẹ, thịt tôm tươi săn ngọt đậm xì dầu nước mắm, trứng gà xốp vàng, cà rốt thái hạt lựu và giá đỗ giòn thanh giải ngấy.', 'vietnamese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Tôm trứng","Ăn nhanh","Dưới 20 phút","Cơm nhà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f92a1c569c245541', 'mi-xao-bo-rau-cu', 'Mì xào bò rau củ', 'Đĩa mì xào bò rau củ hài hòa dinh dưỡng với sợi mì vàng dai mềm không bết, thịt bò thăn xào tái mềm mọng nước quyện hương tỏi gừng và sốt xì dầu, dầu hào đậm đà, bắp cải, cà rốt cùng hành tây giòn ngọt.', 'vietnamese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì xào","Thịt bò","Rau củ","Ăn nhanh","Cơm nhà"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f4665d594d941e4a', 'chao-ga-gung-nong', 'Cháo gà gừng nóng', 'Nồi cháo gà gừng nóng hổi với nước dùng ngọt tự nhiên từ đùi gà ta luộc cùng gừng hành tím, hạt gạo tẻ kết hợp gạo nếp nở bung sánh mịn, thịt đùi gà xé phay mềm ngọt và gừng tươi thái chỉ ấm bụng.', 'vietnamese', 45, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cháo gà","Gừng ấm","Ăn sáng","Bồi bổ","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-35164fb31de89c5f', 'goi-ga-bap-cai-chanh', 'Gỏi gà bắp cải chanh', 'Đĩa gỏi gà bắp cải thanh mát với thịt ức gà ta luộc chín mềm không khô, sợi bắp cải trắng và cà rốt giòn sần sật, hành tây bớt hăng quyện cùng rau răm thơm nồng và nước mắm chanh tỏi ớt chua cay mặn ngọt.', 'vietnamese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi gà","Thanh mát","Ít dầu mỡ","Khai vị","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-368d91563cb1879b', 'lau-thai-tom-ca-mien-tay', 'Lẩu Thái tôm cá miền Tây', 'Lẩu Thái tôm cá miền Tây là sự kết hợp hài hòa giữa vị chua cay nồng nàn kiểu Thái với nguyên liệu tươi ngon vùng sông nước Nam Bộ. Nước dùng ninh xương ống ngọt sâu, thơm dậy mùi sả, riềng, lá chanh và sa tế tôm, làm nổi bật vị ngọt của tôm sú, cá diêu hồng và nấm tươi.', 'vietnamese', 45, 5, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Lẩu Thái","Tôm cá","Miền Tây","Chua cay"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-c52c790faf9281da', 'lau-nam-chay-dau-phu', 'Lẩu nấm chay đậu phụ', 'Lẩu nấm chay đậu phụ mang hương vị thanh tịnh và ngọt lành hoàn toàn từ rau củ và các loại nấm tươi. Nước lẩu thơm mùi hành boa-rô phi, ngọt dịu tự nhiên từ bắp ngọt và cà rốt, kết hợp đậu phụ trắng mềm, váng đậu giòn dai, bắp cải và nhiều loại nấm bổ dưỡng.', 'vietnamese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Món chay","Lẩu nấm","Đậu phụ","Thanh đạm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e9678cfa1bc90074', 'tom-xao-trung-ca-chua', 'Tôm xào trứng cà chua', 'Tôm xào trứng cà chua nâng tầm món trứng cà chua quen thuộc nhờ thịt tôm tươi săn giòn, kết hợp trứng gà đánh mềm xốp và phần sốt cà chua sóng sánh hài hòa vị chua ngọt mặn dịu.', 'chinese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Trung Hoa","Tôm trứng","Xào nhanh","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-387c41fb3a0c2297', 'ga-kung-pao-tu-xuyen', 'Gà Kung Pao Tứ Xuyên', 'Gà Kung Pao Tứ Xuyên chinh phục vị giác nhờ sự cân bằng tinh tế giữa vị cay tê của ớt khô và hoa tiêu, vị chua ngọt dịu đặc trưng từ giấm đen Trấn Giang cùng miếng thịt đùi gà mềm mọng và đậu phộng rang giòn bùi.', 'chinese', 15, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Tứ Xuyên","Kung Pao","Đậu phộng","Cay tê"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f5abd36e99d48d94', 'dau-phu-mapo-tu-xuyen', 'Đậu phụ Mapo Tứ Xuyên', 'Đậu phụ Mapo Tứ Xuyên phiên bản tự phi dầu ớt tươi và ớt khô trực tiếp tại bếp mang đến hương cay thơm bùng nổ, kết hợp thịt heo xay tơi đậm vị tương ớt đậu bản và đậu phụ non mềm tan.', 'chinese', 18, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Tứ Xuyên","Cay tê","Đậu phụ","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-242fd73cebd63651', 'suon-chua-ngot-quang-dong', 'Sườn om chua ngọt Quảng Đông', 'Sườn om chua ngọt Quảng Đông là món mặn trứ danh với từng khúc sườn non mềm róc xương, quyện lớp sốt đỏ bóng chua thanh của giấm gạo và tương cà, hòa cùng vị ngọt tươi từ dứa chín và cà chua.', 'chinese', 45, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Chua ngọt","Sườn heo","Tiệc nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-34f3eb2438125614', 'bap-cai-xao-toi-quang-dong', 'Bắp cải xào tỏi kiểu Quảng Đông', 'Bắp cải xào tỏi kiểu Quảng Đông nổi bật với từng lá bắp cải xé tay giòn sần sật, mép lá hơi xém cạnh thơm mùi chảo nóng, quyện vị mặn ngọt thanh nhẹ của xì dầu, rượu Thiệu Hưng và giấm đen Trấn Giang.', 'chinese', 8, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Bắp cải","Xào tỏi","Nhanh gọn"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2d508cd359edb61c', 'dau-phu-hap-tom-gung', 'Đậu phụ trứng hấp tôm gừng', 'Đậu phụ trứng hấp tôm gừng mang phong vị dim sum tinh tế với phần đậu phụ trứng béo mịn nâng đỡ viên chả tôm giòn ngọt tự nhiên, hoàn thiện bằng lớp sốt xì dầu dầu hào trong mượt và hương thơm ấm nồng của gừng hành.', 'chinese', 15, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Dim sum","Đậu phụ","Tôm tươi"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6eaf6ed6d417c52c', 'muc-chien-muoi-ot', 'Mực chiên giòn muối ớt kiểu Hồng Kông', 'Mực chiên giòn muối ớt kiểu Hồng Kông hấp dẫn với lớp vỏ ngoài xốp giòn vàng ruộm ôm trọn miếng mực tươi giòn ngọt bên trong, dậy mùi thơm bùng nổ của tỏi phi, gừng băm, ớt hiểm và hành lá.', 'chinese', 12, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Hồng Kông","Hải sản","Muối ớt"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d90dc5bbe2891a12', 'chao-thit-bam-gung', 'Cháo thịt bằm gừng trứng kiểu Quảng Đông', 'Cháo thịt bằm gừng trứng kiểu Quảng Đông là món ăn bổ dưỡng, ấm bụng với hạt gạo rang trước giúp cháo nhanh nhừ sánh mịn, hòa quyện thịt heo bằm tơi mềm, vân trứng gà óng ả và gừng tươi thái sợi giải cảm.', 'chinese', 40, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món cháo","Quảng Đông","Bữa sáng","Ấm bụng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b23ab24915e52866', 'com-chien-duong-chau', 'Cơm chiên Dương Châu', 'Cơm chiên Dương Châu chuẩn vị quán Quảng Đông nổi bật với hạt cơm săn tơi vàng ươm nhờ kỹ thuật trộn lòng đỏ trứng trước khi rang, kết hợp đầy đặn tôm tươi, thịt heo xay, lạp xưởng thơm béo và rau củ giòn ngọt.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Dương Châu","Cơm chiên","Quảng Đông","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e83f58ebb9b02fbd', 'mi-dan-dan-tu-xuyen', 'Mì Đan Đan Tứ Xuyên', 'Mì Đan Đan Tứ Xuyên là món mì trộn đường phố trứ danh, quy tụ hài hòa vị béo bùi của tương mè, vị cay tê bùng nổ từ dầu ớt và hoa tiêu, hòa quyện cùng sợi mì dai mượt, cải thìa chần giòn và thịt heo băm xào khô thơm lừng.', 'chinese', 15, 2, 'medium', '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Tứ Xuyên","Cay tê","Mì Đan Đan"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-04d477399e49fe8e', 'mi-xao-bo-quang-dong', 'Mì xào bò Quảng Đông', 'Mì xào bò Quảng Đông mang hương vị đặc trưng của món xào chảo nóng với sợi mì trứng tơi dai, thịt bò mềm mọng nhờ kỹ thuật ướp baking soda và bột bắp, hòa cùng giá đỗ, đậu giòn ngọt và nước sốt xì dầu bóng thơm.', 'chinese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Mì xào","Thịt bò","Lửa lớn"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a22f9257b0fd7a46', 'ba-chi-kho-dong-pha', 'Ba chỉ kho Đông Pha', 'Ba chỉ kho Đông Pha là tuyệt phẩm ẩm thực Giang Nam với từng khối thịt ba chỉ vuông vắn có lớp bì màu nâu hổ phách óng ả, phần mỡ trong mềm tan không ngấy nhờ được om chậm hàng giờ với rượu Thiệu Hưng, xì dầu và đường phèn.', 'chinese', 180, 5, 'hard', '/frigo/illustrations/delicious-meal.png', '["Đông Pha nhục","Trung Hoa","Món kho","Tiệc nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-5f8d0890bd6d0a76', 'vien-su-tu-dau-kho-cai', 'Viên Sư Tử Đầu kho cải thảo', 'Viên Sư Tử Đầu kho cải thảo là món ăn truyền thống vùng Hoài Dương nổi bật với những viên thịt heo cỡ lớn mềm tơi mọng nước xen lẫn củ năng giòn sần sật, được kho liu riu trên lớp cải thảo ngọt thanh cùng sốt xì dầu dầu hào sánh bóng.', 'chinese', 45, 4, 'hard', '/frigo/illustrations/delicious-meal.png', '["Sư tử đầu","Hoài Dương","Món kho","Tiệc nhà"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ece7da4660b63e9d', 'bo-xao-ca-chua-kieu-trung', 'Bò xào cà chua kiểu Trung', 'Món bò xào cà chua kiểu Trung nổi bật với từng lát thịt bò được xử lý mềm mượt hòa quyện trong phần sốt cà chua chín đỏ sánh bóng, chua ngọt hài hòa.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Cà chua","Trung Hoa","Đưa cơm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b9d222a8c523b8e4', 'dua-leo-dap-toi-tu-xuyen', 'Dưa leo đập tỏi Tứ Xuyên', 'Món khai vị lạnh trứ danh của ẩm thực Tứ Xuyên với từng miếng dưa leo đập dập giòn rụm, thấm sâu hỗn hợp giấm đen Trấn Giang, tỏi tươi, dầu mè thơm lừng và sa tế dầu ớt.', 'chinese', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món trộn","Tứ Xuyên","Khai vị","Dưa leo","Giải ngấy"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-51f6c12eefee914d', 'dau-phu-kho-bap-cai', 'Đậu phụ kho bắp cải', 'Món kho bình dân kiểu gia đình Trung Hoa kết hợp đậu phụ chiên vàng giòn vỏ ngoài, bắp cải giòn ngọt và nấm kim châm dai mềm thấm đẫm sốt nước tương sánh nhẹ.', 'chinese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món kho","Đậu phụ","Bắp cải","Thanh đạm","Trung Hoa"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6d3fa354c64cf8b1', 'ca-kho-tuong-dam', 'Cá kho tương đậm kiểu Trung', 'Món cá kho tàu trứ danh kiểu Trung Hoa không thêm nước mà om cá trực tiếp trong hỗn hợp rượu Thiệu Hưng, giấm đen Trấn Giang và xì dầu sánh bóng, giữ nguyên lớp da vàng giòn và thớ thịt trắng ngọt.', 'chinese', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món kho","Cá nguyên con","Trung Hoa","Đậm đà","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-03577e7fa7667ab8', 'canh-chua-cay-trung-hoa', 'Canh chua cay kiểu Trung Hoa', 'Món súp chua cay trứ danh của ẩm thực Trung Hoa với nước dùng gà sánh nhẹ, vân trứng gà tơ mềm, nấm đùi gà giòn ngọt, đậu phụ mềm mịn cùng vị chua thơm từ giấm đen và cay ấm của tiêu trắng.', 'chinese', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món canh","Chua cay","Trung Hoa","Khai vị","Ấm bụng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-62ebe8dd18b15b5e', 'muc-xao-gung-hanh', 'Mực xào gừng hành', 'Món mực xào gừng hành kiểu Quảng Đông giữ được độ giòn sần sật tự nhiên của từng miếng mực khía hoa nhờ kỹ thuật chần nhanh với gừng và xào đảo tốc độ trên lửa lớn.', 'chinese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Mực tươi","Quảng Đông","Nhanh gọn","Hải sản"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d283a9225d6ece09', 'com-ca-hoi-donburi', 'Cơm cá hồi ướp tương Donburi kiểu Nhật', 'Cơm cá hồi Zuke Donburi là món cơm tô nổi tiếng của Nhật với phi lê cá hồi tươi chuẩn sashimi thái lát mỏng, ướp thấm đẫm nước sốt xì dầu mirin thơm dầu mè, đặt lên lớp đệm hành tây thái mỏng trên nền cơm ấm.', 'japanese', 15, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Donburi","Cá hồi","Bữa trưa","Thanh mát"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-7ed24282981e96f6', 'thit-ba-chi-shogayaki-gung', 'Thịt ba chỉ áp chảo sốt gừng Shogayaki', 'Shogayaki là món thịt heo xào gừng quốc dân trong thực đơn teishoku Nhật Bản, nổi bật với từng lát thịt ba chỉ mềm thơm phủ sốt gừng tươi mài nhuyễn hòa quyện vị mặn ngọt từ nước tương, rượu sake và mirin.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Shogayaki","Thịt ba chỉ","Cơm trưa","Nhanh gọn"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-c6e706b483805e44', 'ba-chi-ham-kakuni', 'Thịt ba chỉ hầm Kakuni kiểu Nhật', 'Buta no Kakuni là món thịt ba chỉ hầm trứ danh vùng Nagasaki Nhật Bản. Thịt được áp chảo rút mỡ, ninh mềm trong nước gừng hành rồi mới om chậm cùng nước dùng dashi, rượu sake, mirin, đường và xì dầu cho đến khi từng thớ thịt mềm rục bóng mượt.', 'japanese', 150, 5, 'hard', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Kakuni","Thịt kho","Bữa tiệc","Hầm mềm"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-324e0ea2e2f068bf', 'canh-miso-dau-phu-nam', 'Canh Miso đậu phụ non và nấm', 'Canh Miso là món canh truyền thống không thể thiếu trong bữa cơm Nhật Bản. Nước dùng thanh ngọt từ tảo bẹ kombu hòa cùng tương miso thơm dịu, đậu phụ non cắt khối và nấm tươi tạo nên vị umami nhẹ nhàng ấm bụng.', 'japanese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Món canh","Canh Miso","Thanh đạm","Bữa sáng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-5507103398040565', 'mi-xao-yakisoba-rau-cu', 'Mì xào Yakisoba thịt ba chỉ rau củ', 'Yakisoba là món mì xào lễ hội nổi tiếng của Nhật Bản, kết hợp sợi mì lúa mì dai giòn, thịt ba chỉ áp chảo thơm béo cùng các loại rau củ tươi giòn và sốt yakisoba tự pha từ sốt Worcestershire, dầu hào, tương cà và xì dầu.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Yakisoba","Mì xào","Rau củ","Bữa trưa"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-710fd476f2dddd56', 'com-trung-boc-omurice', 'Cơm gà sốt cà chua bọc trứng Omurice', 'Omurice là món cơm bọc trứng nổi tiếng thuộc phong cách ẩm thực Yoshoku Nhật Bản. Hạt cơm tơi ráo xào thấm đều sốt cà chua ketchup, thịt đùi gà mềm ngọt và đậu xanh, bọc ngoài bằng lớp trứng rây mịn mềm ẩm tan chảy.', 'japanese', 20, 2, 'medium', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Omurice","Trẻ em","Cơm chiên","Trứng gà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-14c8ef999fe47b8f', 'trung-cuon-tamagoyaki', 'Trứng cuộn Nhật Bản Tamagoyaki', 'Tamagoyaki là món trứng cuộn nhiều lớp kinh điển của bữa sáng và hộp cơm bento Nhật Bản. Hỗn hợp trứng gà, chút sữa tươi, xì dầu, rượu mirin và hành lá được tráng thành từng lớp mỏng rồi cuộn chồng khéo léo tạo nên khối trứng mềm ẩm thơm dịu.', 'japanese', 10, 2, 'medium', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Tamagoyaki","Trứng cuộn","Bữa sáng","Hộp cơm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0841a517e823e3b6', 'ga-nuong-teriyaki-bong', 'Đùi gà áp chảo sốt Teriyaki kiểu Nhật', 'Gà Teriyaki là món mặn trứ danh của ẩm thực Nhật Bản. Thịt đùi gà có da được khía nhẹ dàn đều độ dày rồi áp chảo giòn da, sau đó rưới sốt Teriyaki tự pha từ nước tương Nhật, rượu mirin, sake, đường cùng gừng tỏi cô sánh bóng đẹp.', 'japanese', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Teriyaki","Thịt gà","Áp chảo","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6ae7feae7ec0d517', 'ga-xien-yakitori-hanh', 'Gà xiên nướng hành lá Yakitori', 'Negima Yakitori là món gà xiên nướng trứ danh trong các quán izakaya Nhật Bản, kết hợp thịt đùi gà mềm mọng xen kẽ khúc hành lá ngọt thơm, được quét liên tục nước sốt tare cô đặc từ xì dầu, mirin, sake và đường nâu.', 'japanese', 35, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Yakitori","Đồ nướng","Thịt gà","Món nhậu"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-7facaaeafc40dac2', 'ca-hoi-nuong-muoi-chanh', 'Cá hồi nướng muối chanh Shioyaki', 'Shioyaki là phương pháp nướng cá với muối mộc mạc nhưng tinh tế của Nhật Bản. Cá hồi được xoa rượu sake và ướp muối hạt trong tủ lạnh để khử tanh, rút bớt nước thừa giúp thịt cá săn ngọt và phần da nướng giòn thơm.', 'japanese', 10, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Shioyaki","Cá hồi","Đồ nướng","Nhẹ bụng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-70379b3f30b48438', 'goi-dua-leo-tom-nhat', 'Gỏi dưa leo tôm giấm Nhật Sunomono', 'Ebi Sunomono là món gỏi trộn giấm khai vị truyền thống thanh nhẹ của Nhật Bản. Dưa leo được ướp muối vắt ráo để giữ độ giòn lâu, kết hợp cùng tôm tươi luộc chín ngọt thịt và nước sốt giấm gạo pha xì dầu, đường và dầu mè thơm dịu.', 'japanese', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Sunomono","Món gỏi","Khai vị","Thanh mát"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-49262ac40836045a', 'trung-hap-chawanmushi-ga', 'Trứng hấp Chawanmushi thịt gà và nấm', 'Khác với phiên bản hải sản, Chawanmushi thịt gà và nấm tập trung vào vị ngọt thanh của nước dùng dashi kết hợp cùng ức gà mềm thơm ướp rượu sake, nấm đùi gà thái mỏng và lớp trứng đánh rây mịn màng không bọt khí.', 'japanese', 25, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Chawanmushi","Món hấp","Thịt gà","Thanh đạm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e26d04bf95bcede8', 'mi-ramen-heo-trung', 'Mì Ramen thịt xá xíu Chashu và trứng lòng đào', 'Shoyu Ramen là món mì nước biểu tượng của Nhật Bản với nước dùng trong ngọt từ xương ống heo và rau củ thơm, kết hợp cùng nước sốt shoyu tare cô từ nước om thịt ba chỉ cuộn Chashu mềm béo và trứng lòng đào ngâm tương Ajitama.', 'japanese', 180, 4, 'hard', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Mì Ramen","Chashu","Trứng lòng đào","Bữa tối"]', 30, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b808fb03d1e8ede6', 'com-ca-ri-ga-nhat', 'Cơm cà ri gà Nhật', 'Cơm cà ri gà kiểu Nhật (Kare Raisu) có phần sốt sánh mịn, thơm nồng gia vị cà ri hòa quyện vị ngọt tự nhiên từ hành tây xào chín vàng, đùi gà mềm mọng cùng khoai tây và cà rốt bùi bở, chan cạnh cơm trắng dẻo nóng.', 'japanese', 45, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cà ri Nhật","Ẩm thực Nhật","Đùi gà","Cơm nhà","Bữa tối"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-46c2a1c4cc7a8bb5', 'mi-udon-bo-hanh', 'Mì Udon bò hành', 'Mì Udon bò hành (Niku Udon) kết hợp sợi Udon mềm dai cùng nước dùng Dashi trong thanh, ngọt dịu từ xì dầu và Mirin, điểm xuyết thịt bò thái lát mỏng xào nhanh với hành tây và gừng thơm nồng ấm bụng.', 'japanese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì Udon","Ẩm thực Nhật","Thịt bò","Mì nước","Bữa trưa"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-38fb8569664d1f3b', 'ca-hoi-ap-chao-bo-chanh', 'Cá hồi áp chảo bơ chanh', 'Cá hồi áp chảo bơ chanh kiểu Meunière Nhật kết hợp lớp áo bột gạo thật mỏng giúp da cá giòn rụm, bên trong vẫn mềm hồng béo ngậy, rưới sốt bơ tan chảy hòa quyện nước cốt chanh tươi, tỏi phi và xì dầu thanh nhẹ.', 'japanese', 15, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cá hồi","Áp chảo","Sốt bơ chanh","Ẩm thực Nhật","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-eae128801c2c7f96', 'rau-bina-tron-me-nhat', 'Rau bina trộn mè Nhật', 'Rau bina trộn mè Nhật (Horenso Goma-ae) là món rau phụ thanh mát quen thuộc trong mâm cơm Nhật, giữ trọn màu xanh ngọc mướt của cải bó xôi hòa quyện vị béo bùi của hạt mè trắng rang giã dập và sốt xì dầu ngọt dịu.', 'japanese', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Rau bina","Mè rang","Món chay","Ẩm thực Nhật","Thanh mát"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-56ec9eae817af509', 'bap-cai-tron-me-lanh', 'Bắp cải trộn mè lạnh', 'Bắp cải trộn mè lạnh kiểu Nhật kết hợp bắp cải xanh và cà rốt thái sợi hấp nhẹ chỉ với một ít nước nên giữ trọn vị ngọt giòn tự nhiên, trộn đều cùng sốt mè trắng rang giã dập, xì dầu, giấm gạo và dầu mè thơm bùi.', 'japanese', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Bắp cải","Mè rang","Món trộn","Ẩm thực Nhật","Thanh mát"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-44b1338a7a49098d', 'canh-kimchi-dau-phu-han', 'Canh kim chi đậu phụ kiểu Hàn', 'Canh kim chi đậu phụ kiểu Hàn mang hương vị truyền thống với phần kim chi được xào kỹ cùng thịt ba chỉ cho dậy mùi thơm, hầm liu riu trong nước dùng cá cơm tảo bẹ ngọt thanh cùng hành tây, ớt bột Gochugaru và đậu phụ mềm mịn.', 'korean', 30, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Kim chi","Đậu phụ","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a24a701c584d3ef3', 'com-tron-bibimbap-han', 'Cơm trộn Bibimbap Hàn Quốc', 'Cơm trộn Bibimbap Hàn Quốc là bức tranh ẩm thực hài hòa năm sắc màu với cơm trắng dẻo nóng làm nền, xếp bên trên các loại rau củ sơ chế riêng giữ trọn độ giòn tươi, thịt bò thăn xào đậm vị, trứng gà ốp la và sốt tương ớt Gochujang cay ngọt.', 'korean', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Cơm trộn","Bibimbap","Đầy đủ dinh dưỡng","Thịt bò"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-52b5963c6cecfb96', 'bo-nuong-bulgogi-ngot', 'Bò nướng Bulgogi kiểu Hàn', 'Bò nướng Bulgogi kiểu Hàn nổi bật với từng lát thịt bò thăn ngoại mềm ngọt, thấm sâu nước sốt ướp mặn ngọt dịu từ nước tương, mật ong, đường nâu và rượu ngọt Mirin, khi nướng áp chảo lửa lớn tạo lớp cạnh xém thơm quyến rũ.', 'korean', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món nướng","Bulgogi","Thịt bò","Tiệc nướng"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-51b6559bf09bc980', 'canh-tom-nau-bi-do', 'Canh tôm nấu bí đỏ dẻo ngọt', 'Khác với kiểu nấu nhanh giữ miếng, bí đỏ được ninh bở dẻo trên lửa nhỏ cùng nước dùng ngọt thanh từ tôm tươi xào tỏi gừng thơm nức, mang đến tô canh ấm áp sánh vàng dịu nhẹ.', 'vietnamese', 22, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Bí đỏ","Bổ dưỡng","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-81a203668e5e4c1a', 'canh-trung-nam-kim-cham', 'Canh trứng nấm kim châm cà chua', 'Tô canh thanh nhẹ giàu chất xơ với nấm kim châm giòn sần sật ngọt nước, hòa quyện sắc đỏ dịu của cà chua chín và những sợi vân trứng gà mềm béo đẹp mắt.', 'vietnamese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nấm","Dưới 20 phút","Dễ nấu","Cơm nhà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6c20dba60d77bdfd', 'canh-suon-su-su-non', 'Canh sườn hầm su su non', 'Nồi canh ấm nóng quen thuộc với phần nước hầm sườn non trong veo, thịt sườn mềm ngọt róc xương quyện cùng su su non giòn mát và sắc cam dịu của cà rốt.', 'vietnamese', 45, 5, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Sườn","Bổ dưỡng","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-734cc9acf8620c69', 'canh-dau-phu-ca-chua-trung', 'Canh đậu phụ cà chua trứng', 'Canh đậu phụ cà chua trứng có nước dùng đỏ cam tự nhiên, vị chua dịu hài hòa từ cà chua chín, miếng đậu phụ non béo mềm tan nhẹ cùng những sợi vân trứng gà vàng mịn thơm lừng.', 'vietnamese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Đậu phụ","Thanh đạm","Nấu nhanh","Cơm nhà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-095cff5e61d32fd9', 'canh-bo-ca-chua-ngot', 'Canh bò cà chua ngọt', 'Canh bò cà chua ngọt là món canh cơm nhà giản dị nhưng đậm đà hương vị miền Nam. Thịt bò thăn thái mỏng ướp gia vị thấm mềm, nấu nhanh trong nước dùng cà chua đỏ au chua ngọt nhẹ, dậy mùi rau răm và hành lá.', 'vietnamese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Cà chua","Nam Bộ","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a4822c0a1187e4d7', 'suon-nuong-muoi-ot', 'Sườn nướng muối ớt', 'Những khúc sườn non nhiều thịt mềm ngọt được ướp đậm đà vị mặn mà của muối hạt, cay nồng từ ớt hiểm tươi và tỏi băm, nướng chín vàng xém cạnh ăn kèm nước chấm chanh ớt.', 'vietnamese', 30, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Sườn nướng","Muối ớt","Cuối tuần","Món mặn","Đưa cơm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-04514fa34052d242', 'ga-kho-nam-dam', 'Gà kho nấm đùi gà đậm vị', 'Thịt đùi gà áp chảo săn chắc kho quyện hương thơm đặc trưng của dầu mè, nấm hương khô ngâm nở và nấm đùi gà dai ngọt tự nhiên, nước kho sánh nâu đậm vị.', 'vietnamese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt gà","Nấm đùi gà","Đưa cơm","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-695f59248dbf4895', 'ca-kho-gung-sa', 'Cá kho gừng sả miền Trung', 'Khúc cá lóc chiên săn chắc thịt kho thấm vị nước mắm ngon, thơm nồng mùi sả băm, gừng giã dập phi vàng và vị cay ấm đặc trưng từ ớt bột cùng ớt tươi miền Trung.', 'vietnamese', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cá kho","Miền Trung","Gừng sả","Món kho","Đưa cơm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-208386f834b8da43', 'trung-kho-tuong-keo', 'Trứng gà kho nước tương sánh keo', 'Những quả trứng gà thấm đẫm nước sốt nước tương và xì dầu đặc sánh kẹo màu nâu bóng đẹp mắt, phảng phất mùi thơm dịu của ngũ vị hương, hành tỏi phi và tương ớt cay nhẹ.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Trứng kho","Nước tương","Nhanh gọn","Đưa cơm","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d1f8ab89051a6336', 'bong-cai-xao-tom-tuoi', 'Bông cải xào tôm tươi', 'Đĩa bông cải xào tôm tươi hài hòa giữa sắc xanh mướt của súp lơ, cam tươi của cà rốt và vị ngọt săn chắc từ tôm tươi, được bao bọc bởi lớp sốt bột bắp sánh bóng thơm dịu dầu mè và mè trắng rang.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Rau xanh","Giàu chất xơ","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-03c5e6e31e01088d', 'dau-phu-xao-sa-ot', 'Đậu phụ xào sả ớt', 'Đậu phụ xào sả ớt kiểu Nam Bộ hấp dẫn với lớp vỏ đậu vàng giòn bên ngoài nhưng bên trong vẫn béo mềm, quyện đẫm phần sốt sả băm thơm lừng, vị cay nồng của ớt và mặn ngọt sánh nhẹ từ nước tương, dầu hào chay và tương ớt.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Món chay","Đậu phụ","Sả ớt","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2862e7aa0ae0d8fe', 'bo-xao-dua-chua-ngot', 'Bò xào dứa chua ngọt', 'Bò xào dứa chua ngọt là món ăn cực kỳ bắt cơm với thịt thăn bò mềm tan nhờ enzyme tự nhiên từ dứa tươi, kết hợp cùng hành tây giòn ngọt và nước sốt dầu hào nước mắm đậm đà hương vị Nam Bộ.', 'vietnamese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Chua ngọt","Nam Bộ","Cơm nhà"]', 18, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-aa94e2f8bdf3985f', 'tom-hap-sa-chanh', 'Tôm hấp sả lá chanh thơm nồng', 'Tôm sú tươi giữ nguyên vị ngọt giòn tự nhiên khi hấp nhanh cùng sả đập dập, lá chanh thơm mát, gừng lát và chút rượu trắng khử tanh, phủ thêm lớp tỏi phi vàng giòn dậy mùi hấp dẫn.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Tôm","Sả","Mát lành","Dưới 20 phút"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b55451e6e46a4c13', 'bap-cai-cuon-hap-thit', 'Bắp cải cuộn thịt hấp thanh ngọt', 'Những cuộn bắp cải xanh mướt căng tròn ôm lấy phần nhân thịt heo xay quyện mộc nhĩ giòn sần sật và cà rốt ngọt dịu, buộc cố định bằng cọng hành lá chần mềm; hấp cách thủy giữ trọn vị ngọt tự nhiên.', 'vietnamese', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Bắp cải","Khéo tay","Món Bắc","Thanh đạm"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-500644420438efd3', 'dau-phu-hap-sa', 'Đậu phụ hấp sả xì dầu thanh đạm', 'Đậu phụ non mịn hấp cách thủy cùng nước sốt xì dầu đậm dịu và sả xào vàng thơm lừng, giữ trọn vị béo bùi tự nhiên của đậu nành, ít dầu mỡ và rất dễ tiêu hóa.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Đậu phụ","Thanh đạm","Dễ nấu","Món chay"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-47cbfe72125b811d', 'goi-bo-dua-leo-chanh', 'Gỏi bò dưa leo chanh', 'Gỏi bò dưa leo chanh kết hợp tinh tế giữa thịt bò thăn xào tỏi thơm mềm mọng, từng sợi dưa leo và cà rốt giòn ngọt, hành tây thanh dịu và nước trộn mắm chanh ớt hiểm đậm đà, điểm xuyết đậu phộng rang bùi béo và rau thơm.', 'vietnamese', 10, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Gỏi bò","Dưa leo","Chua cay","Khai vị","Đãi tiệc"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-403a1693ea9b3cf8', 'bun-tom-rau-muong-chua-cay', 'Bún tôm rau muống chua cay', 'Bún tôm rau muống chua cay mang đậm hương vị Nam Bộ dễ ăn với nước dùng ngọt xương hòa vị chua dịu từ me vắt, thơm dịu từ dứa và cà chua, thêm chút sa tế cay nồng ăn cùng tôm tươi và rau muống chẻ giòn.', 'vietnamese', 45, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Bún tôm","Chua cay","Rau muống","Nam Bộ"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-c039dac37b31acdb', 'mi-quang-ga-ta', 'Mì Quảng gà ta', 'Mì Quảng gà ta chuẩn vị Quảng Nam với phần nước nhân nấu vừa xâm xấp đậm đà hương nghệ, hành tím và sả phi dầu, thịt gà ta săn mềm thấm vị, ăn cùng rau sống chín tầng, đậu phộng rang và bánh đa bẻ giòn.', 'vietnamese', 55, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Mì Quảng","Gà ta","Ẩm thực miền Trung","Đặc sản"]', 30, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-875e99916a13d031', 'pho-chay-nam-dau', 'Phở chay nấm đậu', 'Phở chay nấm đậu thanh tịnh nhưng vẫn đậm đà tròn vị nhờ nước dùng hầm củ cải trắng, cà rốt, hành tây nướng và gia vị phở truyền thống, kết hợp đậu phụ chiên vàng giòn và nấm đùi gà xào ngũ vị hương thơm lừng.', 'vietnamese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Phở chay","Thanh đạm","Nấm đậu","Món nước"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4)
INSERT INTO recipes (id, slug, title, description, cuisine, cook_time_minutes, servings, difficulty, image_url, tags, prep_time_minutes, source_type, source_reference, verification_state, version) VALUES
('imp-389f525ea854b373', 'canh-chua-chay-dua-dau', 'Canh chua chay dứa đậu phụ Nam Bộ', 'Bát canh chua chay Nam Bộ thanh tao đậm đà với sự hòa quyện cân bằng giữa vị chua dịu từ me chín, ngọt thơm của dứa chín, sắc đỏ của cà chua cùng đậu phụ béo mềm, đậu bắp, dọc mùng và giá đỗ giòn tươi.', 'vietnamese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Canh chua","Nam Bộ","Thanh nhiệt","Đậu phụ"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8301ed8c884fb619', 'cai-bap-xao-nam-chay', 'Bắp cải xào nấm đùi gà chay', 'Món xào chay thanh đạm mà đưa cơm với lá bắp cải trắng giòn ngọt tự nhiên kết hợp nấm đùi gà dai sần sật, thấm nhẹ nước tương, hương tỏi phi và mùi thơm đặc trưng của lá hẹ xanh tươi.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Món xào","Bắp cải","Nấm đùi gà","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-327ffa644fbe1a7d', 'chao-tom-nam-nong', 'Cháo tôm nấm đùi gà nóng', 'Tô cháo tôm nấm nóng hổi sánh mượt với gạo tẻ kết hợp chút gạo nếp rang thơm, thịt tôm tươi săn ngọt đậm đà cùng nấm đùi gà giòn sần sật, gừng tươi thái chỉ và hành lá thơm dịu.', 'vietnamese', 28, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cháo tôm","Nấm đùi gà","Ăn sáng","Thanh ngọt","Ấm bụng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9aed26098f07c061', 'trung-duc-thit-bam', 'Trứng đúc thịt bằm', 'Món trứng đúc thịt bằm dân dã quen thuộc trong mọi mâm cơm Việt với lớp vỏ ngoài vàng ươm thơm phức, phần nhân bên trong bông mềm ẩm mượt quyện thịt heo nạc vai xay, hành tím phi và hành lá xanh tươi.', 'vietnamese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Trứng đúc thịt","Cơm nhà","Nhanh gọn","Giàu đạm","Bé thích"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-24e75cbb2ba569f4', 'banh-trang-tron-rau-cu', 'Bánh tráng trộn rau củ', 'Món bánh tráng trộn rau củ chuẩn vị Sài Gòn phiên bản thanh mát với sợi bánh tráng dẻo dai vừa độ, bắp cải và cà rốt bào giòn, rau răm thơm nồng quyện mỡ hành béo nhẹ, đậu phộng rang giòn bùi và sốt nước tương chanh ớt.', 'vietnamese', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Bánh tráng trộn","Nam Bộ","Ăn vặt","Thanh nhẹ","Dưới 20 phút"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0bd4954058454e92', 'lau-ga-nam-am', 'Lẩu gà nấm ấm bụng', 'Lẩu gà nấm ấm bụng mang hương vị dịu nhẹ chuẩn cơm tiệc gia đình miền Bắc. Đùi gà ta xào săn cùng gừng tươi và sả cây rồi hầm mềm ngọt nước, kết hợp nấm hương tươi thơm nức, nấm đùi gà giòn ngọt cùng bắp cải và rau muống xanh mát.', 'vietnamese', 45, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Gà nấm","Bắc Bộ","Ấm bụng","Gia đình"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-7fa36d5f0187a86e', 'com-chien-ba-chi-hanh', 'Cơm chiên ba chỉ hành', 'Món cơm chiên ba chỉ hành thơm nức mũi với những miếng thịt ba chỉ cắt hạt lự chiên giòn cạnh tiết mỡ béo ngậy, hạt cơm rang săn rời áo hương tỏi phi, xì dầu dậy mùi khói chảo cùng thật nhiều hành lá tươi xanh.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Ba chỉ","Béo thơm","Nhanh gọn","Cơm nhà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-fcf23c737f51ef13', 'com-chien-ca-chua-trung', 'Cơm chiên cà chua trứng', 'Món cơm chiên cà chua trứng kiểu Trung Hoa giản dị nhưng cuốn hút với từng hạt cơm nguội tơi ráo quyện đều nước sốt cà chua chua ngọt, dầu hào đậm đà và những mảng trứng gà chiên mềm thơm.', 'chinese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Cà chua","Trứng gà","Trung Hoa","Món nhanh"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a5148e527a9ce9cf', 'ga-xao-gung-hanh-trung', 'Gà xào gừng hành kiểu Trung', 'Món gà xào gừng hành kiểu Trung Hoa chế biến nhanh gọn nhưng đậm đà nhờ phần nước sốt pha gừng non nạo nhuyễn kết hợp xì dầu, dầu hào và hành lá cắt khúc thơm nồng.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Gừng hành","Trung Hoa","Đưa cơm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b3d9ecb751b0a043', 'bo-xao-hanh-tay-ot', 'Bò xào hành tây ớt kiểu Trung', 'Món bò xào hành tây ớt kiểu Trung Hoa hấp dẫn bởi từng lát thịt bò thăn mềm ngọt quyện sốt xì dầu dầu hào bóng mịn, kết hợp cùng hành tây giòn ngọt và chút cay nồng của ớt hiểm.', 'chinese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Hành tây","Trung Hoa","Đưa cơm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-835a527c81a79e9c', 'sup-bap-cai-thit-bam', 'Súp cải thảo thịt bằm kiểu Trung', 'Món canh súp cải thảo thịt bằm kiểu Trung Hoa có nước dùng trong veo ngọt dịu từ gà và rau củ, thịt heo bằm ướp mềm đậm vị kết hợp cùng cọng cải thảo chín tới ấm lòng cho bữa cơm tối.', 'chinese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Cải thảo","Thịt bằm","Trung Hoa","Thanh đạm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-1dc0835c31b06d5e', 'tom-xao-bong-cai-trung', 'Tôm xào bông cải xanh kiểu Trung', 'Món tôm xào bông cải xanh kiểu Trung Hoa cân bằng dinh dưỡng với từng con tôm tươi săn ngọt kết hợp bông cải xanh chín tới giòn mướt nhờ kỹ thuật ủ hơi nước, phủ lớp sốt dầu hào bóng nhẹ.', 'chinese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Tôm tươi","Bông cải xanh","Quảng Đông","Thanh ngọt"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-57b4406be05661c7', 'ba-chi-xao-tuong-dau', 'Thịt ba chỉ xào tương đậu', 'Món thịt ba chỉ xào tương đậu đậm chất cơm nhà Trung Hoa với từng miếng ba chỉ áp chảo xém cạnh thơm béo, quyện trong mùi thơm nồng đặc trưng của tương ớt đậu bản Doubanjiang và đậu tương đen lên men Douchi.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt ba chỉ","Tương đậu","Trung Hoa","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3774a1f0fda5cce1', 'ga-sot-chua-ngot-trung', 'Gà chiên sốt chua ngọt kiểu Trung', 'Món gà chiên sốt chua ngọt kiểu Trung Hoa hấp dẫn với lớp vỏ bột mỏng nhẹ giòn rụm nhờ kỹ thuật chiên hai lần, quyện trong nước sốt chua ngọt sóng sánh cùng dứa chín, ớt chuông và hành tây tím.', 'chinese', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Chua ngọt","Thịt gà","Trung Hoa","Món tiệc"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-49ca1819d60ffec8', 'mi-hanh-dau', 'Mì trộn dầu hành kiểu Quảng Đông', 'Món mì trộn dầu hành nổi tiếng với hương thơm quyến rũ từ hành lá phi chậm trong dầu nguội hòa quyện cùng xì dầu nhạt, xì dầu đặc và đường cát tạo nên lớp sốt nâu bóng áo đều từng sợi mì dai ngon.', 'chinese', 12, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Dầu hành","Quảng Đông","Món nhanh","Giản dị"]', 5, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2b5b79ba1b622db1', 'canh-cai-thao-tom', 'Canh cải thảo nấu tôm', 'Món canh cải thảo nấu tôm mang vị ngọt thanh tự nhiên từ tôm khô ninh kỹ hòa quyện cùng nước dùng gà trong veo, lá cải thảo mềm mọng và hương thơm ấm áp của gừng tươi.', 'chinese', 18, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Cải thảo","Tôm khô","Trung Hoa","Thanh ngọt"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ee5bc076d722f397', 'ga-hap-nam-dong', 'Gà hấp nấm đông cô', 'Món gà hấp nấm đông cô kiểu gia đình Trung Hoa giữ nguyên độ mọng nước ngọt tự nhiên của thịt đùi gà ướp bột bắp kết hợp hương thơm umami đậm đà từ nấm hương khô ngâm nở.', 'chinese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Thịt gà","Nấm hương","Trung Hoa","Gia đình"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-aac2c265c3845ec4', 'tom-hap-gung-hanh', 'Tôm hấp gừng hành kiểu Quảng Đông', 'Món tôm hấp gừng hành kiểu Quảng Đông tôn vinh trọn vẹn độ ngọt giòn tự nhiên của tôm sú tươi hấp chín vừa tới trong vòng 5–6 phút, phủ lớp gừng sợi, hành lá xanh mướt và nước sốt xì dầu dịu nhẹ.', 'chinese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Tôm sú","Gừng hành","Quảng Đông","Thanh đạm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-55201e4225342ca3', 'ca-sot-chua-ngot-trung', 'Cá phi lê sốt chua ngọt kiểu Trung', 'Món cá phi lê sốt chua ngọt kiểu Quảng Đông nổi bật với từng miếng phi lê cá lọc xương áo lòng trắng trứng và bột bắp chiên vàng giòn rụm, hòa quyện trong phần sốt tương cà, giấm gạo, dứa chín và rau củ giòn tươi.', 'chinese', 15, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Chua ngọt","Phi lê cá","Quảng Đông","Món tiệc"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6771c725aa163703', 'dau-phu-lanh-hanh', 'Đậu phụ non sốt hành xì dầu lạnh', 'Món khai vị lạnh chuẩn vị Trung Hoa với từng khối đậu phụ non mềm tan như kem, quyện cùng nước sốt xì dầu nhạt đun thơm hành tỏi, điểm chút giấm gạo thanh dịu, dầu mè béo thơm và ớt hiểm tươi cay nhẹ.', 'chinese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món lạnh","Khai vị","Đậu phụ","Thanh mát","Chay"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-5eb2769876646aae', 'mi-tron-dau-phu-cay', 'Mì trộn đậu phụ chiên giòn sốt cay', 'Bữa trưa nhanh gọn mà đầy đủ năng lượng với sợi mì lúa mì dai ngon trộn đều trong nước sốt xì dầu nhạt, xì dầu đặc, giấm gạo và dầu ớt thơm lừng tỏi phi, ăn kèm những khối đậu phụ áo bột bắp ngũ vị chiên giòn rụm.', 'chinese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Đậu phụ","Cay nồng","Nhanh gọn","Bữa trưa"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-87adca15ad4c1369', 'ga-ham-nikujaga-ca-rot', 'Gà hầm Nikujaga cà rốt', 'Gà hầm Nikujaga biến tấu thanh nhẹ từ món hầm truyền thống Nhật Bản với thịt đùi gà mềm ngọt thay cho thịt bò, hầm cùng khoai tây bở bùi, cà rốt và hành tây trong nước dùng Dashi hòa quyện xì dầu, rượu Sake và Mirin.', 'japanese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nikujaga","Thịt gà hầm","Ẩm thực Nhật","Cơm nhà","Mùa lạnh"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-62d95da722597187', 'mi-soba-tron-nam-me', 'Mì Soba trộn nấm mè', 'Mì Soba trộn nấm mè mang hương vị thanh nhã của mì kiều mạch Nhật Bản dai mềm, hòa quyện cùng nấm đùi gà xào vàng giòn sần sật, gừng bào, hành lá và phần sốt mè rang thơm bùi đậm vị xì dầu giấm gạo.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì Soba","Nấm đùi gà","Mè rang","Ẩm thực Nhật","Bữa trưa"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d2ab8a9e07388289', 'muc-nuong-teriyaki', 'Mực nướng Teriyaki', 'Mực nướng Teriyaki kiểu Nhật (Ika Maruyaki) giữ trọn độ giòn ngọt tự nhiên của mực ống tươi nhờ chần nhanh rồi nướng xém cạnh, phủ lớp sốt Teriyaki nấu từ xì dầu, rượu Sake, Mirin và đường nâu sánh bóng thơm lừng.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mực nướng","Teriyaki","Hải sản","Ẩm thực Nhật","Món nướng"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-81ff926a5557c059', 'ca-hoi-nuong-miso', 'Cá hồi nướng Miso', 'Cá hồi nướng Miso (Saikyo Yaki) là món cá nướng tinh tế nổi tiếng của Nhật Bản, dùng tương Miso trắng ngọt dịu kết hợp rượu Sake, Mirin và chút dầu mè ướp thấm nhẹ vào từng thớ cá hồi béo ngậy rồi nướng lửa trên vàng xém thơm lừng.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cá hồi","Tương Miso","Món nướng","Ẩm thực Nhật","Cơm tối"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8c6abf9194ba8c45', 'ga-xao-gia-itame', 'Gà xào giá Itame', 'Gà xào giá Itame (Tori Moyashi Itame) là món xào nhà Nhật nhanh gọn chỉ trong 20 phút, kết hợp thịt đùi gà áp chảo vàng thơm thấm sốt xì dầu tỏi và giá đỗ xào nhanh trên lửa lớn nên vẫn giữ được độ giòn ngọt tươi mát.', 'japanese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gà xào","Giá đỗ","Itame","Ẩm thực Nhật","Nhanh gọn"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b33750551f6ea7fe', 'nam-nuong-bo-shoyu', 'Nấm nướng bơ Shoyu', 'Nấm nướng bơ Shoyu là món nhậu Izakaya kinh điển của Nhật Bản, dùng nấm đùi gà cắt khoanh dày khía caro áp chảo vàng ruộm rồi áo đẫm bơ béo thơm và xì dầu Nhật rưới cháy cạnh, cắn vào giòn sần sật đậm vị umami.', 'japanese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nấm đùi gà","Bơ Shoyu","Izakaya","Ẩm thực Nhật","Nhanh gọn"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e9562581c7d79169', 'com-cua-kanimeshi', 'Cơm cua Kanimeshi', 'Cơm cua Kanimeshi nấu bằng nồi cơm điện tiện lợi nhưng vẫn đậm đà hương vị biển kiểu Hokkaido, kết hợp cơm gạo Nhật dẻo thơm vị xì dầu và rượu Sake, hòa quyện thịt cua tươi ngọt chắc, dầu mè thơm và lớp trứng đánh hấp tơi béo.', 'japanese', 45, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Kanimeshi","Cơm cua","Nồi cơm điện","Ẩm thực Nhật","Hải sản"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ee7ca138c67f4f24', 'bo-xao-gung-itame', 'Bò xào gừng Itame', 'Bò xào gừng Itame kiểu Nhật có miếng thịt bò mềm mọng nhờ bí quyết áo lớp tinh bột khoai tây mỏng, xào nhanh cùng hành tây hấp chín ngọt thanh và gừng tươi hai kiểu vừa thái sợi vừa mài nhuyễn trong nước sốt xì dầu Mirin sánh đậm.', 'japanese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thịt bò xào","Gừng tươi","Itame","Ẩm thực Nhật","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-57a8ece15d731efb', 'sup-miso-bap-cai', 'Súp Miso bắp cải', 'Súp Miso bắp cải là món canh hằng ngày thanh đạm của người Nhật, kết hợp vị ngọt tự nhiên từ bắp cải xanh và nấm đùi gà nấu vừa chín tới trong nước dùng Dashi, hòa tan tương Miso sau khi tắt bếp để giữ trọn hương thơm lên men dịu nhẹ.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Súp Miso","Bắp cải","Nấm đùi gà","Ẩm thực Nhật","Món canh"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-23a82881883d70fb', 'mi-udon-nam-dau', 'Mì Udon nấm đậu', 'Mì Udon nấm đậu là tô mì chay thanh tịnh chuẩn vị Nhật Bản, lấy vị ngọt tự nhiên từ tảo bẹ Kombu và nấm hương khô nấu Dashi, kết hợp sợi mì Udon dày dai, đậu phụ chiên vàng mềm béo và nấm đùi gà giòn ngọt.', 'japanese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì Udon","Đậu phụ","Nấm đùi gà","Món chay","Ẩm thực Nhật"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-85a3d8b84fc0bc05', 'mi-ramen-pho-mai-kim-chi', 'Mì ramen phô mai kim chi', 'Mì ramen phô mai kim chi kết hợp vị chua cay nồng ấm của kim chi cải thảo xào thơm với nước dùng đậm đà, sợi mì ramen dai giòn, trứng gà lòng đào và lớp phô mai Cheddar tan chảy béo thơm hài hòa.', 'korean', 15, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Mì cay","Phô mai","Kim chi","Món nhanh"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9d28abab0b8e5619', 'ga-ham-kim-chi', 'Gà hầm kim chi (Dak Kimchi Jjim)', 'Gà hầm kim chi (Dak Kimchi Jjim) kết hợp những miếng đùi gà chặt vừa ăn được om chậm cùng kim chi cải thảo chua lâu năm và sốt Gochujang cay thơm, cho phần thịt gà mềm rục thấm vị và nước sốt sánh đỏ cực kỳ bắt cơm.', 'korean', 40, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món hầm","Thịt gà","Kim chi","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2842fe1b767de23d', 'trung-cuon-gyeran-mari', 'Trứng cuộn Hàn Quốc (Gyeran Mari)', 'Trứng cuộn Hàn Quốc (Gyeran Mari) có kết cấu mềm mịn, nhiều lớp cuộn chặt tay với nhân cà rốt và hành lá băm nhuyễn đẹp mắt, vị béo nhẹ thanh tao thích hợp dùng kèm cơm nóng hoặc xếp hộp cơm trưa.', 'korean', 10, 2, 'medium', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món trứng","Bữa sáng","Hộp cơm","Món nhanh"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-412960b58d00d211', 'sundubu-tom-cay', 'Canh đậu phụ non hải sản cay (Sundubu Jjigae)', 'Canh đậu phụ non hải sản cay (Sundubu Jjigae) là món canh nóng nổi tiếng của Hàn Quốc nhờ dầu ớt Gochugaru tự xào thơm lừng hòa trong nước dùng cá cơm tảo bẹ, ôm trọn từng miếng đậu phụ non béo mịn, tôm tươi săn ngọt và trứng gà lòng đào.', 'korean', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Hải sản","Đậu phụ non","Cay ấm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-80976e834de46c34', 'japchae-mi-soi-tron', 'Miến trộn Hàn Quốc (Japchae)', 'Miến trộn Hàn Quốc (Japchae) là món ăn truyền thống không thể thiếu trong các dịp lễ tiệc nhờ sợi miến khoai lang trong suốt dai ngon áo xì dầu và dầu mè rang, hòa quyện cùng thịt bò thăn, hai loại nấm thơm ngọt và rau củ xào riêng rực rỡ.', 'korean', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Miến trộn","Japchae","Lễ tiệc","Thịt bò"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8608afb7fee8ebc3', 'ba-chi-nuong-samgyeopsal', 'Ba chỉ nướng Hàn Quốc (Samgyeopsal)', 'Ba chỉ nướng Hàn Quốc (Samgyeopsal) hấp dẫn nhờ miếng ba chỉ dày thịt xen mỡ được nướng trên chảo gang đến khi vàng giòn hai mặt, ăn kèm kim chi áp chảo và tỏi nướng thơm lừng, cuốn trong xà lách và lá tía tô cùng tương Ssamjang.', 'korean', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Tiệc nướng","Thịt ba chỉ","Samgyeopsal","Cuốn rau"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-97ba5787e2d4113b', 'canh-tuong-dau-han', 'Canh tương đậu Hàn Quốc (Doenjang Jjigae)', 'Canh tương đậu Hàn Quốc (Doenjang Jjigae) là món canh quen thuộc trên mâm cơm gia đình xứ Hàn với vị mặn bùi đặc trưng của tương đậu lên men Doenjang hòa cùng nước dùng cá cơm tảo bẹ ngọt thanh, nấm đùi gà giòn ngọt, rau chân vịt xanh mướt và đậu phụ mềm.', 'korean', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Tương đậu","Đậu phụ","Thanh đạm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-96d226a7f4d12156', 'ga-chien-gangjeong-cay', 'Gà chiên giòn sốt cay ngọt (Dakgangjeong)', 'Gà chiên giòn sốt cay ngọt (Dakgangjeong) nổi bật với kỹ thuật chiên hai lần giúp lớp vỏ bột bắp giòn rụm lâu dài dù đã áo đẫm nước sốt mật ong, đường nâu, giấm gạo và tương ớt Gochujang keo bóng đậm đà.', 'korean', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Gà chiên","Cay ngọt","Giòn rụm","Dakgangjeong"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ba1871f088d9a522', 'lau-bulgogi-nam', 'Lẩu Bulgogi nấm kiểu Hàn (Bulgogi Jeongol)', 'Lẩu Bulgogi nấm kiểu Hàn (Bulgogi Jeongol) mang đến trải nghiệm ấm cúng với thịt bò thăn ướp sốt mật ong xì dầu xếp gọn cùng nấm đùi gà, cải thảo, cà rốt và miến khoai lang trong nồi nước dùng cá cơm tảo bẹ ninh củ cải ngọt thanh.', 'korean', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món lẩu","Thịt bò","Nấm đùi gà","Tiệc gia đình"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-24fc3ac5cd3ff445', 'com-chien-kim-chi-han', 'Cơm chiên kim chi truyền thống (Kimchi Bokkeumbap)', 'Cơm chiên kim chi truyền thống (Kimchi Bokkeumbap) giữ đúng tinh thần tối giản chuẩn vị Hàn với kim chi cải thảo ủ chua kỹ xào săn, hạt cơm nguội rang tơi áo đều nước kim chi và Gochujang cay nồng, phủ trứng ốp la béo thơm.', 'korean', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Cơm chiên","Kim chi","Món nhanh","Cay đậm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-46962ad0d6f6e63b', 'ga-xao-hung-que-pad-krapao', 'Gà bằm xào húng quế kiểu Thái (Pad Krapow Gai)', 'Phiên bản Pad Krapow thịt gà băm thanh nhẹ hơn thịt heo nhưng vẫn giữ trọn hương vị đường phố Thái Lan: thịt gà tơi ngọt quyện sốt dầu hào, hai loại xì dầu, vị cay tê của ớt hiểm và mùi thơm bừng tỉnh của lá húng quế.', 'thai', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad Krapow","Thịt gà","Cay nồng","Cơm đĩa"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f8fc539b7aa359ac', 'com-chien-dua-thai', 'Cơm chiên dứa hải sản kiểu Thái (Khao Pad Sapparot)', 'Khao Pad Sapparot là món cơm chiên nhiệt đới nổi tiếng của Thái Lan với hạt cơm tơi vàng ươm hương cà ri dịu nhẹ, vị chua ngọt thanh mát từ dứa tươi hòa cùng tôm săn ngọt và hạt điều bùi béo.', 'thai', 18, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Cơm chiên","Hải sản","Dứa chín","Chua ngọt"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e28e249efceacac7', 'larb-heo-chua-cay', 'Gỏi thịt heo bằm chua cay kiểu Thái (Larb Moo)', 'Larb Moo là món gỏi thịt bằm đặc sản vùng Isan Thái Lan với vị chua thanh từ chanh tươi, mặn ngọt hài hòa, cay tê của ớt bột và hương thơm bùi đặc trưng từ thính gạo rang cùng húng lủi.', 'thai', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Gỏi trộn","Chua cay","Thịt heo bằm","Ít dầu mỡ"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-90fc2e140739a7d7', 'tom-yum-ca-nam', 'Canh chua cay cá nấm Tom Yum kiểu Thái (Tom Yum Pla)', 'Tom Yum Pla là biến thể Tom Yum nước trong thanh mát không dùng cốt dừa hay tương ớt béo, nổi bật với vị ngọt tự nhiên của phi lê cá thịt trắng, nấm đùi gà giòn sần sật và hương thảo mộc tươi nồng nàn.', 'thai', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Tom Yum","Cá tươi","Chua cay"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8ebb3021c30c48f8', 'pad-see-ew-ga', 'Hủ tiếu xào xì dầu thịt gà kiểu Thái (Pad See Ew)', 'Pad See Ew là món mì xào xì dầu trứ danh tại các khu chợ đêm Thái Lan, nổi bật với sợi bánh phở tươi bản to dẻo dai áp chảo hơi xém cạnh, vị mặn ngọt hài hòa từ hắc xì dầu, dầu hào và cải xanh giòn ngọt.', 'thai', 20, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad See Ew","Mì xào","Ức gà","Xì dầu"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8e2f2113f406a7d8', 'ga-xien-sate-sa', 'Thịt gà xiên sả nướng kiểu Thái (Satay Sả)', 'Gà xiên sả kiểu Thái thơm nức hương sả tươi, tỏi và ngò rí quyện cùng nước cốt dừa giúp thịt đùi gà mềm mọng lạ miệng, nướng xém cạnh vàng ươm mà không hề bị khô.', 'thai', 15, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Xiên nướng","Thịt gà","Sả thơm","Tiệc cuối tuần"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-574963de4a60d466', 'ca-hap-chanh-ot-thai', 'Cá chẽm hấp chanh ớt kiểu Thái (Pla Neung Manao)', 'Pla Neung Manao là món cá hấp kinh điển trong các bữa tiệc Thái Lan, giữ trọn độ ngọt thanh mềm mọng của thịt cá tươi hòa quyện cùng nước sốt chanh tỏi ớt chua tê bùng vị và hương cần tàu tươi mát.', 'thai', 15, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món hấp","Cá tươi","Chua cay","Thanh mát"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-295e7045e644d2ca', 'goi-muc-mi-soi-thai', 'Gỏi miến mực chua cay kiểu Thái (Yam Wun Sen)', 'Yam Wun Sen là món gỏi miến khai vị thanh mát trứ danh của Thái Lan với sợi miến trong dai không bết dính, mực tươi giòn ngọt quyện sốt nước mắm chanh đường thốt nốt chua cay đậm vị.', 'thai', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Gỏi trộn","Miến trộn","Hải sản","Chua cay"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-5e0a488541baee5e', 'trung-chien-kai-jeow', 'Trứng chiên giòn phồng kiểu Thái (Kai Jeow)', 'Kai Jeow là món trứng chiên đường phố nổi tiếng của Thái Lan với kỹ thuật rót trứng từ trên cao vào chảo dầu thật nóng, tạo lớp vỏ ngoài phồng xốp giòn tan mà ruột trứng vẫn giữ độ ẩm mềm.', 'thai', 10, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Trứng chiên","Món chiên","Nhanh gọn","Cơm nhà"]', 5, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-bcc430e4b54c1e65', 'canh-tom-chuet-tom', 'Canh bắp cải tôm tươi thanh ngọt kiểu Thái (Tom Chuet)', 'Tom Chuet là món canh thanh mát không cay quen thuộc trên mâm cơm gia đình Thái Lan, kết hợp vị ngọt tự nhiên từ tôm tươi áp chảo sơ cùng bắp cải mềm ngọt, cà chua chín và nước dùng thơm mùi tỏi phi.', 'thai', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Không cay","Thanh đạm","Cơm nhà"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-103ea67cd56c9c96', 'mi-y-carbonara-ba-chi', 'Mì Ý Carbonara ba chỉ giòn', 'Mì Ý Carbonara chuẩn truyền thống thành Rome không hề dùng kem tươi mà tạo độ sánh mượt nhờ kỹ thuật nhũ tương hóa hỗn hợp trứng gà, phô mai Pecorino Romano bào mịn cùng mỡ ba chỉ muối giòn và nước luộc mì giàu tinh bột.', 'italian', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Carbonara","Ba chỉ","Béo mịn"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-34505f9722b38fc1', 'mi-y-bo-bam-bologna', 'Mì Ý bò bằm sốt Ragù Bologna', 'Sốt Ragù Bologna là tinh hoa ẩm thực miền Emilia-Romagna với thịt bò xay kết hợp thịt heo xay và ba chỉ muối xào xém, hầm liu riu hàng giờ cùng cà rốt, cần tây, hành tây, rượu vang đỏ và cà chua Passata tạo nên độ sánh đậm quyện vị.', 'italian', 90, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Ragù Bologna","Thịt bò bằm","Cuối tuần"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-266d7af134d7286a', 'mi-y-nam-kem', 'Mì Ý nấm đùi gà sốt kem', 'Mì Ý nấm đùi gà sốt kem là món pasta ấm áp, dễ nấu chỉ trong 30 phút. Nấm đùi gà giòn ngọt được xào vàng với bơ lạt và dầu ô liu rồi hòa quyện cùng kem tươi, sữa tươi và phô mai Parmesan béo ngậy.', 'italian', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Nấm đùi gà","Sốt kem","Nhanh gọn"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8b2c852ba59f2143', 'risotto-rau-bina-nam', 'Cơm Risotto rau bina và nấm', 'Cơm Risotto rau bina và nấm là sự kết hợp hài hòa giữa vị ngọt giòn của nấm đùi gà áp chảo, sắc xanh tươi mát từ cải bó xôi cùng hạt gạo Arborio mềm dẻo sóng sánh trong nước dùng rau củ, bơ lạt và phô mai Parmesan.', 'italian', 30, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Cơm Risotto","Rau bina","Nấm đùi gà","Thanh đạm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-de5ce12092f4f0aa', 'frittata-rau-bina-pho-mai', 'Trứng chiên kiểu Ý Frittata rau bina phô mai', 'Frittata rau bina phô mai là món trứng chiên dày kiểu Ý giàu đạm và chất xơ, dễ làm ngay trên bếp chảo chống dính mà không cần lò nướng. Rau bina được làm xẹp và vắt thật ráo nước để khối trứng chiên lên xốp mềm, thơm ngậy phô mai.', 'italian', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Frittata","Trứng chiên","Rau bina","Phô mai"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b8d2cb0b37dbdb81', 'ga-sot-chanh-bo-y', 'Ức gà áp chảo sốt chanh bơ kiểu Ý', 'Pollo al limone là món gà sốt chanh bơ thanh lịch đặc trưng của ẩm thực Ý. Ức gà cắt miếng đều được phủ lớp bột mì mỏng rồi áp chảo vàng ươm, sau đó rim nhẹ trong nước cốt và vỏ chanh vàng cùng hương thảo, hoàn thiện với bơ lạt lạnh tạo sốt bóng mượt.', 'italian', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Ức gà","Sốt chanh bơ","Áp chảo","Thanh nhẹ"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a4d02f2246e0e115', 'ga-cacciatore-nam', 'Gà om nấm sốt cà chua Cacciatore', 'Gà om nấm Cacciatore là món ăn đồng quê ấm áp của nước Ý. Đùi gà áo bột mỏng áp chảo xém da rồi được om chậm trong nền rau củ hành tây, cần tây, nấm đùi gà, rượu vang trắng và cà chua chín mọng thơm mùi hương thảo, lá nguyệt quế.', 'italian', 40, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Cacciatore","Đùi gà om","Nấm đùi gà","Cà chua"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a60814a4aca4143b', 'vien-thit-polpette-ca-chua', 'Thịt viên bò sốt cà chua Polpette', 'Polpette là món thịt viên om sốt cà chua truyền thống trong bữa cơm gia đình Ý. Thịt bò xay được nhào cùng ruột bánh mì gối tươi, trứng gà, nhục đậu khấu và phô mai Parmesan, Pecorino giúp viên thịt mềm ẩm mà không bị khô, sau đó thả trực tiếp vào sốt cà chua ninh sánh.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Polpette","Thịt bò viên","Sốt cà chua","Gia đình"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-5504378372dc989b', 'sup-minestrone-rau-cu', 'Súp rau củ Ý Minestrone', 'Súp Minestrone là món canh rau củ truyền thống giàu chất xơ của nước Ý. Hàng chục loại rau củ tươi được cắt hạt lựu đều nhau rồi cho vào nồi theo từng đợt chín dần, hòa quyện cùng đậu trắng bùi béo và bó thơm hương thảo, nguyệt quế.', 'italian', 45, 5, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Súp Minestrone","Rau củ","Thanh nhẹ","Mùa lạnh"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b6496331f7aa0ee9', 'mi-y-tom-kem-chanh', 'Mì Ý tôm tươi sốt kem chanh', 'Mì Ý tôm tươi sốt kem chanh là món pasta hải sản sang trọng nhưng chế biến gọn nhẹ. Vị ngọt tự nhiên của tôm tươi hòa cùng sốt kem tươi sánh mịn, phô mai Parmesan và vị chua dịu từ vỏ, nước cốt chanh vàng giúp món ăn béo mà không hề ngán.', 'italian', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Tôm tươi","Sốt kem chanh","Hải sản"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d6f7b2ef8f347338', 'canh-dua-suon-non', 'Canh dứa sườn non', 'Canh dứa sườn non là món canh khai vị quen thuộc trong bữa cơm Nam Bộ. Sườn non được chần sạch rồi hầm liu riu ra nước ngọt thanh, nấu cùng dứa chín và cà chua tạo vị chua ngọt tự nhiên rất bắt cơm.', 'vietnamese', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Sườn non","Dứa chín","Nam Bộ","Chua ngọt"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-5e0564249085d9c1', 'canh-tom-bong-cai', 'Canh tôm bông cải xanh', 'Canh tôm bông cải xanh là món canh nấu nhanh giàu đạm và chất xơ. Tôm tươi bóc vỏ giã dập nhẹ hoặc giữ nguyên con nấu cùng bông cải xanh giòn ngọt, tạo nên bát canh trong thanh, nhẹ bụng cho cả gia đình.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Tôm tươi","Bông cải xanh","Thanh mát","Nấu nhanh"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9daae727e7894587', 'canh-ga-bap-cai-ngot', 'Canh gà nấu bắp cải ngọt', 'Canh gà nấu bắp cải ngọt mang đến hương vị thanh dịu dễ ăn. Thịt đùi gà chặt miếng ướp nhẹ gừng hành rồi ninh mềm, kết hợp cùng bắp cải và cà rốt tiết ra vị ngọt tự nhiên giúp nước canh trong lành và đậm đà.', 'vietnamese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Đùi gà","Bắp cải","Cà rốt","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-20123919cd3164a8', 'canh-ca-hoi-ca-chua', 'Canh chua cá hồi cà chua dứa', 'Canh chua cá hồi cà chua dứa kết hợp miếng cá hồi giàu béo mềm ngọt với hương vị canh chua truyền thống gồm dứa thơm, cà chua, măng chua, dọc mùng và rau ngổ. Nước canh đậm đà chua thanh dịu nhẹ, rất hợp cơm ngày nóng.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Cá hồi","Canh chua","Hải sản","Bổ dưỡng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d500b08871587628', 'tom-kho-dua-keo', 'Tôm kho dứa sánh keo', 'Tôm tươi thịt chắc ngọt quyện trong lớp nước sốt dứa chín chua dịu sánh keo bám bóng màu đỏ cam, thơm mùi hành tỏi phi và tiêu xay cay ấm.', 'vietnamese', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món kho","Tôm tươi","Dứa chín","Nam Bộ","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-c7e40140f9ee9591', 'ga-kho-sa-ot-do', 'Gà kho sả ớt đỏ', 'Đùi gà chặt miếng săn chắc thấm đẫm hương thơm nồng của sả băm và ớt hiểm đỏ cay dịu, nước sốt thắng caramel nâu đỏ sánh bóng cực kỳ bắt cơm.', 'vietnamese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gà kho sả ớt","Nam Bộ","Món kho","Đưa cơm","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ebbd704089d9c62a', 'ga-xao-hanh-tay', 'Gà xào hành tây sốt dầu hào', 'Gà xào hành tây sốt dầu hào có lớp thịt đùi gà mềm mọng không bị khô, thấm đẫm hương sả, hành tím và tỏi phi quyện trong nước sốt mặn ngọt hài hòa cùng những múi hành tây chín tới giòn ngọt thanh.', 'vietnamese', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Hành tây","Đậm đà","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b7ae5824ff7e6a74', 'su-su-xao-toi', 'Su su xào tỏi', 'Su su xào tỏi là món rau xào thanh mát, mộc mạc mà đưa cơm với những lát su su non giòn ngọt không hề bị nhựa hay nhũn, quyện hương thơm nồng nàn của tỏi đập dập phi vàng và chút vị đậm đà từ nước mắm ngon.', 'vietnamese', 8, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau củ","Thanh đạm","Dưới 20 phút","Miền Trung"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-30c2038c8737538c', 'bo-xao-nam-dui', 'Bò xào nấm đùi gà', 'Bò xào nấm đùi gà là sự kết hợp tuyệt vời giữa từng lát thịt bò thăn mềm ngọt và những miếng nấm đùi gà giòn dai sần sật, hút trọn vị ngọt của thịt bò cùng hương thơm dầu hào, tỏi phi và tiêu đen.', 'vietnamese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Nấm","Đậm đà","Cơm nhà"]', 18, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-019bbf517408a529', 'ca-chien-sot-ca-chua', 'Cá chiên sốt cà chua', 'Cá chiên sốt cà chua là món ăn gia đình quen thuộc với khúc cá thịt trắng béo ngọt được chiên vàng đều hai mặt giữ độ săn chắc, sau đó rim nhỏ lửa trong phần sốt cà chua chín đỏ sánh mịn quyện hương thơm hành tím, tỏi và dầu hào.', 'vietnamese', 22, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Cá thu","Sốt cà chua","Nam Bộ","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d7836b7d1a4d90b3', 'nam-chien-gion', 'Nấm đùi gà chiên giòn', 'Nấm đùi gà chiên giòn là món ăn vặt lẫn món mặn đưa cơm rất bắt miệng. Thân nấm đùi gà được chần sơ vắt ráo để giữ độ dai ngọt tự nhiên, nhúng qua trứng gà rồi áo bột năng khô chiên hai lửa cùng lá húng quế, tạo lớp vỏ giòn tan mà bên trong vẫn mềm mọng.', 'vietnamese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Nấm đùi gà","Giòn rụm","Ăn vặt","Trẻ em thích"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9d527dacd46efc67', 'dau-phu-chien-sa', 'Đậu phụ chiên sả ớt chay', 'Đậu phụ chiên sả ớt chay là món ăn dân dã nhưng cực kỳ gây nghiện nhờ sự kết hợp giữa miếng đậu phụ chiên vỏ giòn ruột béo và lớp sả ớt phi thơm giòn đậm vị nước tương, hạt nêm chay. Món thực hiện nhanh gọn, phù hợp cả bữa cơm chay lẫn mặn.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Món chay","Đậu phụ","Sả ớt","Nam Bộ"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-236e3b84d403909e', 'ga-luoc-hanh-la', 'Đùi gà luộc hành lá da vàng giòn', 'Đùi gà góc tư luộc vừa sôi rồi ủ chín từ từ giúp thịt mềm ngọt giữ trọn nước, không bị nứt rách da hay đỏ xương; sốc lạnh nhanh cho lớp da giòn sần sật ánh vàng hấp dẫn.', 'vietnamese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món luộc","Gà ta","Giản dị","Cơm nhà","Thanh đạm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-df7571988423623f', 'muc-hap-sa-ot', 'Mực tươi hấp sả ớt kiểu miền Trung', 'Mực tươi làm sạch nguyên con hoặc cắt khoanh, ướp nhẹ nước mắm đường tiêu rồi hấp lửa lớn cùng sả đập dập, gừng, ớt hiểm và hành lá; thịt mực trắng giòn ngọt lịm chấm nước mắm chanh ớt đúng điệu miền Trung.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Mực","Sả","Miền Trung","Dưới 20 phút"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2b88b3e83b941e80', 'goi-su-su-tom', 'Gỏi su su tôm giòn mát', 'Gỏi su su tôm giòn mát mang vị thanh sạch lạ miệng với từng sợi su su và cà rốt ướp muối vắt ráo giòn sần sật, kết hợp tôm tươi luộc chín đỏ au chẻ đôi, rau răm thơm nồng, hành tím phi giòn và lạc rang bùi béo.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi su su","Tôm tươi","Thanh mát","Khai vị","Miền Trung"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0b34a73de8ccab71', 'goi-dau-phu-dua-leo', 'Gỏi đậu phụ dưa leo chay thanh mát', 'Gỏi đậu phụ dưa leo là món khai vị chay thanh đạm mà đậm vị với từng miếng đậu phụ chiên vàng giòn bên ngoài mềm béo bên trong, quyện cùng dưa leo và cà rốt bóp muối vắt khô giòn sần sật, rau thơm và đậu phộng rang bùi thơm.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi chay","Đậu phụ","Dưa leo","Thanh đạm","Mát lành"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0ea0e53318af9de9', 'bun-bo-nam-bo-tron', 'Bún bò Nam Bộ trộn', 'Tô bún bò Nam Bộ trộn hài hòa giữa vị thịt bò xào sả tỏi mềm mọng nóng hổi, bún tươi thanh mát, rau thơm, giá đỗ giòn sần sật cùng hành phi thơm lừng, đậu phộng rang bùi béo và nước mắm chua ngọt.', 'vietnamese', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Bún bò Nam Bộ","Món trộn","Thịt bò xào","Thanh mát"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-1fa2a5a65ec5a26d', 'bun-rieu-cua-dau', 'Bún riêu cua đậu', 'Tô bún riêu cua đậu thanh thuần vị quê nhà nổi bật với tảng riêu cua đồng xốp béo, phần nước gạch cua phi hành đỏ óng cùng cà chua, đậu phụ chiên giòn và hương thơm dịu của giấm bỗng.', 'vietnamese', 40, 4, 'hard', '/frigo/illustrations/delicious-meal.png', '["Bún riêu","Cua đồng","Đậu phụ rán","Ẩm thực miền Bắc"]', 30, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ff6d8fe6659e4976', 'bun-cha-ha-noi', 'Bún chả Hà Nội', 'Bún chả Hà Nội chế biến gọn gàng tại nhà với chả miếng ba chỉ và chả viên nạc vai ướp nước hàng, mắm tôm, cốt sả hành, nướng lò vàng bóng không khô, hòa quyện cùng nước chấm ấm và dưa góp đu đủ cà rốt.', 'vietnamese', 30, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Bún chả","Hà Nội","Món nướng lò","Bữa trưa"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-675a6c1cea0b604e', 'com-rang-chay-nam-dau', 'Cơm rang chay nấm đậu phụ rau củ', 'Đĩa cơm rang chay đầy đủ dưỡng chất và màu sắc bắt mắt với từng hạt cơm nguội rang tơi ráo bóng nhẹ, hòa quyện cùng nấm đùi gà dai ngọt, đậu phụ cắt hạt lựu béo mềm, cà rốt giòn tươi và mùi thơm quyến rũ của tỏi phi, hành lá.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Cơm rang","Đậu phụ","Nấm đùi gà","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4dbcf05ec1f88763', 'nam-xao-sa-ot-chay', 'Nấm đùi gà xào sả ớt chay', 'Món xào chay đậm đà đưa cơm với từng lát nấm đùi gà giòn dai thấm đẫm nước tương mặn ngọt, phủ đầy sả phi thơm lừng, ớt hiểm cay ấm cùng chút mè trắng rang bùi béo và hành lá xanh tươi.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Nam Bộ","Nấm đùi gà","Xào sả ớt","Đậm vị"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b88c09328fa3f33a', 'goi-cuon-chay-nam-dau', 'Gỏi cuốn chay nấm đậu phụ', 'Những cuốn gỏi chay tròn đầy thanh mát với lớp bánh tráng dẻo mỏng ôm trọn nhân đậu phụ chiên tẩm nước tương đậm vị, nấm đùi gà xào dai ngọt, bún gạo tươi, cà rốt, dưa leo, giá đỗ và rau thơm giòn tươi, chấm cùng nước tương chanh ớt mè rang.', 'vietnamese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Gỏi cuốn","Nam Bộ","Mát lành","Bánh tráng"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-66711b78b6c12643', 'com-tam-suon-nuong', 'Cơm tấm sườn nướng', 'Đĩa cơm tấm sườn nướng chuẩn vị Sài Gòn với miếng sườn cốt lết ướp sữa tươi mật ong nướng vàng ươm mềm mọng, hạt cơm tấm tơi dẻo phủ mỡ hành béo xanh, trứng gà ốp la lòng đào, đồ chua củ cải cà rốt giòn thanh và chén nước mắm chua ngọt kẹo.', 'vietnamese', 30, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cơm tấm","Sườn nướng","Nam Bộ","Quốc dân","Mỡ hành"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6a3a83f38e6d3f9c', 'chao-bo-gung', 'Cháo bò gừng', 'Tô cháo bò gừng nóng hổi thơm lừng với hạt gạo tẻ kết hợp gạo nếp rang thơm nở bung sánh mịn, lát thịt bò thăn mềm ngọt chín tái tới ngay trong cháo sôi cùng gừng tươi thái chỉ, hành lá và lá tía tô giải cảm ấm người.', 'vietnamese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cháo bò","Gừng ấm","Ăn sáng","Bổ dưỡng","Ấm bụng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b1dcb812f8671a49', 'banh-trang-nuong-pho-mai', 'Bánh tráng nướng phô mai', 'Món bánh tráng nướng phô mai kiểu Đà Lạt hấp dẫn ngay trên chảo chống dính với đế bánh tráng gạo giòn tan, lớp trứng gà hành lá béo thơm phủ đầy phô mai mozzarella tan chảy kéo sợi, xúc xích thái lát, hành tím phi và tương ớt mayonnaise.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Bánh tráng nướng","Phô mai","Nam Bộ","Ăn vặt","Dưới 20 phút"]', 8, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8f24a253602fc9be', 'lau-ca-chua-dua', 'Lẩu cá chua dứa miền Tây', 'Lẩu cá chua dứa miền Tây mang hương vị thanh mát đặc trưng vùng sông nước. Cá diêu hồng tươi cắt khúc nấu chín vừa tới giữ thịt trắng ngọt săn chắc, hòa quyện nước lẩu chua dịu từ dứa chín, cà chua và chanh tươi, thơm lừng mùi sả, gừng, ngò gai và rau ngổ.', 'vietnamese', 40, 5, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Cá diêu hồng","Dứa chín","Miền Tây","Chua ngọt"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-cd86ce166f002f60', 'suon-ham-tuong-dau', 'Sườn non hầm tương đậu đen', 'Món hầm truyền thống Trung Hoa nổi bật với hương vị bùi mặn đặc trưng của đậu tương đen lên men (tàu xì) quyện cùng xì dầu, rượu Thiệu Hưng và gừng tỏi thơm nồng, thấm sâu vào từng miếng sườn non mềm rục.', 'chinese', 65, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món hầm","Sườn non","Tàu xì","Đậm đà","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3e8e08fb584de7f3', 'bo-ham-gung-dam', 'Thịt bò hầm gừng cà rốt đậm vị', 'Món bò hầm chuẩn vị gia đình Trung Hoa ấm nồng mùi gừng tươi thái lát, hoa hồi và lá nguyệt quế, hòa quyện vị cay nhẹ từ tương đậu bản Tứ Xuyên cùng nước dùng bò sánh đậm ôm trọn từng miếng thịt bò mềm tan và cà rốt ngọt bùi.', 'chinese', 135, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thịt bò","Món hầm","Gừng ấm","Mùa lạnh","Đậm đà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-abcc9b72400680cf', 'trung-cuon-hanh-la-trung', 'Trứng cuộn hành lá áp chảo kiểu Trung', 'Món trứng cuộn hành lá đơn giản nhưng tinh tế của bếp Hoa, tráng từng lớp mỏng trên chảo chống dính với chút bột bắp và rượu Thiệu Hưng giúp trứng xốp mềm ẩm mượt, cuộn tròn cắt khúc gọn đẹp rồi rưới xì dầu nhạt thơm dịu.', 'chinese', 10, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Trứng cuộn","Nhanh gọn","Khai vị","Bữa sáng","Trung Hoa"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-26359a897d4be366', 'sup-tom-nam-trung', 'Súp tôm nấm đùi gà gừng ấm', 'Món súp khai vị nhẹ bụng mà giàu dinh dưỡng kiểu nhà hàng Trung Hoa: nước dùng gà thanh ngọt quyện hương gừng tươi ấm áp, những lát nấm đùi gà dai ngọt tự nhiên và thịt tôm ướp rượu Thiệu Hưng chín tới hồng hào giòn sần sật.', 'chinese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Súp","Tôm tươi","Nấm đùi gà","Thanh ngọt","Khai vị"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-00e0b1417e11b291', 'dau-phu-xao-hanh-tay', 'Đậu phụ chiên giòn xào hành tây', 'Những miếng đậu phụ cứng thấm khô áo lớp bột bắp mỏng chiên vàng giòn rụm hai mặt, sau đó đảo nhanh trên chảo nóng cùng hành tây ngọt thanh, gừng tỏi phi thơm và nước sốt xì dầu đậm – nhạt quyện vị dịu của rượu Thiệu Hưng và đường nâu.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Đậu phụ","Xào","Hành tây","Chay","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-45274582db71eb9f', 'mi-xao-tom-quang-dong', 'Mì xào tôm cải bắp kiểu Quảng Đông', 'Đĩa mì xào kiểu Quảng Đông đậm đà hương chảo nóng với từng sợi mì trứng mềm dai không bết dính, hòa quyện vị ngọt mặn dịu của dầu hào, xì dầu và dầu mè, kết hợp tôm tươi săn giòn cùng bắp cải thái sợi và giá đỗ giòn mát.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì xào","Quảng Đông","Tôm tươi","Bắp cải","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3d2e5735cbfe9654', 'tom-rang-muoi-tieu', 'Tôm rang muối tiêu ớt kiểu Hồng Kông', 'Món tôm rang muối tiêu trứ danh của ẩm thực Hồng Kông với từng con tôm nguyên vỏ áo bột bắp mỏng chiên giòn tan đến mức ăn được cả vỏ, xóc nhanh cùng bột tiêu Tứ Xuyên rang muối biển thơm lừng, tỏi phi vàng giòn và ớt hiểm cay nồng.', 'chinese', 15, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Tôm rang","Muối tiêu","Hồng Kông","Giòn rụm","Khai vị"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-73568e9a99d0ccdf', 'trung-xao-hanh-tay', 'Trứng xào hành tây mềm thơm kiểu Trung', 'Món xào gia đình quen thuộc của bếp Trung Hoa hoàn thành chỉ trong 15 phút: trứng gà đánh cùng chút sữa tươi và mayonnaise nên cực kỳ mềm xốp, quyện cùng hành tây xào ẩm với nước lọc giữ trọn vị ngọt tự nhiên.', 'chinese', 10, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Trứng xào","Hành tây","Nhanh gọn","Cơm nhà","Bữa sáng"]', 5, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a17f5a86a1bc891c', 'ba-chi-luoc-cham-tuong', 'Thịt ba chỉ luộc thái mỏng rưới sốt tỏi ớt Tứ Xuyên', 'Món ba chỉ luộc sốt tỏi (Toán Nê Bạch Nhục) trứ danh vùng Tứ Xuyên: thịt ba chỉ nguyên tảng luộc liu riu cùng gừng, hành, hoa hồi và tiêu Tứ Xuyên cho mềm mọng, thái lát mỏng mượt rồi chan sốt xì dầu giấm đen, tỏi băm và dầu ớt thơm lừng.', 'chinese', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thịt ba chỉ","Luộc","Tứ Xuyên","Khai vị","Mùa hè"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-fbbe89a1039604fc', 'nam-xao-toi-trung', 'Nấm đùi gà xào tỏi nước tương', 'Món nấm xào 10 phút đậm hương vị nhà hàng Trung Hoa: nấm đùi gà thái khoanh dày khía caro áp chảo xém cạnh săn giòn, rồi quyện cùng hỗn hợp tỏi phi thơm lẫn tỏi sống băm nhuyễn, xì dầu nhạt và chút dầu hào dậy vị ngọt tự nhiên.', 'chinese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nấm đùi gà","Xào tỏi","Nhanh gọn","Chay","Cơm nhà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3ee45f761eb0b78d', 'mi-lanh-ga-trung', 'Mì lạnh gà xé dưa leo sốt mè Tứ Xuyên', 'Tô mì lạnh gà xé Tứ Xuyên giải ngấy lý tưởng cho ngày nắng nóng: ức gà ủ chín mềm mọng nước rồi xé sợi tơi, kết hợp sợi mì luộc xả lạnh dai giòn, dưa leo bào sợi mát lành và nước sốt tương mè béo bùi quyện giấm đen, xì dầu, dầu ớt và tiêu Tứ Xuyên tê dịu.', 'chinese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì lạnh","Ức gà","Sốt mè","Tứ Xuyên","Giải nhiệt"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-cbb5635bfe848a49', 'ga-om-gung-tuong', 'Đùi gà om gừng xì dầu kiểu Hoa', 'Món đùi gà om xì dầu đậm vị cơm nhà Trung Hoa: thịt đùi gà có xương giữ trọn độ mọng ngọt sau khi áp chảo vàng da, om thấm đẫm hương gừng tươi thái lát ấm nồng, hồi quế, đường nâu và hai loại xì dầu tạo nước sốt nâu bóng sánh đẹp.', 'chinese', 45, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Đùi gà","Món om","Gừng tươi","Xì dầu","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-7bf9327b2c48f2d4', 'suon-nuong-tuong', 'Sườn non nướng tương mật ong kiểu Hoa', 'Những dẻ sườn non nướng kiểu xá xíu Trung Hoa hấp dẫn với vị mặn ngọt hài hòa từ xì dầu nhạt, tương đen Hoisin, rượu Thiệu Hưng và ngũ vị hương, nướng chín mềm ẩm trong lò rồi phết mật ong lửa lớn tạo lớp vỏ caramel óng ả xém cạnh.', 'chinese', 55, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Sườn nướng","Mật ong","Ngũ vị hương","Cuối tuần","Tiệc nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4)
INSERT INTO recipes (id, slug, title, description, cuisine, cook_time_minutes, servings, difficulty, image_url, tags, prep_time_minutes, source_type, source_reference, verification_state, version) VALUES
('imp-bbfdcf2e3b277fed', 'soba-nong-ga', 'Mì Soba nóng thịt gà', 'Mì Soba nóng thịt gà (Torinanban Soba) là món mì nước ấm áp kinh điển của Nhật Bản, kết hợp nước dùng Dashi truyền thống từ tảo bẹ Kombu và cá bào Katsuobushi, đùi gà áp chảo da vàng giòn, hành boa-rô xém ngọt cùng chút gừng mài thơm nồng.', 'japanese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì Soba","Thịt gà","Nước dùng Dashi","Ẩm thực Nhật","Mì nước"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f2334219f33e48d0', 'tom-nuong-muoi-nhat', 'Tôm nướng muối kiểu Nhật', 'Tôm nướng muối kiểu Nhật (Ebi Shioyaki) tôn vinh trọn vẹn vị ngọt tự nhiên của tôm sú nguyên vỏ, chỉ cần ướp nhanh với rượu Sake khử tanh, xiên que giữ thân thẳng đẹp và phủ lớp muối hạt nướng xém vỏ giòn thơm.', 'japanese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Shioyaki","Hải sản","Ẩm thực Nhật","Món nướng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8f6eeb8b34b7cd65', 'com-muc-nuong', 'Cơm mực nướng sốt Teriyaki', 'Cơm mực nướng sốt Teriyaki (Ikayaki Don) mang hương vị quán ăn lễ hội Nhật Bản, kết hợp cơm trắng gạo hạt ngắn dẻo ngọt cùng mực ống nguyên con áp chảo xém cạnh thơm lừng, áo lớp sốt xì dầu Sake Mirin gừng tươi sánh bóng đậm đà.', 'japanese', 40, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cơm mực","Mực nướng","Teriyaki","Ẩm thực Nhật","Hải sản"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9e4ad3e4074d2a1c', 'salad-bap-cai-tom-nhat', 'Salad bắp cải tôm Nhật', 'Salad bắp cải tôm kiểu Nhật kết hợp bắp cải thái sợi mỏng, cà rốt giòn ngọt và hành tây ngâm lạnh hết hăng cùng tôm sú luộc đỏ au săn chắc, áo đều lớp sốt Mayonnaise pha mật ong, giấm gạo, chanh tươi và chút xì dầu thanh dịu.', 'japanese', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Salad Nhật","Bắp cải","Tôm tươi","Món trộn","Thanh mát"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4023e971948407f6', 'ca-hoi-om-ca-chua', 'Cá hồi om cà chua kiểu Nhật', 'Món cá hồi om cà chua phong cách gia đình Nhật kết hợp vị béo ngậy của phi lê cá hồi áp chảo với nước sốt cà chua tươi chua dịu, ngọt thanh hành tây và hương thơm umami từ nấm cùng xì dầu Nhật Bản.', 'japanese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Cá hồi","Cà chua","Cơm nhà","Bữa tối ấm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-76ddca35768468fe', 'bo-nuong-yakiniku-muoi', 'Bò nướng Yakiniku muối chanh', 'Phiên bản Yakiniku vị thanh kiểu Nhật không ướp sốt ngọt dày, giữ trọn vị ngọt thịt của lát bò thăn nướng cháy cạnh, kết hợp muối tiêu, vị chua thơm của chanh tươi và chén sốt hành lá dầu mè Negi-shio béo thơm.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Yakiniku","Thịt bò nướng","Sốt Negi-shio","Cuối tuần","Nhật Bản"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-1bbb2341036dd966', 'bong-cai-tron-me-nhat', 'Bông cải xanh trộn mè Nhật (Goma-ae)', 'Món rau phụ Goma-ae truyền thống của Nhật Bản với bông cải xanh chần vừa chín tới giòn ngọt tự nhiên, quyện lớp sốt bùi béo từ mè trắng rang giã dập hòa cùng xì dầu Nhật, Sake, Dashi và mật ong.', 'japanese', 8, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Goma-ae","Bông cải xanh","Món phụ Nhật","Thanh đạm","Mè rang"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-5ed977305ac677b6', 'com-bo-hanh-nhat', 'Cơm bơ xì dầu hành lá Nhật Bản', 'Món cơm trộn Butter Shoyu Gohan kinh điển của Nhật Bản: hơi nóng từ cơm mới nấu làm viên bơ lạt tan chảy, hòa quyện vị mặn thanh của xì dầu Nhật, hành lá tươi, cá bào Katsuobushi và rong biển Nori giòn thơm.', 'japanese', 5, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm bơ Nhật","Bữa sáng nhanh","Nhật Bản","Đơn giản","Tiện lợi"]', 5, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-57294c4da3e61e24', 'sup-miso-tom-nam', 'Súp Miso tôm nấm đùi gà', 'Bát súp Miso hải sản chuẩn vị Nhật Bản kết hợp vị ngọt tự nhiên từ tôm tươi nấu cùng rượu Sake khử tanh, nấm đùi gà cắt lát sần sật, rong biển Wakame mềm mượt và tương Miso hòa tan sau khi tắt bếp giữ trọn hương thơm.', 'japanese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Súp Miso","Tôm tươi","Nấm đùi gà","Canh Nhật","Ấm bụng"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ea9ba867b7d2c6ad', 'ga-hap-gung-bap-cai', 'Ức gà hấp gừng bắp cải kiểu Nhật', 'Món ức gà hấp kiểu Nhật nhẹ nhàng, giàu đạm và ít dầu mỡ: thịt ức gà hấp chín tới trên nền bắp cải ngọt giúp giữ độ ẩm mềm, sau đó xé sợi trộn sốt nước tương Ponzu, gừng bào và dầu mè thơm bùi.', 'japanese', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Ức gà","Bắp cải","Thanh đạm","Nhật Bản"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-7d764feba948bce3', 'canh-kimchi-ca', 'Canh kim chi cá hồi đậu phụ', 'Canh kim chi cá hồi đậu phụ là biến tấu đậm đà của món kimchi jjigae truyền thống Hàn Quốc. Vị chua cay tự nhiên của kim chi cải thảo lên men kỹ hòa cùng thịt cá hồi béo ngọt và đậu phụ thanh mát, rất đưa cơm trong những ngày se lạnh.', 'korean', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Canh kim chi","Hàn Quốc","Cá hồi","Đậu phụ","Cay ấm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a24e0f07380bfdc2', 'suon-ham-galbi-han', 'Sườn bò hầm kiểu Hàn (Galbi Jjim)', 'Sườn bò hầm Galbi Jjim là món ăn truyền thống trong các dịp lễ tiệc của Hàn Quốc. Từng dẻ sườn bò được ngâm chần kỹ để sạch tạp chất rồi hầm liu riu với nước ngâm nấm hương, nước tương và rượu mirin đến khi thịt mềm róc xương, phủ lớp sốt nâu bóng óng ánh.', 'korean', 110, 5, 'hard', '/frigo/illustrations/delicious-meal.png', '["Galbi jjim","Sườn bò","Món tiệc","Hàn Quốc","Hầm mềm"]', 45, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-706c3678abea88b4', 'trung-chien-tron-han', 'Trứng chiên hành lá kiểu Hàn (Gyeran Jeon)', 'Gyeran Jeon là món trứng chiên tròn dẹt giản dị nhưng rất được ưa chuộng trong bữa cơm gia đình và hộp cơm trưa Hàn Quốc. Trứng đánh kỹ chiên trên chảo chống dính với lượng dầu vừa đủ cho mặt ngoài vàng đều, viền giòn nhẹ và bên trong mềm ẩm thơm hành lá.', 'korean', 10, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gyeran jeon","Trứng chiên","Hàn Quốc","Món nhanh","Hộp cơm"]', 8, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d88e008b28a31151', 'muc-xao-kimchi', 'Mực xào kim chi cay đậm kiểu Hàn', 'Món mực xào kim chi (Ojingeo Kimchi Bokkeum) kết hợp độ giòn ngọt tự nhiên của mực tươi khứa caro với vị chua cay đậm đà từ kim chi cải thảo chín kỹ và tương ớt Gochujang. Kỹ thuật xào nhanh lửa lớn giữ cho mực không ra nước và sốt áo bóng đều từng miếng.', 'korean', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mực xào","Kim chi","Hàn Quốc","Cay đậm","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3ec4d8a534fc8861', 'ga-nuong-bulgogi', 'Gà nướng Bulgogi kiểu Hàn (Dak Bulgogi)', 'Gà nướng Bulgogi (Dak Bulgogi) sử dụng phần đùi gà mềm mọng ướp đậm đà trong hỗn hợp nước tương, đường nâu, mật ong, rượu mirin, dầu mè và gừng tỏi. Khi nướng hoặc áp chảo trên lửa vừa-cao, lớp gia vị caramel hóa tạo bề mặt vàng xém thơm lừng mà thịt bên trong vẫn mọng nước.', 'korean', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Dak bulgogi","Gà nướng","Hàn Quốc","Mặn ngọt","Cuốn rau"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-750cef719bf5f2f6', 'chao-kimchi-han', 'Cháo kim chi trứng kiểu Hàn (Kimchi Juk)', 'Cháo kim chi Hàn Quốc (Kimchi Juk) là món cháo nóng hổi thanh nhẹ nhưng giàu hương vị nhờ bước xào kim chi chua cùng dầu mè và ép nhẹ cơm cho thơm béo trước khi ninh. Trứng gà được ủ chín mềm trong cháo nóng, kết hợp cùng rong biển vụn và hành lá tạo nên tô cháo ấm bụng cho bữa sáng hoặc ngày se lạnh.', 'korean', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Kimchi juk","Cháo Hàn","Bữa sáng","Cay ấm","Trứng gà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-28d20ebe44b82a22', 'nam-xao-tuong-han', 'Nấm đùi gà xào tương kiểu Hàn', 'Nấm đùi gà xào tương là món banchan (món phụ) quen thuộc trên mâm cơm Hàn Quốc nhờ cách làm nhanh gọn chỉ trong 20 phút. Nấm đùi gà xào lửa vừa giữ được độ dai giòn sần sật, thấm đều hỗn hợp nước tương đặc, dầu hào và mè rang thơm bùi.', 'korean', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Banchan","Nấm đùi gà","Hàn Quốc","Xào tương","Món nhanh"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-922028bd2fb07eb8', 'dau-phu-chien-tuong-han', 'Đậu phụ chiên sốt tương hành kiểu Hàn (Dubu Buchim)', 'Đậu phụ chiên sốt tương hành (Dubu Jorim / Dubu Buchim) là món banchan truyền thống có mặt trong hầu hết bữa cơm Hàn Quốc. Miếng đậu phụ chắc được thấm khô và áp chảo vàng đều hai mặt rồi rim nhẹ trong nước tương, siro ngô, tỏi băm và ớt bột tạo nên lớp áo bóng mặn ngọt hài hòa.', 'korean', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Dubu buchim","Đậu phụ","Banchan","Hàn Quốc","Chiên sốt"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b575db6fcd68a387', 'canh-trung-han', 'Canh trứng kiểu Hàn (Gyeran Guk)', 'Canh trứng Gyeran Guk là món canh nhà quốc dân của Hàn Quốc vì chỉ mất 15 phút chế biến nhưng vô cùng ấm bụng và dễ tiêu hóa. Nước dùng đun cùng tảo bẹ kombu ngọt thanh tự nhiên, nêm nhẹ nước tương và nước mắm rồi rưới trứng gà đánh tan tạo thành những vân trứng mềm mịn như mây.', 'korean', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gyeran guk","Canh trứng","Hàn Quốc","Thanh đạm","Món nhanh"]', 5, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-53933600fa3853f3', 'bo-xao-nam-han', 'Thịt bò xào nấm kiểu Hàn', 'Thịt bò xào nấm kiểu Hàn kết hợp hương vị bulgogi mặn ngọt thơm dầu mè với nấm đùi gà thái lát dọc dai giòn và hành tây ngọt thanh. Thịt bò được thái mỏng ngang thớ và ướp thấm gia vị trước khi xào nhanh trên chảo nóng, giúp thịt mềm mọng mà không bị ra nước.', 'korean', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Bulgogi xào","Thịt bò","Nấm đùi gà","Hàn Quốc","Đưa cơm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-81fc284c0bafa826', 'tom-xao-sa-ot-thai', 'Tôm tươi xào sả ớt lá chanh kiểu Thái', 'Món tôm xào sả ớt kiểu Thái nổi bật nhờ sự kết hợp giữa sả băm, tỏi, ớt hiểm và lá chanh Kaffir thơm nồng đặc trưng, quyện cùng nước sốt xào sánh bóng từ dầu hào, xì dầu và đường thốt nốt.', 'thai', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món xào","Tôm tươi","Sả ớt","Đậm đà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-15e4185437e9198c', 'mi-xao-pad-thai-tom', 'Mì xào Pad Thai tôm truyền thống', 'Công thức Pad Thai tôm truyền thống cân chỉnh chuẩn cho 3 phần ăn, giữ nguyên kỹ thuật thắng caramen đường thốt nốt cùng nước cốt me chua dịu, đậu phụ ép chiên cạnh vàng và sợi trứng tơi quyện quanh từng sợi bánh phở.', 'thai', 20, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad Thai","Mì xào","Truyền thống","Tôm tươi"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-cc62ea4de6a7436b', 'goi-dua-tom-thai', 'Gỏi dứa tôm tươi chua cay kiểu Thái', 'Gỏi dứa tôm tươi kiểu Thái là món khai vị giải ngấy tuyệt vời với vị ngọt mọng tự nhiên của dứa chín hòa quyện tôm luộc giòn săn, vị chua cay mặn ngọt cân bằng và hương bạc hà the mát.', 'thai', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Gỏi trộn","Dứa chín","Tôm tươi","Khai vị"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3d7573766352454e', 'canh-ga-sa-thai', 'Canh gà nấu sả nấm chua thanh kiểu Thái (Tom Yum Gai)', 'Món canh gà sả nấm kiểu Thái mang hương vị chua cay thanh tao từ nước cốt me kết hợp chanh tươi, hành tím áp chảo thơm lừng cùng sả, riềng, lá chanh Thái, thịt đùi gà mềm ngọt và nấm đùi gà giòn sần sật.', 'thai', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Thịt gà","Nấm đùi gà","Chua cay"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-88fc351665d5e9fc', 'bo-xao-ot-thai', 'Bò xào ớt kiểu Thái', 'Bò xào ớt kiểu Thái là món xào lửa lớn nổi tiếng với từng lát thịt bò mềm mọng áo đều lớp sốt dầu hào, xì dầu đậm đà, hòa cùng vị cay thơm của ớt hiểm, tỏi phi và độ giòn ngọt tự nhiên của ớt chuông, hành tây.', 'thai', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Ẩm thực Thái","Cay nồng","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4ec49419e966f676', 'ca-nuong-muoi-sa', 'Cá diêu hồng nướng muối sả kiểu Thái', 'Cá diêu hồng nướng muối sả kiểu Thái (Pla Pao) giữ nguyên lớp vảy cá bọc muối hạt mịn giúp khóa trọn độ ẩm và vị ngọt tự nhiên của thớ thịt cá trắng bên trong, thơm dịu mùi sả và lá chanh Kaffir, chấm cùng sốt chanh tỏi ớt chua cay đặc trưng.', 'thai', 40, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món nướng","Cá diêu hồng","Ẩm thực Thái","Nướng muối","Tiệc gia đình"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e47b2f01ee81031a', 'mi-xao-dua-tom-thai', 'Mì xào dứa tôm kiểu Thái', 'Mì xào dứa tôm kiểu Thái kết hợp sợi hủ tiếu gạo dai mềm áo sốt me chua ngọt cùng tôm tươi săn giòn, dứa chín mọng nước, trứng gà tơi béo và đậu phộng rang bùi thơm, mang hương vị đường phố Bangkok tươi mới.', 'thai', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì xào","Pad Thai","Tôm tươi","Dứa thơm","Ẩm thực Thái"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-192973f6e1b702b5', 'dau-phu-chien-sot-cay-thai', 'Đậu phụ chiên sốt cay kiểu Thái', 'Đậu phụ chiên sốt cay kiểu Thái hấp dẫn với lớp vỏ ngoài chiên vàng giòn rụm, bên trong vẫn mềm béo, quyện cùng nước sốt chua cay mặn ngọt từ đường thốt nốt, nước cốt chanh, tương ớt và tỏi phi thơm lừng.', 'thai', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Đậu phụ chiên","Món chay","Khai vị","Ẩm thực Thái","Chua cay"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2a705e2ff35573b1', 'canh-chua-me-tom-thai', 'Canh chua me tôm kiểu Thái', 'Canh chua me tôm kiểu Thái (Gaeng Som) mang vị chua thanh dịu từ me chín kết hợp hậu ngọt của đường thốt nốt, nước dùng sánh nhẹ nhờ thịt cá phi lê nghiền mịn, ăn kèm tôm tươi ngọt thịt, cà chua và nấm đùi gà giòn ngon.', 'thai', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Canh chua","Tôm tươi","Gaeng Som","Ẩm thực Thái","Thanh mát"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f050984a2c4deb91', 'goi-nam-chua-cay-thai', 'Gỏi nấm chua cay kiểu Thái', 'Gỏi nấm chua cay kiểu Thái kết hợp ba loại nấm chần giòn ngọt là nấm đùi gà, nấm mỡ và nấm kim châm, trộn đều với hành tây tím, cà chua bi, cần tây và nước sốt chanh tỏi ớt chua cay mặn ngọt bùng vị, rắc đậu phộng rang bùi béo.', 'thai', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi nấm","Món chay","Khai vị","Ẩm thực Thái","Thanh mát"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8b874d97e90e00f0', 'ga-chien-sa-thai', 'Gà chiên sả kiểu Thái', 'Gà chiên sả kiểu Thái hấp dẫn với từng miếng thịt đùi gà mềm mọng bên trong, lớp vỏ ngoài giòn rụm áo phủ những sợi sả giã tơi chiên vàng ruộm, dậy hương nồng nàn của rễ ngò rí, tiêu đen và lá chanh Kaffir.', 'thai', 15, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Đùi gà","Sả ớt","Ẩm thực Thái","Giòn rụm"]', 40, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b95544e75512c4e8', 'mi-y-toi-dau-ot', 'Mì Ý tỏi dầu ớt kiểu truyền thống', 'Mì Ý tỏi dầu ớt truyền thống chinh phục vị giác bằng sự thuần khiết: dầu ô liu nguyên chất thơm nức mùi tỏi lát phi dịu và vị cay ấm của ớt sừng đỏ, hoàn thiện bằng kỹ thuật xóc chảo với nước luộc mì tạo lớp sốt bóng mượt tự nhiên.', 'italian', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Aglio e Olio","Cay nhẹ","Nhanh gọn"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-5ae4665cc17ff036', 'mi-y-sot-cay-ca-chua', 'Mì Ý Penne sốt cà chua cay Arrabbiata', 'Penne all''Arrabbiata là món mì cay nổi tiếng vùng Lazio với cái tên mang nghĩa ''giận dữ'' bởi sắc đỏ rực của cà chua và vị cay bùng nổ từ ớt tươi. Mì ống Penne có rãnh nhỏ giúp ôm trọn phần sốt cà chua sánh đặc cùng hương ngò tây tươi mát.', 'italian', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Arrabbiata","Sốt cay","Cà chua"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9c48616208fff232', 'mi-y-bong-cai-xanh', 'Mì Ý sốt kem bông cải xanh hạnh nhân', 'Mì Ý bông cải xanh hạnh nhân là món pasta rau củ thanh mát, giàu dinh dưỡng với phần sốt xanh mướt được tạo nên từ một nửa bông cải xanh xay nhuyễn cùng hạnh nhân rang và phô mai Parmesan, kết hợp phần bông cải om mềm giữ nguyên nhánh tạo kết cấu thú vị.', 'italian', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Bông cải xanh","Hạnh nhân","Thanh đạm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b5571547ad5d2cec', 'mi-y-ca-hoi-bo-chanh', 'Mì Ý cá hồi sốt bơ chanh', 'Mì Ý cá hồi sốt bơ chanh là lựa chọn hoàn hảo cho bữa tối nhanh gọn mà vẫn tinh tế. Cá hồi áp chảo vừa chín mềm được hòa quyện cùng hành tím phi thơm, rượu vang trắng, nước cốt chanh vàng và bơ lạt đánh bóng ngoài bếp lửa.', 'italian', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Cá hồi","Bơ chanh","Nấu nhanh"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-7b5f0d33681ea7d2', 'ga-parmigiana-nuong', 'Gà Parmigiana nướng phô mai', 'Món gà Parmigiana kinh điển với từng lát ức gà dần mỏng tẩm bột chiên xù trộn phô mai Pecorino vàng giòn, phủ sốt cà chua húng quế nấu sánh và phô mai Mozzarella nướng chảy thơm lừng.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Gà Parmigiana","Ẩm thực Ý","Nướng lò","Phô mai","Món chính"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e3df53f1154592bc', 'ca-nuong-ca-chua-y', 'Cá nướng cà chua chanh vàng kiểu Ý', 'Phi lê cá thịt trắng chắc ngọt được ướp thấm vị nước cốt chanh vàng, tỏi và dầu ô liu, phủ lớp vụn bánh mì ngò tây giòn rụm rồi nướng lò cùng cà chua chín mọng tiết sốt chua ngọt tự nhiên.', 'italian', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cá nướng","Ẩm thực Ý","Cà chua","Chanh vàng","Ít béo"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a0ed6c762f7dceba', 'bo-pizzaiola', 'Bò om sốt cà chua lá Oregano (Pizzaiola)', 'Món bò Pizzaiola dân dã vùng Napoli với từng lát thịt bò dần mỏng mềm ngọt, thấm đẫm sốt cà chua nấu sánh thơm lừng mùi tỏi và thảo mộc Oregano đặc trưng.', 'italian', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Bò Pizzaiola","Ẩm thực Ý","Thịt bò","Cà chua","Món mặn"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2865ee57783628d7', 'salad-mi-y-nguoi', 'Salad mì Ý trộn nguội phô mai Feta', 'Đĩa salad mì Ý thanh mát mang phong vị Địa Trung Hải với những xoắn mì Fusilli chín vừa al dente quyện sốt dầu ô liu chanh vàng, cà chua mọng nước, dưa leo giòn ngọt và phô mai Feta béo mặn.', 'italian', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Salad mì Ý","Ẩm thực Ý","Món mát","Bữa trưa","Feta"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f9481ae10c0cc62a', 'sup-ca-chua-kem-y', 'Súp cà chua kem tươi kiểu Ý', 'Bát súp cà chua kem kiểu Ý mịn mượt như nhung với vị chua thanh tự nhiên từ cà chua chín hòa quyện độ béo dịu của sữa tươi, kem tươi và hương húng quế Tây thanh tao.', 'italian', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Súp kem cà chua","Ẩm thực Ý","Khai vị","Món nóng","Crouton"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e39ba043b6d1f19d', 'rau-cu-nuong-y', 'Rau củ nướng dầu ô liu kiểu Ý', 'Khay rau củ nướng vàng xém cạnh với bông cải xanh giòn ngọt, cà rốt bùi bở và hành tây thơm lừng mùi tỏi nướng caramel hóa, quyện dầu ô liu nguyên chất, giấm Balsamic Ý chua ngọt dịu và thảo mộc Oregano Địa Trung Hải.', 'italian', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Rau củ nướng","Món chay","Ẩm thực Ý","Món phụ","Thanh nhẹ"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f50c115d909f97f2', 'canh-nam-ca-chua-chua-nhe', 'Canh nấm cà chua chua nhẹ', 'Canh nấm cà chua chua nhẹ không dùng thịt nhưng vẫn ngọt thanh nhờ sự kết hợp giữa nấm đùi gà, nấm rơm hoặc nấm hương tươi cùng vị chua dịu từ cà chua chín và hương thơm ấm nhẹ của gừng, hành tỏi.', 'vietnamese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nấm đùi gà","Cà chua","Thanh đạm","Nấu nhanh"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ae5b053b8361f807', 'canh-tom-nau-sa-chua', 'Canh tôm nấu sả chua', 'Canh tôm nấu sả chua mang đậm phong vị miền Trung với nước dùng trong vắt, thơm nồng hương sả đập dập và cay nhẹ từ ớt hiểm, kết hợp thịt tôm tươi săn ngọt cùng vị chua thanh mát của cà chua và nước cốt chanh.', 'vietnamese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Tôm tươi","Miền Trung","Chua cay","Sả chanh"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ac77ed3af015efd7', 'canh-bo-bap-cai', 'Canh thịt bò nấu bắp cải', 'Canh thịt bò nấu bắp cải kết hợp vị ngọt đậm của thịt bò thăn thái lát với độ ngọt mát tự nhiên của bắp cải và cà chua. Nước canh trong trẻo, thơm dịu mùi tỏi phi và ngò rí, cực kỳ dễ ăn.', 'vietnamese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Bắp cải","Thanh ngọt","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4ec35a6c12daa33d', 'muc-kho-tieu', 'Mực kho tiêu', 'Những khoanh mực tươi trụng sơ giữ nguyên độ giòn sần sật, thấm đẫm nước kho mặn ngọt màu cánh gián quyện mùi hành tỏi phi thơm và tiêu đen xay cay nồng.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món kho","Mực tươi","Tiêu đen","Nam Bộ","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-01121ea953ffed76', 'suon-kho-trung', 'Sườn non kho trứng cút', 'Những miếng sườn non kho liu riu trong nước dừa tươi đến khi mềm rệu, kết hợp cùng trứng cút bùi béo thấm màu nâu hổ phách sóng sánh và hương thơm cay ấm của tiêu ớt.', 'vietnamese', 45, 5, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món kho","Sườn non","Trứng cút","Bắc Bộ","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-296b724137581830', 'dau-phu-kho-tieu', 'Đậu phụ kho tiêu', 'Những miếng đậu phụ vàng ruộm bên ngoài, mềm béo bên trong thấm đẫm sốt nước tương ngọt mặn hài hòa quyện vị cay ấm của tiêu đen xay và hương tỏi phi.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món kho","Đậu phụ","Món chay","Nhanh gọn","Đưa cơm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-54c8037962551d6b', 'gia-do-xao-toi', 'Giá đỗ xào tỏi', 'Giá đỗ xào tỏi là món rau cấp tốc giữ nguyên độ giòn mọng ngọt thanh tự nhiên của giá đỗ tươi, quyện mùi tỏi phi vàng thơm lừng và vị mặn dịu vừa vặn, cực kỳ hợp để giải ngấy trong bữa cơm gia đình.', 'vietnamese', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau củ","Thanh đạm","Dưới 20 phút","Cơm nhà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e75e90d847daa628', 'mi-xao-hai-san', 'Mì xào hải sản', 'Mì xào hải sản là món ăn đủ chất và rực rỡ sắc màu với những vắt mì trứng dai mềm không bết dính, ôm trọn tôm sú, mực ống tươi giòn cùng cải thìa, cà rốt, ớt chuông thấm đẫm sốt dầu hào và nước tương thơm lừng.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Mì xào","Nam Bộ","Đủ chất"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-1e6d5d1750d3aa51', 'ga-xao-ca-chua', 'Gà xào cà chua', 'Gà xào cà chua mang hương vị cơm nhà ấm cúng với từng miếng thịt đùi gà săn mềm mọng nước, thấm đẫm phần sốt cà chua chín nhừ đỏ au quyện xì dầu mặn ngọt dịu nhẹ và hành tây giòn thơm.', 'vietnamese', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Cà chua","Đậm đà","Cơm nhà"]', 18, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ce3c9df133ba1cd4', 'banh-trang-chien-trung', 'Bánh tráng chiên trứng', 'Bánh tráng chiên trứng là món ăn vặt đường phố Sài Gòn nổi tiếng nhờ sự kết hợp giữa miếng bánh tráng mỏng chiên phồng giòn rụm bên dưới và lớp trứng gà béo mềm bên trên, điểm thêm vị mặn thơm của ruốc sấy, hành phi, ớt hiểm và rau răm tươi.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Ăn vặt","Bánh tráng","Sài Gòn","Dưới 30 phút"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-1d4d9422e7f81e97', 'cua-hap-chanh-ot', 'Cua thịt hấp chanh sả ớt', 'Cua thịt tươi sống được chà rửa sạch và hấp cách thủy cùng sả cây đập dập, hành tây, gừng và ớt hiểm giúp khử mùi bùn biển, giữ nguyên từng thớ thịt trắng muốt ngọt đậm quyện chén muối tiêu chanh ớt.', 'vietnamese', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Hải sản","Cua biển","Món Nam","Đãi tiệc"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d3972d88e860aba9', 'goi-muc-chanh', 'Gỏi mực chanh ớt giòn ngọt', 'Gỏi mực chanh ớt là món khai vị hải sản thanh mát, nhanh gọn với từng khoanh mực ống trắng giòn ngọt tự nhiên không tanh, quyện hành lá chần dịu hăng, rau răm thơm nồng và nước trộn chanh tỏi ớt đậm vị chua cay hài hòa.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi mực","Hải sản","Chanh ớt","Khai vị","Miền Trung"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-68184b07a3c61cff', 'cuon-nem-nuong-banh-trang', 'Cuốn nem nướng bánh tráng chấm sốt nếp gan tôm', 'Cuốn nem nướng bánh tráng đậm chất miền Trung với những xiên nem thịt heo giò sống lẫn mỡ hạt lựu nướng vàng ruộm thơm sả, cuốn gọn trong bánh tráng cùng rau sống, giá đỗ, dưa leo, đồ chua và chén sốt gạo nếp tôm thịt gan heo béo bùi khó cưỡng.', 'vietnamese', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Nem nướng","Bánh tráng cuốn","Miền Trung","Nước chấm đặc biệt","Đãi tiệc"]', 45, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ed9f34ecd475d031', 'bun-dau-mam-tom', 'Bún đậu mắm tôm', 'Mẹt bún đậu mắm tôm đậm chất Hà thành quy tụ đủ hương vị từ đậu phụ mơ chiên vỏ giòn ruột béo, thịt ba chỉ luộc thái mỏng, chả cốm chiên thơm dẻo cùng bát mắm tôm pha quất, đường và dầu nóng đánh bông hấp dẫn.', 'vietnamese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Bún đậu mắm tôm","Hà Nội","Món mẹt","Ăn trưa"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a744a977e7e4b165', 'hu-tieu-muc', 'Hủ tiếu mực', 'Tô hủ tiếu mực Nam Bộ thanh nhẹ đầy đủ dinh dưỡng với nồi nước lèo trong vắt ngọt tự nhiên từ xương ống heo, củ cải trắng, tôm khô và khô mực nướng, kết hợp mực ống tươi giòn ngọt cùng thịt heo băm xào đậm đà.', 'vietnamese', 60, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hủ tiếu mực","Hải sản","Nước dùng trong","Nam Bộ"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-c67f536bef1c38d6', 'bap-cai-kho-nam-chay', 'Bắp cải kho nấm đùi gà chay', 'Món kho chay ấm áp đưa cơm với từng miếng bắp cải mềm ngọt mà vẫn giữ được thớ lá, hòa quyện nấm đùi gà giòn sần sật, cà rốt và đậu phụ chiên ngấm đẫm nước sốt tương sánh nhẹ thơm mùi hành boa-rô và tiêu xay.', 'vietnamese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Món kho","Bắp cải","Nấm đùi gà","Ngày rằm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-35deaaa123c7470d', 'nom-gia-chua-cay', 'Nộm giá đỗ chua cay chay', 'Đĩa nộm giá đỗ chua cay chay thanh mát chống ngán với từng cọng giá đỗ trắng mập giòn sần sật, cà rốt cam tươi bào sợi, quyện đều nước trộn nước mắm chay chanh tỏi ớt hài hòa, thơm dịu rau húng quế và bùi béo đậu phộng rang.', 'vietnamese', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Món nộm","Giá đỗ","Khai vị","Thanh mát"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-94b6bce7403fedc6', 'chao-nam-dau-phu', 'Cháo nấm đậu phụ', 'Tô cháo nấm đậu phụ thanh đạm dễ tiêu với hạt gạo tẻ kết hợp gạo nếp rang thơm sánh mịn, nấm đùi gà xào thơm giòn ngọt cùng đậu phụ trắng mềm béo, gừng tươi ấm bụng và hương xì dầu dịu nhẹ.', 'vietnamese', 28, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cháo chay","Nấm đùi gà","Đậu phụ","Thanh đạm","Dễ tiêu"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4f7a2cd919912ac9', 'mi-tron-trung-hanh', 'Mì trộn trứng hành', 'Món mì trộn trứng hành siêu tốc chỉ trong 10 phút nhưng đậm đà khó cưỡng với từng sợi mì dai bóng không nát áo đều sốt xì dầu nước mắm, hương dầu hành phi thơm lừng, dầu mè béo nhẹ và trứng gà chiên vàng mềm.', 'vietnamese', 10, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Ăn nhanh","Dưới 20 phút","Sinh viên","Tiết kiệm"]', 5, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-edac077a60dfa8b5', 'trung-kho-tra-trung-hoa', 'Trứng gà kho trà vân đá ngũ vị', 'Món trứng kho vân đá truyền thống của ẩm thực đường phố Trung Hoa: những quả trứng gà luộc vừa chín tới được gõ rạn nhẹ lớp vỏ ngoài, rồi ngâm ủ trong nồi nước gia vị đậm hương hoa hồi, quế thanh, lá nguyệt quế, tiêu Tứ Xuyên và xì dầu cho ra đường vân đá nâu sẫm thơm bùi.', 'chinese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Trứng kho trà","Vân đá","Ngũ vị","Ăn vặt","Trung Hoa"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0efe9204d9dbdb3e', 'ga-chien-ot-kho', 'Gà chiên giòn xóc ớt khô hoa tiêu Tứ Xuyên', 'Món Lạp Tử Kê trứ danh vùng Trùng Khánh – Tứ Xuyên: những miếng thịt đùi gà rút xương ướp gia vị chiên giòn rụm bên ngoài, mềm mọng bên trong, xóc thơm cùng ớt khô ngâm mềm, hoa tiêu Tứ Xuyên tê đầu lưỡi, gừng tỏi và mè trắng rang.', 'chinese', 15, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Gà chiên","Tứ Xuyên","Cay tê","Món nhậu","Giòn rụm"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0a1f8e0bd042cbfd', 'ba-chi-xao-bap-cai', 'Thịt ba chỉ xào bắp cải giòn kiểu Trung', 'Món xào dân dã cực kỳ đưa cơm của ẩm thực Trung Hoa: thịt ba chỉ thái lát mỏng áp chảo xém cạnh cho tiết bớt mỡ béo ngậy, dùng chính phần mỡ thơm đó xào lửa lớn với bắp cải trắng xé miếng giòn ngọt, rưới xì dầu nhạt quanh thành chảo dậy hương chảo nóng.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thịt ba chỉ","Bắp cải","Món xào","Đưa cơm","Trung Hoa"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ae6d3af49ade8384', 'cua-xao-gung-hanh', 'Cua biển xào gừng hành kiểu Quảng Đông', 'Món cua xào gừng hành kiểu Quảng Đông nổi bật với thịt cua săn ngọt, lớp vỏ thấm đẫm nước sốt dầu hào sánh nhẹ thơm nức mùi gừng phi, tỏi và hành lá tươi.', 'chinese', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món xào","Cua biển","Quảng Đông","Hải sản","Tiệc gia đình"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-122b920eba3f2e50', 'mi-xao-dau-phu', 'Mì xào đậu phụ cải thảo kiểu Hoa', 'Đĩa mì xào đậu phụ kiểu Hoa hài hòa giữa sợi mì Udon mềm dai thấm đẫm sốt tương Hoisin sánh bóng, đậu phụ vàng ruộm bên ngoài béo mềm bên trong cùng cải thảo và cà rốt giòn ngọt.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì xào","Đậu phụ","Món chay","Nhanh gọn","Cải thảo"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-01ae566db4a7feab', 'sup-bo-nam-trung', 'Súp thịt bò nấm đùi gà kiểu Hoa', 'Tô súp thịt bò nấm đùi gà kiểu Hoa ấm nóng với nước dùng trong ngọt thanh vị nấm và gừng, những lát thịt bò chín tới mềm ngọt quyện chút sánh mịn nhẹ dịu và hương dầu mè tiêu trắng.', 'chinese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món súp","Thịt bò","Nấm đùi gà","Thanh ngọt","Ấm bụng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-296dbce4d9098a2e', 'ca-nuong-tuong', 'Cá chẽm nướng xì dầu hành gừng', 'Những miếng phi lê cá chẽm trắng muốt, mềm mọng tự nhiên sau khi nướng kín giấy bạc cùng gừng hành và xì dầu nhạt, nổi bật với lớp dầu mè phi tỏi hành nóng hổi rưới lên mặt khi dọn.', 'chinese', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món nướng","Phi lê cá","Xì dầu","Hành gừng","Bữa tối"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0a43bfa1d02fa497', 'rau-bina-tron-toi', 'Cải bó xôi trộn tỏi dầu mè', 'Món khai vị lạnh kiểu Trung Hoa thanh mát với từng cọng cải bó xôi xanh mướt giòn ngọt, quyện đều nước sốt chua mặn dịu từ giấm đen Trấn Giang, xì dầu, tỏi băm và dầu mè thơm lừng.', 'chinese', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món trộn","Cải bó xôi","Khai vị","Thanh mát","Món chay"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-329f0579ddc26919', 'ca-chua-tron-toi', 'Cà chua trộn tỏi dầu mè kiểu Hoa', 'Món cà chua trộn lạnh thanh ngọt giải ngấy với từng múi cà chua bóc vỏ mềm mọng, thấm đượm vị chua ngọt dịu của giấm gạo đường cát, hòa quyện hương tỏi phi nhẹ, xì dầu và dầu mè thơm nồng.', 'chinese', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món trộn","Cà chua","Khai vị","Thanh mát","Món chay"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-59f5760d6349d284', 'nam-nhoi-thit-hap', 'Nấm đùi gà nhồi thịt hấp xì dầu', 'Những miếng nấm đùi gà giòn ngọt tự nhiên ôm lấy phần nhân thịt heo xay mềm dẻo đậm hương gừng hành và dầu hào, hấp chín tới giữ trọn nước ngọt rồi phủ lớp sốt sánh bóng thơm mùi dầu mè.', 'chinese', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Nấm đùi gà","Thịt băm","Khéo tay","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d8001a64eeaa9150', 'com-tron-trung-tan-nhat', 'Cơm trộn trứng Nhật (Tamago Kake Gohan)', 'Món cơm trộn trứng Tamago Kake Gohan trứ danh của Nhật Bản: hơi nóng từ cơm mới nấu làm trứng gà tươi tiệt trùng chín nhẹ thành lớp sốt kem vàng óng mịn màng, hòa quyện vị umami của xì dầu Nhật, cá bào Katsuobushi và rong biển Nori.', 'japanese', 5, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Tamago Kake Gohan","Cơm trộn trứng","Bữa sáng nhanh","Nhật Bản","Tối giản"]', 5, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e420d7a0eed8a0d6', 'tom-sot-cay-nhat', 'Tôm sốt cay Nhật Bản (Ebi Chili)', 'Món Ebi Chili trứ danh trong ẩm thực Nhật Bản: tôm tươi sơ chế sạch giòn sần sật được áp chảo nhanh tay giữ trọn độ ngọt, sau đó áo đều lớp sốt đỏ óng sánh mịn hòa quyện vị cay thơm lên men của Doubanjiang và vị chua ngọt dịu từ tương cà.', 'japanese', 12, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Ebi Chili","Tôm sốt cay","Yoshoku","Nhật Bản","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2138056075abd874', 'salad-dau-phu-dua-leo', 'Salad đậu phụ dưa leo kiểu Nhật', 'Món salad lạnh kiểu Nhật hài hòa kết cấu giữa đậu phụ trắng mềm béo đã ép ráo nước, dưa leo tươi giòn mát và lớp sốt trộn sánh thơm từ tương Miso trắng, giấm gạo, xì dầu Nhật, dầu ô liu và mè trắng rang.', 'japanese', 3, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Salad Nhật","Đậu phụ","Dưa leo","Thanh mát","Món chay nhẹ"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ff9fd0fdcdd85b79', 'bap-cai-nuong-bo', 'Bắp cải áp chảo bơ xì dầu kiểu Nhật', 'Món bắp cải áp chảo bơ xì dầu đơn giản mà cuốn hút theo phong cách quán Izakaya Nhật Bản: từng miếng bắp cải được nướng xém vàng tự nhiên giữ trọn vị ngọt giòn, thấm đẫm hương béo thơm của bơ lạt quyện xì dầu Nhật và tỏi phi.', 'japanese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Izakaya","Bắp cải áp chảo","Bơ xì dầu","Món phụ Nhật","Nhanh gọn"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d6e35b3fa19080de', 'trung-om-nam-nhat', 'Trứng om nấm đùi gà kiểu Nhật', 'Món trứng om nấm Tamago-toji kiểu gia đình Nhật với nấm đùi gà thái lát sần sật thấm đẫm nước dùng Dashi pha xì dầu nhạt, rượu Mirin và Sake, ôm trọn bởi lớp trứng gà đánh mịn chín mềm vừa tới.', 'japanese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Trứng gà","Nấm đùi gà","Nhanh gọn","Ấm bụng"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-cc88c6bd94df496e', 'canh-cua-nam-nhat', 'Canh trong cua thịt nấm đùi gà kiểu Nhật', 'Món canh trong Osuimono trang nhã của Nhật Bản: nền nước dùng Dashi kết hợp vị ngọt thanh của nấm đùi gà và từng thớ thịt cua biển tươi ngọt, nêm nhẹ với xì dầu nhạt để giữ nước canh trong vắt mà đậm đà hương vị umami.', 'japanese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Canh trong Nhật","Thịt cua","Nấm đùi gà","Umami","Thanh đạm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-df7a6429150724b1', 'tom-om-ca-chua-nhat', 'Tôm om cà chua kiểu Nhật (Yoshoku)', 'Món tôm om cà chua phong cách Yoshoku hiện đại của Nhật Bản: tôm tươi áp chảo nhanh tay giữ độ giòn ngọt, hòa quyện trong nước sốt cà chua tươi nấu nhừ cùng hành tây, tương cà, xì dầu Nhật và rượu Sake thơm lừng.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Yoshoku","Tôm tươi","Cà chua","Chan cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9157234945e6ff01', 'ga-ham-dak-jjim', 'Gà hầm tương kiểu Andong (Andong Jjimdak)', 'Andong Jjimdak là món gà hầm nổi tiếng xuất xứ từ vùng Andong, Hàn Quốc. Thịt đùi gà được áp chảo săn rồi hầm cùng khoai tây, cà rốt, nấm đùi gà và miến khoai lang trong hỗn hợp sốt tương, dầu hào, siro ngô và chút tương đen Chunjang tạo màu nâu óng đậm vị mặn ngọt hài hòa.', 'korean', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Andong jjimdak","Gà hầm","Hàn Quốc","Miến Hàn","Đậm đà"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-aedcf1c5c1d05d04', 'tom-xao-tuong-han', 'Tôm xào sốt tương bơ tỏi kiểu Hàn', 'Tôm xào sốt tương bơ tỏi kiểu Hàn là món ăn đưa cơm nhanh gọn chỉ mất 20 phút. Tôm tươi bóc vỏ ướp nhẹ muối tiêu được xào nhanh trên chảo bơ tỏi thơm lừng rồi áo đều lớp sốt nước tương, rượu mirin và chút đường tạo độ bóng mặn ngọt hài hòa.', 'korean', 8, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Tôm xào","Bơ tỏi","Hàn Quốc","Banchan","Món nhanh"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e39a1be406f9e1ea', 'trung-hap-han', 'Trứng hấp xốp kiểu Hàn (Gyeran Jjim)', 'Gyeran Jjim là món trứng hấp nổi tiếng thường được phục vụ nóng hổi trong thố đất tại các quán thịt nướng Hàn Quốc. Bằng kỹ thuật khuấy nhẹ giữa chừng khi nấu trong nồi đáy dày hoặc nồi đất đậy nắp kín, trứng nở phồng bông xốp như bánh souffle nhưng vẫn giữ độ ẩm mềm mịn tan ngay đầu lưỡi.', 'korean', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gyeran jjim","Trứng hấp","Hàn Quốc","Bông xốp","Món nhanh"]', 5, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-da5a134e2654eeb5', 'dau-phu-tron-kimchi', 'Đậu phụ luộc trộn kim chi xào kiểu Hàn (Dubu Kimchi)', 'Đậu phụ trộn kim chi xào (Dubu Kimchi) là sự đối lập đầy tinh tế giữa những lát đậu phụ trắng luộc mềm mát, thanh vị với phần kim chi cải thảo xào nóng hổi đậm đà vị chua cay của tương ớt Gochujang, tỏi gừng và dầu mè rang. Đây vừa là món khai vị thanh nhẹ vừa là món nhậu truyền thống rất được yêu thích ở Hàn Quốc.', 'korean', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Dubu kimchi","Đậu phụ","Kim chi","Hàn Quốc","Khai vị"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8cd9bb1abdd63a9e', 'mi-lanh-naengmyeon', 'Mì lạnh nước kiểu Hàn (Mul Naengmyeon)', 'Mì lạnh Mul Naengmyeon là đặc sản giải nhiệt mùa hè trứ danh của ẩm thực Hàn Quốc. Sợi mì kiều mạch được luộc chín vừa rồi xả kỹ qua nước đá lạnh để đạt độ dai giòn sần sật, chan nước hầm thịt bò lọc sạch mỡ pha giấm đường và mù tạt vàng cay dịu lạnh buốt.', 'korean', 60, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Naengmyeon","Mì lạnh","Hàn Quốc","Mùa hè","Thịt bò"]', 30, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a631650d667191b4', 'muc-nuong-cay-han', 'Mực nướng sốt cay kiểu Hàn (Ojingeo Gui)', 'Mực nướng cay Ojingeo Gui là món nhậu (anju) khoái khẩu tại các quán nướng Hàn Quốc. Thân mực tươi được chà muối sạch nhớt, khứa caro nông và ướp thấm sốt tương ớt Gochujang, ớt bột Hàn, siro ngô và chút mù tạt vàng, khi nướng trên lửa lớn chỉ 4–5 phút là mực săn giòn, áo lớp sốt đỏ bóng thơm nức.', 'korean', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Ojingeo gui","Mực nướng","Hàn Quốc","Món nhậu","Cay ngọt"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2a958e709ba9cb7c', 'dau-phu-xao-kimchi', 'Đậu phụ áp chảo kim chi xào cay (Dubu Kimchi)', 'Phiên bản đậu phụ áp chảo kim chi xào cay (Dubu Kimchi) mang đến kết cấu giòn nhẹ bên ngoài của từng miếng đậu phụ vàng ruộm, hòa quyện cùng đĩa kim chi cải thảo xào sốt Gochujang đỏ óng cay nồng, rất thích hợp ăn cùng cơm trắng nóng hoặc làm món nhắm cuối tuần.', 'korean', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Dubu kimchi","Đậu phụ","Kim chi xào","Hàn Quốc","Món nhậu"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-1f3a7df71f4cbc77', 'suon-nuong-galbi', 'Sườn bò nướng LA Galbi kiểu Hàn', 'LA Galbi là món sườn bò cắt ngang xương nổi tiếng của Hàn Quốc, được ướp ngập trong hỗn hợp nước tương, mật ong, đường, rượu mirin, dầu mè và hành tây gừng tỏi xay mịn giúp từng thớ thịt mềm mọng và thấm vị đậm đà. Khi nướng trên vỉ than hoặc chảo gang nóng, dẻ sườn chín nhanh, viền thịt xém cạnh caramel thơm nức.', 'korean', 15, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["LA Galbi","Sườn bò nướng","Hàn Quốc","Tiệc nướng","Cuốn rau"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-328b6c9769e256eb', 'tom-nuong-muoi-ot-han', 'Tôm nướng muối hạt kiểu Hàn (Saeu Sogeum Gui)', 'Tôm nướng muối hạt (Saeu Sogeum Gui) là món ăn mùa thu rất được yêu thích tại Hàn Quốc nhờ cách chế biến mộc mạc giúp giữ trọn độ ngọt tự nhiên của tôm tươi. Tôm nguyên vỏ được nướng áp nhiệt gián tiếp trên lớp muối biển hạt to nóng già nên chín đều, vỏ giòn thơm mà thịt bên trong vẫn mọng nước, chấm kèm sốt tương ớt Gochujang pha chanh mật ong.', 'korean', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Tôm nướng muối","Hàn Quốc","Món nhậu","Hải sản","Chấm Gochujang"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-5dbb6aa38dae701d', 'mi-xao-kimchi-han', 'Mì xào kim chi Hàn Quốc', 'Đĩa mì xào kim chi Hàn Quốc nóng hổi với sợi mì ramen săn bóng áo đều sốt tương ớt Gochujang cay nhẹ, vị chua thanh của kim chi lên men, chút béo ngậy từ bơ lạt và trứng ốp la đặt trên mặt.', 'korean', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì xào","Kim chi","Hàn Quốc","Bữa tối nhanh","Trứng ốp la"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b7f8a716b25a7072', 'canh-bo-bap-cai-han', 'Canh bò cải thảo Hàn Quốc', 'Tô canh bò cải thảo Hàn Quốc ấm áp với nước dùng trong thanh ngọt tự nhiên từ thịt bò xào săn và rau cải thảo hầm mềm, điểm xuyết hương dầu mè và tỏi thơm dịu rất dễ ăn.', 'korean', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Cải thảo","Hàn Quốc","Thanh đạm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-7d38862afc164a8d', 'muc-hap-tuong-han', 'Mực xào xì dầu Hàn Quốc', 'Món mực xào xì dầu Hàn Quốc (Ojingeo Ganjang-bokkeum) nổi bật với từng khoanh mực trắng giòn sần sật, thấm đẫm sốt xì dầu đặc và dầu hào ngọt mặn hài hòa cùng hành tây, ớt chuông giòn tươi.', 'korean', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Mực tươi","Xì dầu","Hàn Quốc","Không cay"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-c78c4d4ca35484d3', 'com-nam-han', 'Cơm nấu nấm Hàn Quốc', 'Nồi cơm nấm Hàn Quốc (Beoseot-bap) tỏa hương thơm dịu tự nhiên nhờ gạo được rang sơ rồi nấu trực tiếp với nước dùng tảo bẹ Kombu cùng ba loại nấm ngọt giòn, ăn kèm chén sốt xì dầu hành lá thanh tao.', 'korean', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm nấm","Món chay","Hàn Quốc","Nấm tươi","Thanh đạm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-97c4b38c79bf9f39', 'canh-kimchi-tom', 'Canh kim chi tôm đậu phụ Hàn Quốc', 'Nồi canh kim chi tôm (Haemul Kimchi Jjigae) bốc khói nghi ngút với nước dùng cá cơm tảo bẹ đậm đà, vị chua dịu từ kim chi chín kỹ kết hợp cùng thịt tôm giòn ngọt và từng miếng đậu phụ non tan mềm.', 'korean', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Canh kim chi","Hải sản","Tôm tươi","Hàn Quốc","Cay ấm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b855b6ba4a9a3be8', 'tom-yum-tom-nam', 'Canh Tom Yum tôm nấm kiểu Thái', 'Canh Tom Yum tôm nấm kiểu Thái trứ danh với nước dùng nấu trực tiếp từ gạch đầu tôm và vỏ tôm xào thơm, kết hợp bộ ba thảo mộc sả, riềng, lá chanh Kaffir cùng nấm đùi gà giòn ngọt và tôm tươi chín tới mọng thịt.', 'thai', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Tom Yum","Canh chua cay","Tôm tươi","Ẩm thực Thái","Hải sản"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2b514b564c702ff1', 'tom-nuong-chanh-ot', 'Tôm nướng chanh ớt kiểu Thái', 'Tôm nướng chanh ớt kiểu Thái mang hương vị biển tươi mát với từng con tôm sú chắc thịt nướng cháy cạnh thơm lừng, được phết đẫm lớp sốt chanh tươi, nước mắm, đường và ớt tỏi băm đậm vị ngay khi còn nóng.', 'thai', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Chanh ớt","Ẩm thực Thái","Hải sản","Món tiệc"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-119da2ec6738c17e', 'ga-hap-chanh-sa', 'Gà hấp chanh sả kiểu Thái', 'Gà hấp chanh sả kiểu Thái thơm dịu và mọng ngọt với từng miếng thịt đùi gà ướp kỹ cùng sả, riềng, lá chanh Kaffir và rễ ngò xay nhuyễn, hấp chín mềm cùng lá húng quế Thái, chấm kèm nước mắm chanh tỏi ớt hòa chút nước ngọt gà hấp đậm đà.', 'thai', 40, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gà hấp","Sả chanh","Ẩm thực Thái","Thanh đạm","Cơm gia đình"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2fb85e79ab43b8bc', 'goi-bo-nuong-thai', 'Gỏi bò nướng Nam Tok kiểu Thái', 'Gỏi bò nướng Nam Tok kiểu Thái đặc trưng với thịt thăn bò ướp vừa vị nướng xém cạnh, giữ trọn nước thịt ngọt mềm, trộn ngay cùng thính gạo rang (Khao Khua), sả thái mỏng, hành tím, lá bạc hà và nước trộn chanh ớt mắm đậm đà.', 'thai', 12, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Nam Tok","Gỏi bò","Thính gạo","Ẩm thực Thái","Khai vị"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3f14cf8e63967712', 'muc-xao-toi-ot-thai', 'Mực xào tỏi ớt kiểu Thái', 'Mực xào tỏi ớt kiểu Thái ghi điểm với từng miếng mực tươi khía vảy rồng giòn sần sật, không ra nước, thấm đẫm hương thơm nồng nàn của tỏi ớt giã cối phi vàng và sốt dầu hào, nước mắm, xì dầu đặc đậm đà đưa cơm.', 'thai', 8, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mực xào","Tỏi ớt","Hải sản","Ẩm thực Thái","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-244640181aff1fb6', 'nam-nuong-sa', 'Nấm đùi gà nướng sả kiểu Thái', 'Nấm đùi gà nướng sả kiểu Thái là món chay thơm nức với từng khoanh nấm giòn ngọt tự nhiên được luộc sơ khử hăng, khứa vảy rồng thấm đẫm sốt xì dầu, dầu hào chay, dầu mè và sả băm nhuyễn, nướng xém cạnh hấp dẫn.', 'thai', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Nấm đùi gà","Nấm nướng","Sả ớt","Ẩm thực Thái"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f494a9f384ce66a4', 'cua-xao-cay-thai', 'Cua xào cay kiểu Thái', 'Cua xào cay kiểu Thái (Poo Pad Prik) nổi bật với thớ thịt cua tươi trắng ngọt tự nhiên quyện trong nước sốt dầu hào, xì dầu nhạt sánh nhẹ, dậy mùi tỏi phi, ớt hiểm cay nồng cùng vị giòn mát của ớt chuông xanh và hành lá.', 'thai', 12, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cua xào","Poo Pad Prik","Hải sản","Ẩm thực Thái","Cay nồng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0ec0d1db60dbdc1e', 'com-ga-khao-man-gai', 'Cơm gà Khao Man Gai kiểu Thái', 'Cơm gà Khao Man Gai kiểu Thái chinh phục thực khách với từng hạt cơm gạo thơm dẻo bóng nhẹ mùi tỏi gừng và mỡ gà, thịt gà ta luộc chín tới da giòn thịt mọng ngọt, ăn kèm chén sốt tương đậu nành lên men gừng ớt đậm vị và bát nước dùng thanh ngọt.', 'thai', 60, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Khao Man Gai","Cơm gà","Ẩm thực Thái","Nước chấm gừng","Bữa trưa"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4316659025be0f91', 'mi-xao-bo-cay-thai', 'Mì xào bò cay kiểu Thái', 'Mì xào bò cay kiểu Thái (Pad Kee Mao) nổi bật với sợi hủ tiếu bản rộng dai mềm xém cạnh thơm mùi chảo lửa, thịt bò thăn mềm mọng đậm vị, hòa quyện vị cay nồng của tỏi ớt giã cùng mùi thơm đặc trưng không thể thiếu của lá húng quế Thái.', 'thai', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pad Kee Mao","Mì xào","Thịt bò","Ẩm thực Thái","Cay nồng"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4)
INSERT INTO recipes (id, slug, title, description, cuisine, cook_time_minutes, servings, difficulty, image_url, tags, prep_time_minutes, source_type, source_reference, verification_state, version) VALUES
('imp-0e30c82a4c77802e', 'goi-dau-phu-cay-thai', 'Gỏi đậu phụ cay kiểu Thái', 'Gỏi đậu phụ cay kiểu Thái mang đến sự tương phản thú vị giữa từng khối đậu phụ non mềm mịn mát lạnh và lớp rau thơm băm nhuyễn giòn tươi gồm sả non, hành tím, dưa leo, bạc hà, ngò rí thấm đẫm nước sốt chanh ớt đường thốt nốt chua cay hài hòa.', 'thai', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi đậu phụ","Món chay","Khai vị","Ẩm thực Thái","Thanh mát"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d005aca18d138bfe', 'tom-xao-hung-que-thai', 'Tôm xào húng quế kiểu Thái', 'Tôm xào húng quế kiểu Thái (Pad Krapao Tôm) là món ăn đường phố cực kỳ bắt cơm với từng con tôm tươi săn giòn áo lớp sốt dầu hào, nước mắm sánh đậm, hòa cùng vị cay thơm nồng nàn của tỏi ớt giã và lá húng quế Thái đảo nhanh khi tắt bếp.', 'thai', 8, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pad Krapao","Tôm xào","Húng quế","Ẩm thực Thái","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a9710414682c8521', 'mi-xao-xi-dau-bo-thai', 'Mì xào xì dầu bò kiểu Thái', 'Mì xào xì dầu bò kiểu Thái (Pad See Ew biến tấu với mì sợi trứng) hấp dẫn với từng sợi mì vàng nâu bóng mượt, hơi xém cạnh thơm mùi khói chảo, hòa quyện thịt bò thăn mềm ngọt, trứng gà tơi béo và bắp cải giòn giòn đậm vị xì dầu.', 'thai', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pad See Ew","Mì xào","Thịt bò","Xì dầu","Ẩm thực Thái"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-c64c83ef34771b5a', 'canh-nam-sa-thai', 'Canh nấm sả Thái chay thanh vị', 'Bát canh nấm sả Thái chay thanh mát lấy cảm hứng từ món Tom Yum nước trong, kết hợp nấm đùi gà giòn ngọt, đậu phụ non mềm mịn cùng hương thơm nồng nàn của sả, riềng tươi, lá chanh Thái và vị chua dịu tự nhiên từ cà chua, nước cốt chanh.', 'thai', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Canh chay","Nấm đùi gà","Thảo mộc Thái","Thanh nhẹ","Khai vị"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a71f6ef791b463ea', 'goi-tom-sa-chanh', 'Gỏi tôm sả chanh kiểu Thái', 'Đĩa gỏi tôm sả chanh kiểu Thái mang hương vị tươi mát bùng nổ với thịt tôm sú chần vừa chín tới giòn sần sật, quyện cùng sả thái khoanh mỏng, ngò gai, lá bạc hà và sốt trộn chua cay mặn ngọt hài hòa.', 'thai', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi Thái","Tôm sú","Sả chanh","Khai vị","Chua cay"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9236740e2b55e8a1', 'com-chien-ga-thai', 'Cơm chiên gà kiểu Thái (Khao Pad Gai)', 'Cơm chiên gà Thái (Khao Pad Gai) chinh phục vị giác nhờ từng hạt cơm dẻo tơi săn cạnh, thịt đùi gà áp chảo mềm ngọt quyện trứng gà béo bùi, dậy mùi thơm đặc trưng của xì dầu nhạt, tiêu trắng và chén nước mắm ớt chanh ăn kèm.', 'thai', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Khao Pad","Cơm chiên","Thịt gà","Đường phố Thái","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a1904f60d9f4f10e', 'mi-y-bo-toi', 'Mì Ý sốt bơ tỏi (Burro e Aglio)', 'Món mì Ý bơ tỏi tối giản mà tinh tế với từng sợi Spaghetti dai mượt bao phủ bởi lớp sốt nhũ hóa óng ả từ bơ lạt, nước luộc mì giàu tinh bột, tỏi phi lát vàng dịu và phô mai Parmesan.', 'italian', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì Ý bơ tỏi","Ẩm thực Ý","Nhanh gọn","Spaghetti","Món chính"]', 8, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-cc5f58548e934d9e', 'mi-y-tom-toi-ot', 'Mì Ý tôm tỏi ớt (Aglio Olio)', 'Món mì Ý hải sản tinh tế với tôm tươi xào săn ngọt thịt, sợi mì dai mềm quyện sốt dầu ô liu bơ thơm nức mùi tỏi phi, chút cay nồng của ớt tươi và vị tươi mát từ vỏ chanh vàng bào.', 'italian', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì Ý tôm","Aglio Olio","Ẩm thực Ý","Hải sản","Cay nhẹ"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8fdcddab058d5f65', 'mi-y-sot-ca-chua-tuoi', 'Mì Ý sốt cà chua tươi (Pomodoro)', 'Đĩa mì Ý sốt cà chua tươi Pomodoro thanh vị với cà chua chín mọng nấu nhanh cùng tỏi phi dầu ô liu, thêm chút cà chua cô đặc tạo màu đỏ au đẹp mắt và hương thơm dịu của lá húng quế Tây.', 'italian', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì Ý Pomodoro","Cà chua tươi","Ẩm thực Ý","Nhanh gọn","Món chính"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d4d1de72f13e8f30', 'lasagna-bo-bam', 'Lasagna bò bằm nướng sốt Béchamel', 'Món Lasagna truyền thống vùng Bologna với 5 tầng lá mì mềm dẻo ôm trọn phần sốt thịt bò bằm và thịt xông khói ninh chậm cùng cà chua, cân bằng bởi sốt sữa trắng Béchamel thơm mùi nhục đậu khấu và lớp phô mai Parmesan nướng vàng giòn.', 'italian', 120, 6, 'hard', '/frigo/illustrations/delicious-meal.png', '["Lasagna","Bò bằm","Ẩm thực Ý","Nướng lò","Tiệc cuối tuần"]', 30, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3fd9eb5a7c40c3c0', 'risotto-ga-hanh', 'Risotto gà hành kiểu Ý', 'Đĩa cơm Ý Risotto béo mịn chuẩn vị với từng hạt gạo Arborio mềm dẻo bên ngoài nhưng vẫn giữ lõi sần nhẹ bên trong, quyện thịt ức gà ngọt mềm, hành tây thơm dịu, bơ lạt và phô mai Parmesan.', 'italian', 30, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Risotto","Ẩm thực Ý","Ức gà","Gạo Ý","Món chính"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4c5955ef4919d61a', 'mi-y-cua-ot', 'Mì Ý thịt cua tỏi ớt chanh vàng', 'Món mì Ý hải sản tinh tế với từng thớ thịt cua biển ngọt tự nhiên hòa quyện sốt nhũ hóa trắng sánh từ dầu ô liu phi thơm tỏi ớt và nước luộc mì, điểm nhấn bởi hương thơm tươi mát của vỏ chanh vàng và ngò tây.', 'italian', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Mì Ý cua","Hải sản","Ẩm thực Ý","Cay nhẹ","Bữa tối"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-c398c169dc196c4e', 'tom-nuong-toi-chanh-y', 'Tôm nướng tỏi chanh vàng kiểu Ý', 'Món khai vị hải sản kiểu Ý đầy cuốn hút với những con tôm tươi nguyên vỏ nướng nhanh trên lửa lớn, thịt tôm chắc ngọt thơm lừng hương dầu ô liu, tỏi băm, vỏ chanh vàng và ngò tây tươi.', 'italian', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Ẩm thực Ý","Chanh vàng","Khai vị","Hải sản"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8fcc592ab7250a38', 'bap-cai-om-ca-chua-y', 'Bắp cải om cà chua kiểu Ý', 'Món rau om dân dã vùng Bắc Ý với từng sợi bắp cải chín mềm ngọt lịm, thấm đều nước sốt cà chua đỏ au quyện hương dầu ô liu, hành tây và tỏi phi dịu nhẹ.', 'italian', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Bắp cải om","Món chay","Ẩm thực Ý","Món phụ","Thanh đạm"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-da0c2dea539000e5', 'frittata-nam-pho-mai', 'Frittata nấm phô mai kiểu Ý', 'Ổ trứng chiên dày Frittata kiểu Ý mềm ẩm bên trong, xém vàng bên ngoài với nấm đùi gà xào thơm ngọt, ngò tây tươi, tỏi phi và phô mai Parmesan tan quyện đậm đà.', 'italian', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Frittata","Bữa sáng","Ẩm thực Ý","Trứng nấm","Phô mai"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e427b91ce9f574c3', 'sup-nam-kem-y', 'Súp nấm kem tươi kiểu Ý', 'Bát súp nấm kem kiểu Ý thơm nức mùi nấm đùi gà xào vàng quyện sốt bơ bột mì béo dịu từ sữa tươi và kem tươi, kết cấu mịn mượt ăn kèm lát nấm áp chảo và bánh mì nướng giòn.', 'italian', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Súp nấm kem","Ẩm thực Ý","Khai vị","Món nóng","Crostini"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f3eb85959cb62d3e', 'sup-ga-rau-cu-y', 'Súp gà rau củ thanh nhẹ kiểu Ý', 'Tô súp gà rau củ kiểu Ý nhẹ nhàng, thanh vị với nước dùng gà luộc trong vắt ngọt tự nhiên, kết hợp cà rốt, khoai tây bùi mềm, cần tây thơm dịu và thịt ức gà xé thớ mềm ngon.', 'italian', 45, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Súp gà","Rau củ","Ẩm thực Ý","Thanh nhẹ","Bổ dưỡng"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f4c5afa7ccc2a9ed', 'ca-chua-nhoi-thit-nuong', 'Cà chua nhồi thịt nướng lò kiểu Ý', 'Món Pomodori Ripieni truyền thống đẹp mắt với từng trái cà chua chín chắc tay nhồi đầy nhân thịt heo xay mềm ẩm quyện ruột cà chua băm, trứng gà, bột chiên xù, tỏi thơm và phô mai Parmesan nướng vàng.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cà chua nhồi thịt","Ẩm thực Ý","Nướng lò","Chiêu đãi","Món chính"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0d54a1288223d8ac', 'ga-nuong-bo-toi-y', 'Gà nướng bơ tỏi kiểu Ý', 'Đùi gà có xương nướng lò ở nhiệt độ cao giúp lớp da ngoài vàng giòn bắt mắt trong khi thớ thịt bên trong vẫn giữ trọn độ ngọt mọng, hòa quyện hương bơ lạt, tỏi phi dịu và thảo mộc Ý.', 'italian', 40, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nướng lò","Đùi gà","Bơ tỏi","Ẩm thực Ý","Món chính"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-70e5e19dd4073b76', 'bo-ham-ca-chua-y', 'Bò hầm cà chua kiểu Ý (Stracotto)', 'Món bò hầm truyền thống miền Bắc nước Ý được nấu chậm cùng nền rau củ xào thơm, rượu vang đỏ và sốt cà chua passata, cho thớ thịt bò mềm tơi đậm đà cùng nước sốt sánh quyện tuyệt hảo.', 'italian', 110, 5, 'hard', '/frigo/illustrations/delicious-meal.png', '["Stracotto","Bò hầm","Rượu vang đỏ","Ẩm thực Ý","Mùa lạnh"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-500ffbf4fd05f9da', 'mi-y-muc-ot', 'Mì Ý mực sốt cà chua cay', 'Sự kết hợp chuẩn vị biển Địa Trung Hải giữa mực ống tươi áp chảo xém cạnh, om mềm trong sốt cà chua bi nấu cùng rượu vang trắng, tỏi và ớt tươi cay nhẹ, bám quyện hoàn hảo quanh từng sợi mì Ý.', 'italian', 30, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Mì Ý","Hải sản","Mực tươi","Sốt cà chua","Cay nhẹ"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-ebc8bf739393ac91', 'canh-tom-dau-phu', 'Canh tôm nấu đậu phụ cà chua', 'Canh tôm nấu đậu phụ cà chua là món canh dễ nấu, giàu đạm và nhẹ bụng. Nước canh có màu đỏ cam dịu nhẹ từ cà chua xào, hòa quyện vị ngọt tươi của tôm bóc vỏ cùng đậu phụ mềm mịn và hương thơm thoang thoảng của gừng, hành ngò.', 'vietnamese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Tôm tươi","Đậu phụ","Cà chua","Nấu nhanh"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3446b3924b05eb7b', 'canh-bo-bap-cai-ca-rot', 'Canh thịt bò bắp cải cà rốt', 'Canh thịt bò bắp cải cà rốt là biến tấu đầy đủ sắc màu và dinh dưỡng của món canh bò truyền thống. Vị ngọt bùi của cà rốt hòa cùng bắp cải mềm ngọt và lát thịt bò thăn thơm mùi tỏi phi tạo nên tô canh ấm nóng dễ chịu.', 'vietnamese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Bắp cải","Cà rốt","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6e3eb737c7d88a2c', 'ga-kho-trung', 'Gà kho trứng', 'Thịt đùi gà săn ngọt quyện cùng những quả trứng gà thấm đều nước kho màu nâu cánh gián sánh mượt, dậy mùi thơm của hành tím, tỏi, ớt giã nhuyễn và nước mắm ngon.', 'vietnamese', 40, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt gà","Trứng gà","Nam Bộ","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6251f57b97918111', 'tom-kho-tuong-dam', 'Tôm kho nước tương đậm vị', 'Tôm tươi rút chỉ lưng thấm đẫm nước sốt nước tương và dầu hào sánh bóng, lên màu đỏ cam bắt mắt từ dầu điều, thơm lừng mùi hành tỏi phi và tiêu đen cay nhẹ.', 'vietnamese', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món kho","Tôm tươi","Nước tương","Nhanh gọn","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-977a3409383d743f', 'muc-xao-bong-cai', 'Mực xào bông cải xanh', 'Mực xào bông cải xanh kết hợp giữa những khoanh mực giòn ngọt không hề tanh với bông cải xanh chần sơ xanh mướt, thấm đều gia vị nước tương, hành tím phi thơm và vị cay nhẹ kích thích vị giác.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Bông cải","Dưới 20 phút","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a4ff266c02427746', 'bong-cai-xao-toi', 'Bông cải xanh xào tỏi', 'Bông cải xanh xào tỏi là món rau xanh thanh mát, giữ nguyên sắc xanh ngọc bích và độ giòn ngọt tự nhiên của từng bông súp lơ nhờ kỹ thuật chần sốc nhiệt, quyện hương tỏi phi vàng thơm lừng và vị mặn dịu của nước tương.', 'vietnamese', 8, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau xanh","Tỏi","Thanh đạm","Dưới 20 phút"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f9f08651bc712e93', 'cha-ca-ha-noi-nghe', 'Chả cá Hà Nội tẩm nghệ (Chả cá Lã Vọng)', 'Chả cá Hà Nội tẩm nghệ là tinh hoa ẩm thực Tràng An nổi tiếng. Cá lăng phi lê ít xương được ướp đậm đà với riềng giã, nước mẻ lọc mịn, bột nghệ và chút mắm tôm rồi áp chảo vàng ươm, sau đó đảo nóng tại bàn cùng thật nhiều hành lá và thì là xanh mướt.', 'vietnamese', 15, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Chả cá","Hà Nội","Bắc Bộ","Đặc sản"]', 35, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0d6c454ae1073ef6', 'su-su-hap-toi', 'Su su hấp tỏi rưới mắm thơm', 'Những miếng su su non xanh mướt hấp cách thủy vừa chín tới giữ được vị ngọt thanh tự nhiên và độ giòn nhẹ, rưới đều hỗn hợp nước mắm dầu tỏi phi vàng thơm nức cùng hành lá xanh tươi.', 'vietnamese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Su su","Thanh đạm","Dễ nấu","Dưới 20 phút"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4d81607829384874', 'ga-hap-gung-hanh', 'Đùi gà hấp gừng hành thơm mềm', 'Đùi gà tơ khứa nhẹ ướp thấm gia vị rồi hấp cách thủy cùng gừng non thái sợi, hành tím và hành lá giúp giữ trọn độ ẩm ngọt trong từng thớ thịt, dậy hương thơm ấm bụng rất hợp bữa cơm gia đình.', 'vietnamese', 28, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Gà","Gừng","Gia đình","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-1b518ba2f068f3ab', 'nom-dua-chua-cay', 'Nộm dứa chua cay giòn mát', 'Nộm dứa chua cay mang hương vị nhiệt đới tươi mới với từng lát dứa chín vàng mọng nước, cà rốt bào sợi ngâm đá giòn sần sật, hành lá xanh mát và nước mắm giấm chanh tỏi ớt hài hòa, điểm đậu phộng rang thơm bùi.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nộm dứa","Chua cay","Khai vị","Thanh mát","Nhiệt đới"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0f336e8735d9ce75', 'goi-muc-dua-leo', 'Gỏi mực dưa leo sả ớt giòn mát', 'Gỏi mực dưa leo sả ớt là món gỏi biển giòn mát với từng khoanh mực ống trụng vừa chín tới trắng giòn, hòa quyện cùng dưa leo bỏ ruột và cà rốt vắt ráo, sả thái khoanh thơm nồng, rau răm húng quế và chút tỏi phi vàng rụm.', 'vietnamese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi mực","Dưa leo","Sả ớt","Khai vị","Mát lành"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f93013fb234d39d0', 'bun-xao-chay-nam', 'Bún xào chay nấm đùi gà rau củ', 'Đĩa bún xào chay mộc mạc mà tròn vị với từng sợi bún gạo tơi mềm thấm đều nước tương thơm lừng, kết hợp nấm đùi gà giòn ngọt, bắp cải và cà rốt thái sợi giòn tươi, dậy hương tỏi phi và hành lá.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Bún xào","Nấm đùi gà","Rau củ","Ngày rằm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6af3e18fdac79061', 'mien-tron-ga', 'Miến trộn gà', 'Món miến trộn gà thanh mát nhẹ bụng rất hợp cho bữa trưa mùa hè với sợi miến dong không bị dính bết, thịt đùi gà luộc gừng ngâm lạnh giòn da mềm thịt, quyện sốt nước tương nước mắm chua ngọt cùng rau thơm và lạc rang giã dập.', 'vietnamese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Miến trộn","Thịt gà","Món trộn thanh mát","Bữa trưa"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2e39be75d8f72249', 'ca-chua-xao-nam-chay', 'Cà chua xào nấm đùi gà chay', 'Món xào chay thanh nhẹ nhanh gọn với từng lát nấm đùi gà xém cạnh giòn dai thấm hương tỏi phi, quyện trong phần sốt cà chua chín đỏ mọng chua ngọt dịu, thêm chút dầu hào chay và bột năng giúp nước sốt sánh bóng quyến rũ.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Món xào","Cà chua","Nấm đùi gà","Dưới 20 phút"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-11b65c6b18266849', 'dau-phu-kho-dua-chay', 'Đậu phụ kho dứa chay chua ngọt', 'Món kho chay mới lạ kích thích vị giác với đậu phụ trắng chiên vàng giòn bên ngoài, mềm béo bên trong, rim thấm cùng những miếng dứa chín chua ngọt thanh dịu, quyện sốt nước tương dầu hào chay sánh bóng thơm lừng hành tỏi.', 'vietnamese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Nam Bộ","Món kho","Đậu phụ","Dứa"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2ae4c4cdd97c5d02', 'com-bo-hanh-tay', 'Cơm bò hành tây', 'Bữa cơm bò hành tây nhanh gọn chỉ trong 20 phút với thịt bò thăn xào tái chín mềm mọng đậm vị xì dầu, dầu hào, từng múi hành tây chín tới giòn ngọt tự nhiên và phần nước sốt sánh thơm rưới đẫm cơm trắng nóng hổi.', 'vietnamese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm bò","Xào nhanh","Dưới 20 phút","Cơm văn phòng","Cơm nhà"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9a2994a529126adb', 'mi-xao-trung-rau', 'Mì xào trứng rau', 'Món mì xào trứng rau đơn giản nhưng đủ sắc hương vị với sợi mì dai săn bóng bẩy quyện sốt xì dầu, dầu hào, trứng gà đánh tơi vàng ươm mềm xốp cùng bắp cải trắng và cà rốt giòn ngọt.', 'vietnamese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì xào","Trứng rau","Ăn nhanh","Dưới 20 phút","Tiết kiệm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-990934aa20b70964', 'lau-bo-rau-thom', 'Lẩu bò rau thơm cà chua', 'Lẩu bò rau thơm cà chua là món lẩu dễ ăn và tròn vị cho những buổi sum họp cuối tuần. Nước lẩu được ninh kỹ từ xương ống bò cho vị ngọt đậm tự nhiên, kết hợp cà chua xào đỏ đẹp và nước cốt chanh thanh mát, nhúng thịt bò thái mỏng chín tới cùng hương thơm nồng nàn của húng quế, ngò rí và rau muống.', 'vietnamese', 45, 5, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Lẩu bò","Rau thơm","Cà chua","Tiệc gia đình"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d0569e8ec34b2bfc', 'bo-xao-gia-do', 'Thịt bò xào giá đỗ lửa lớn', 'Đĩa thịt bò xào giá đỗ đậm đà hương vị cơm nhà kiểu Hoa với từng lát thịt bò mềm mọng thấm gia vị và cọng giá đỗ trắng mập vẫn giữ nguyên độ giòn thanh không ra nước.', 'chinese', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Giá đỗ","Bữa nhanh","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-531f59c246a56bcb', 'vien-thit-chien-trung', 'Thịt viên chiên giòn kiểu Hoa', 'Những viên thịt heo chiên vàng rộm, vỏ ngoài hơi xém giòn thơm nức mùi ngũ vị hương, gừng và xì dầu đặc, cắn vào bên trong vẫn giữ được độ dẻo dai và nước thịt ngọt mềm.', 'chinese', 15, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Thịt viên","Món nhậu","Trung Hoa","Giòn rụm"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-3767b2e36f535b7b', 'ga-nuong-tuong-trung', 'Gà nướng xì dầu mật ong kiểu Hoa', 'Những miếng ức gà nướng óng ả màu cánh gián từ xì dầu đặc và mật ong, thấm sâu hương thơm ấm áp của ngũ vị hương, tỏi gừng và dầu mè, thịt bên trong vẫn mềm mọng khi thưởng thức.', 'chinese', 45, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món nướng","Ức gà","Xì dầu","Mật ong","Cơm nhà"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-08b08cad387c7c9f', 'dau-phu-chien-toi', 'Đậu phụ chiên giòn sốt tỏi', 'Đậu phụ cứng chiên áp chảo giòn rụm lớp vỏ ngoài nhờ phủ bột bắp, bên trong vẫn béo mềm, quyện cùng bát sốt tỏi hành lá xèo thơm trong dầu nóng pha xì dầu và dầu hào chay.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Đậu phụ","Món chay","Sốt tỏi","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-cbbfa59518b7d47d', 'mi-tron-toi', 'Mì trộn dầu hành tỏi phi xì dầu', 'Món mì trộn kiểu Thượng Hải nhanh gọn chỉ trong 15 phút với từng sợi mì bóng bẩy áo đều dầu hành phi giòn thơm, tỏi phi vàng nhạt cùng hỗn hợp xì dầu nhạt và xì dầu đặc đậm đà.', 'chinese', 10, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Bữa nhanh","Tỏi phi","Hành phi","Bữa trưa"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-266587069d92cb79', 'cua-hap-gung', 'Cua biển hấp gừng chấm giấm đen', 'Món cua hấp gừng thanh tao kiểu Trung Hoa tôn vinh trọn vẹn độ ngọt tự nhiên và thớ thịt săn chắc của cua biển tươi, kết hợp cùng bát nước chấm giấm đen Trấn Giang pha gừng băm dịu vị ấm bụng.', 'chinese', 12, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Cua biển","Hải sản","Gừng tươi","Thanh tao"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b02fdf7cecfae119', 'muc-kho-tuong', 'Mực ống kho xì dầu gừng', 'Món mực ống kho xì dầu gừng kiểu Hoa với những khoanh mực trắng dày thịt săn giòn, thơm hương rượu Thiệu Hưng và gừng sợi ấm nồng, thấm đẫm nước sốt hai loại xì dầu sánh nâu bóng mượt điểm dầu mè thơm lừng.', 'chinese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món kho","Mực ống","Xì dầu","Cơm nhà","Đậm đà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4693d6520fbd9d49', 'bo-nuong-toi', 'Thịt bò nướng tỏi lát kiểu Hoa', 'Món thịt bò nướng tỏi thơm lừng với từng lát bò thăn mềm mọng cháy cạnh nhẹ, hòa quyện hương xì dầu dầu hào đậm đà, điểm xuyết những lát tỏi phi vàng giòn rụm và muối tiêu chấm kèm.', 'chinese', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món nướng","Thịt bò","Tỏi phi","Cháy cạnh","Món nhậu"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-dd48c08a9b9ed207', 'suon-chien-gion', 'Sườn non chiên giòn ngũ vị', 'Từng khúc sườn non thơm lừng ngũ vị hương và tỏi, được bao bọc bởi lớp bột trứng vàng ruộm giòn tan bên ngoài trong khi thớ thịt sát xương bên trong vẫn mềm ngọt mọng nước.', 'chinese', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Sườn non","Giòn rụm","Ngũ vị hương","Cơm nhà"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b4924a7d33d5acff', 'chao-trung-trung', 'Cháo trứng vân mây kiểu Hoa', 'Nồi cháo trắng sánh nhừ bông mịn kiểu Hoa với những sợi vân trứng gà vàng óng mềm mượt hòa quyện, thoang thoảng mùi tiêu trắng ấm nồng, hành lá tươi và chút xì dầu nhạt dịu vị.', 'chinese', 45, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cháo nóng","Trứng gà","Bữa sáng","Dễ tiêu","Thanh nhẹ"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4a712c9f5f9913be', 'mi-tom-nong', 'Mì nước tôm tươi gừng hành', 'Tô mì nước nóng hổi kiểu Hoa với nước dùng gà thanh ngọt quyện hương gừng tỏi phi dịu nhẹ, sợi mì trứng dai mềm ăn kèm tôm tươi săn giòn, cải thìa xanh mướt và nấm thái lát.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì nước","Tôm tươi","Bữa sáng","Thanh ngọt","Nhanh gọn"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a27445c786a3fd67', 'com-bo-donburi', 'Cơm bò Gyudon Nhật Bản', 'Tô cơm bò Gyudon trứ danh của Nhật Bản với từng lát thịt bò mềm mọng thấm đẫm nước sốt ngọt mặn cân bằng từ Dashi, xì dầu Nhật, rượu Sake và Mirin, hòa cùng hành tây thái lát chín mềm đặt trên cơm trắng hạt ngắn nóng hổi.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gyudon","Cơm bò Nhật","Donburi","Bữa trưa nhanh","Nhật Bản"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-aba623dc468a9569', 'canh-ca-nam-nhat', 'Canh cá hồi nấu nấm kiểu Nhật', 'Tô canh cá hồi nấu nấm kiểu Nhật trong vắt và thanh nhẹ với nước dùng ngâm tảo bẹ Kombu ngọt umami tự nhiên, thịt cá hồi phi lê xử lý chần sơ kiểu Shimofuri hoàn toàn không tanh, kết hợp nấm đùi gà và hương gừng rượu Sake ấm áp.', 'japanese', 18, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Canh cá Nhật","Cá hồi","Nấm đùi gà","Tảo bẹ Kombu","Thanh ngọt"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4f398ac575200416', 'mi-udon-ca-ri', 'Mì Udon cà ri gà Nhật Bản', 'Tô mì Udon cà ri gà chuẩn vị Nhật Bản kết hợp sợi mì lúa mì bản to dai mềm với phần nước dùng cà ri sánh mượt đậm đà từ nước dùng Dashi, viên cà ri Nhật, xì dầu, rượu Sake cùng thịt đùi gà và rau củ ngọt thanh.', 'japanese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì Udon","Cà ri Nhật","Đùi gà","Món nước ấm","Nhật Bản"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b8731e057182331b', 'bap-cai-tron-me-nhat', 'Bắp cải trộn mè rang kiểu Nhật', 'Món rau phụ bắp cải trộn mè kiểu Nhật thanh mát và giòn sần sật: bắp cải thái sợi được ủ nhẹ với muối cho mềm giòn tự nhiên rồi trộn đều trong hỗn hợp mè trắng rang giã dập quyện xì dầu Nhật, đường, dầu mè thơm và giấm gạo.', 'japanese', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món trộn Nhật","Bắp cải","Mè rang","Rau phụ","Giòn mát"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f04b28987d7cd34a', 'cua-nuong-muoi-nhat', 'Cua nướng muối biển kiểu Nhật', 'Món cua nướng muối kiểu Nhật (Yaki-kani) trứ danh vùng Hokkaido: từng thớ thịt cua biển tươi ngọt mọng nước được bảo vệ bởi lớp vỏ nướng xém cùng muối biển, rượu Sake và chút bơ lạt thơm béo, ăn kèm chanh vàng tươi và xì dầu.', 'japanese', 15, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cua nướng muối","Hải sản Nhật","Tiệc nướng","Hokkaido","Cao cấp"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-bf6c9c4d92b2e04c', 'tom-om-gung-nhat', 'Tôm om gừng nước tương kiểu Nhật', 'Món tôm om gừng Shogani kiểu Nhật Bản với những con tôm tươi săn giòn, đỏ au đẹp mắt thấm đẫm nước sốt om ngọt mặn hài hòa từ xì dầu Nhật, rượu Sake, Mirin, đường và hương gừng tươi cay ấm.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Tôm tươi","Gừng tươi","Nhanh gọn","Đưa cơm"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-92aabff659e3c551', 'ga-xao-toi-han', 'Gà xào sốt tỏi Hàn Quốc', 'Món gà xào sốt tỏi kiểu Hàn hấp dẫn với từng miếng thịt đùi gà rút xương ngoài giòn rụm, bên trong mọng nước, quyện đều lớp sốt tỏi băm mật ong, giấm gạo và xì dầu đặc sánh bóng thơm lừng.', 'korean', 18, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thịt gà","Món xào","Sốt tỏi","Hàn Quốc","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4b592ae31a81a527', 'bo-kho-tuong-han', 'Thịt bò kho tương Hàn Quốc', 'Món thịt bò kho tương Hàn Quốc (Jangjorim) mang hương vị mặn ngọt đậm đà đặc trưng: thịt thăn bò được hầm mềm rồi xé dọc thớ thấm vị xì dầu, ăn kèm tỏi kho bùi béo và ớt sừng cay dịu rất bắt cơm.', 'korean', 75, 5, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt bò","Nước tương","Hàn Quốc","Cơm nhà"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-72e70eb4e8fba4db', 'tom-xao-kim-chi', 'Tôm xào kim chi Hàn Quốc', 'Đĩa tôm xào kim chi Hàn Quốc bắt mắt với thịt tôm hồng tươi giòn ngọt thấm hương bơ tỏi gừng, quyện cùng kim chi cải thảo chua cay nhẹ, cải thảo giòn sần sật và ớt chuông đỏ rực.', 'korean', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Tôm tươi","Kim chi","Hàn Quốc","Bữa tối nhanh"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-88b58c0233dec53e', 'trung-xao-kim-chi', 'Trứng xào kim chi Hàn Quốc', 'Đĩa trứng xào kim chi mềm mịn tan trong miệng với từng mảng trứng vàng ươm béo nhẹ xen lẫn kim chi cải thảo chua cay giòn sần sật, cực kỳ gọn nhẹ cho bữa sáng hoặc bữa tối bận rộn.', 'korean', 8, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món nhanh","Trứng gà","Kim chi","Hàn Quốc","Bữa sáng"]', 5, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e5d49dd8dc1449d1', 'ba-chi-kho-kim-chi', 'Thịt ba chỉ kho kim chi Hàn Quốc', 'Nồi thịt ba chỉ kho kim chi Hàn Quốc (Kimchi Jjim) đậm đà quyến rũ với từng miếng ba chỉ ninh mềm tan béo ngậy, thấm trọn vị chua cay nồng nàn của kim chi lên men kỹ và hương tương đậu Doenjang trầm ấm.', 'korean', 65, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món kho","Ba chỉ heo","Kim chi","Hàn Quốc","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-daec3b038c4f43af', 'ca-nuong-tuong-han', 'Cá thu nướng chấm tương Hàn Quốc', 'Món cá thu nướng kiểu Hàn hấp dẫn với lớp da cá giòn rụm vàng ươm, phần thịt bên trong trắng mềm béo ngậy giữ trọn vị ngọt tự nhiên, kết hợp nước chấm xì dầu tỏi ớt chanh tươi cân bằng vị béo rất bắt cơm.', 'korean', 20, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cá nướng","Cá thu","Hàn Quốc","Nước chấm tương","Bữa cơm gia đình"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4ca7d6f55d5b7937', 'mi-xao-bo-han', 'Miến xào thịt bò Hàn Quốc (Japchae)', 'Đĩa miến trộn Japchae Hàn Quốc óng ả sắc màu với sợi miến khoai lang dai mềm quyện hương dầu mè rang và đường nâu ngọt dịu, kết hợp thịt thăn bò mềm thơm cùng nấm hương, rau chân vịt, cà rốt và hành tây giòn ngọt.', 'korean', 20, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Miến xào","Thịt bò","Japchae","Hàn Quốc","Tiệc gia đình"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-09e07baa201acf28', 'chao-tom-han', 'Cháo tôm Hàn Quốc (Saewoo-juk)', 'Tô cháo tôm Saewoo-juk kiểu Hàn sánh mịn mượt mà với hạt gạo rang dầu mè thơm bùi, thịt tôm tươi thái nhỏ ngọt tự nhiên cùng cà rốt, hành tây, vân trứng gà mềm mịn và rong biển nướng giòn rắc mặt.', 'korean', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món cháo","Tôm tươi","Hàn Quốc","Ấm bụng","Dễ tiêu"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9c2f22829fd3d3f1', 'bo-xao-kim-chi', 'Thịt bò xào kim chi Hàn Quốc', 'Đĩa thịt bò xào kim chi Hàn Quốc hấp dẫn với từng lát thịt thăn bò mềm ẩm thấm gia vị, kết hợp hoàn hảo cùng kim chi cải thảo chua cay đậm đà và hành tây giòn ngọt quyện sốt mật ong dầu hào bóng đẹp.', 'korean', 12, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Kim chi","Hàn Quốc","Đưa cơm"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-d7b9a40e678c0e29', 'ga-nuong-muoi-han', 'Gà nướng muối kiểu Hàn', 'Món gà nướng muối kiểu Hàn (Dak-sogeum-gui) giản dị mà cực kỳ cuốn hút: thịt đùi gà rút xương được áp chảo tự tiết mỡ giúp lớp da mỏng giòn tan, thịt bên trong ngọt mọng quyện hành lá tỏi nướng xém thơm nức.', 'korean', 18, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gà nướng","Đùi gà","Hàn Quốc","Da giòn","Bữa cơm gia đình"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-2b289d9040d46110', 'dau-phu-kho-gung-han', 'Đậu phụ kho gừng kiểu Hàn', 'Đĩa đậu phụ kho gừng Hàn Quốc (Dubu Jorim) thơm nức mùi gừng tỏi xào quyện nước tương xì dầu mặn ngọt hài hòa, miếng đậu bên ngoài săn vàng thấm vị mà bên trong vẫn giữ được độ mềm béo thanh tao.', 'korean', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Đậu phụ","Món kho","Gừng tươi","Hàn Quốc"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-7cb7368109956ad5', 'canh-kim-chi-gia', 'Canh kim chi giá đỗ Hàn Quốc', 'Tô canh kim chi giá đỗ (Kimchi Kongnamul-guk) nóng hổi thanh nhẹ mà đậm đà: giá đỗ giữ nguyên độ giòn ngọt tự nhiên hòa quyện nước dùng cá cơm tảo bẹ cùng vị chua cay dịu của kim chi chín kỹ.', 'korean', 18, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Kim chi","Giá đỗ","Hàn Quốc","Thanh mát"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a3e676be13c4c51c', 'bo-ham-nam-han', 'Thịt bò hầm nấm Hàn Quốc', 'Nồi thịt bò hầm nấm Hàn Quốc (Beoseot Bulgogi Jeongol) ấm áp sang trọng với nước dùng tảo bẹ củ cải trong ngọt, kết hợp thịt thăn bò ướp sốt đậm đà cùng nấm đùi gà, nấm hương, rau củ tươi và miến khoai lang dai mềm.', 'korean', 30, 5, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món hầm","Thịt bò","Nấm tươi","Hàn Quốc","Lẩu gia đình"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-1b54108818405e6a', 'com-chien-ba-chi-kim-chi', 'Cơm chiên ba chỉ kim chi Hàn Quốc', 'Món cơm chiên ba chỉ kim chi Hàn Quốc (Kimchi Bokkeumbap) đậm đà khó cưỡng với từng hạt cơm săn tơi phủ màu đỏ cam bắt mắt của tương ớt Gochujang, quyện thịt ba chỉ chiên xém béo giòn, kim chi chua cay và trứng ốp la lòng đào.', 'korean', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Ba chỉ heo","Kim chi","Hàn Quốc","Bữa tối nhanh"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9328a098d7bd1f6f', 'ga-nuong-chanh-ot', 'Gà nướng chanh ớt kiểu Thái (Gai Yang)', 'Món gà nướng chanh ớt kiểu Thái hấp dẫn với từng chiếc đùi gà góc tư da vàng óng giòn rụm, thịt thớ mềm mọng thấm đẫm hương vị chua thanh của nước cốt chanh, mặn thơm nước mắm cùng vị cay nồng ấm của tỏi và ớt hiểm.', 'thai', 40, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Gai Yang","Gà nướng","Thái Lan","Chanh ớt","Món tiệc"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-cc203adb1d5aa11b', 'canh-ca-sa-ca-chua', 'Canh cá nấu sả cà chua kiểu Thái', 'Tô canh cá sả cà chua kiểu Thái có phần nước dùng trong veo, thơm dịu tinh dầu sả tươi, hòa quyện cùng thịt cá trắng ngọt chắc, vị chua nhẹ từ cà chua chín và chanh tươi giúp bữa cơm thêm nhẹ bụng, ấm áp.', 'thai', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Canh cá","Sả cà chua","Nước trong","Thái Lan","Thanh mát"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-7bd81a7e8fb33958', 'muc-om-sa-thai', 'Mực hấp om sả chanh kiểu Thái', 'Món mực om sả kiểu Thái kết hợp kỹ thuật hấp nhanh giữ trọn độ giòn ngọt tự nhiên của mực ống tươi cùng hương tinh dầu sả nồng nàn, hòa quyện với nước sốt hải sản Nam Jim chua cay mặn ngọt bùng vị.', 'thai', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mực hấp","Sả chanh","Hải sản Thái","Chua cay","Ít dầu mỡ"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0abadc2e606770a7', 'cua-hap-sa', 'Cua biển hấp sả gừng kiểu Thái', 'Cua biển hấp sả gừng kiểu Thái giữ trọn vị ngọt chắc nguyên bản của thịt cua tươi, quyện cùng hương thơm nồng ấm của sả cây, gừng tươi và rượu vang trắng bốc hơi trong xửng hấp, ăn kèm muối tiêu chanh ớt cay thanh rất bắt vị.', 'thai', 18, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cua hấp","Sả gừng","Hải sản","Thái Lan","Món tiệc"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-cc6a0ca585b502d4', 'larb-ga', 'Larb gà bằm trộn thính gạo kiểu Isaan', 'Larb gà kiểu Isaan là món gỏi thịt ấm nổi tiếng của vùng Đông Bắc Thái Lan, gây ấn tượng với thịt gà bằm mềm ẩm không khô, quyện thính gạo rang giòn bùi, vị chua thanh của chanh, mặn thơm nước mắm và hương lá bạc hà tươi mát.', 'thai', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Larb gà","Isaan","Thính gạo","Chua cay","Thái Lan"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6e4967b3145dee09', 'nam-xao-hung-que-thai', 'Nấm đùi gà xào húng quế kiểu Thái chay', 'Phiên bản chay thanh đạm nhưng cực kỳ bắt cơm của món xào đường phố Thái Pad Krapao: nấm đùi gà xém cạnh giòn ngọt sần sật thấm sốt xì dầu đậm đà, quyện hương cay nồng của tỏi ớt và lá húng quế tươi bùng vị.', 'thai', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pad Krapao","Món chay","Nấm đùi gà","Húng quế","Thái Lan"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4d9fae75b597d2c5', 'bo-nuong-sa-thai', 'Thịt bò ướp sả nướng kiểu Thái', 'Từng lát thịt thăn bò mềm mọng thấm đẫm hương thơm nồng nàn của sả non băm nhuyễn, tỏi, tiêu đen, xì dầu và nước mắm ngon, nướng nhanh trên lửa lớn cho mặt thịt xém cạnh thơm phức, cực kỳ hợp cho bữa tiệc hay cơm gia đình.', 'thai', 12, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Bò nướng","Sả thơm","Thái Lan","Món nhậu","Nướng vỉ"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a97820d3080e47eb', 'tom-xien-sa-nuong', 'Tôm sú xiên cây sả nướng thơm nồng', 'Tôm sú xiên sả nướng mang hương thơm nhiệt đới quyến rũ: dùng chính thân cây sả vót nhọn xiên dọc mình tôm giúp thịt tôm chín giữ dáng thẳng đẹp, thấm đẫm tinh dầu sả hòa quyện vị đậm đà của dầu hào, nước mắm và muối ớt chanh.', 'thai', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Xiên sả","Hải sản Thái","Món tiệc","Chanh ớt"]', 25, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a9d8b4d783b986d1', 'com-tom-sa-thai', 'Cơm chiên tôm sả kiểu Thái', 'Đĩa cơm chiên tôm sả kiểu Thái thơm nức mùi sả non phi vàng và hương khói chảo wok, hòa quyện thịt tôm săn ngọt, cà rốt giòn thanh, trứng chiên tơi xốp cùng vị đậm đà hài hòa của xì dầu, dầu hào và nước mắm.', 'thai', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Tôm sả","Thái Lan","Nhanh gọn","Bữa chính"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-4095c816782acd82', 'salad-ca-chua-cay-thai', 'Salad cà chua trộn cay kiểu Thái', 'Món salad cà chua cay kiểu Thái (Yum Makhuea Thet) thanh mát đầy sức sống với từng múi cà chua chín đỏ mọng nước thấm sốt mắm chanh đường thốt nốt, điểm xuyết vị giòn bùi của đậu phộng rang và tôm khô đậm đà.', 'thai', 3, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Salad Thái","Cà chua","Chua cay","Khai vị","Mát lành"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-0e9c9740a6232263', 'heo-xao-hung-que', 'Thịt heo bằm xào húng quế kiểu Thái (Pad Krapao)', 'Món ăn quốc dân của đường phố Thái Lan: thịt nạc vai heo xay xào tơi đậm đà cùng đậu đũa giòn ngọt, quyện mùi thơm cay nồng của tỏi ớt phi và lá húng quế, ăn kèm cơm trắng nóng và trứng gà ốp la viền giòn lòng đào béo ngậy.', 'thai', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pad Krapao","Thịt heo bằm","Húng quế","Đường phố Thái","Đưa cơm"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b6d6788784da6342', 'ca-chien-sot-cay-thai', 'Cá chiên giòn rưới sốt ớt tỏi kiểu Thái (Pla Rad Prik)', 'Cá chiên sốt cay kiểu Thái (Pla Rad Prik) gây thương nhớ bởi lớp da cá chiên giòn tan vàng ruộm ôm lấy thớ thịt cá trắng ngọt mềm ẩm, quyện cùng nước sốt tỏi ớt đường thốt nốt sánh dẻo chua cay mặn ngọt bùng vị.', 'thai', 22, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cá chiên giòn","Pla Rad Prik","Sốt cay","Thái Lan","Đưa cơm"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-71cac2085659d819', 'ga-xao-dua-thai', 'Thịt đùi gà xào dứa chua ngọt kiểu Thái', 'Đĩa gà xào dứa kiểu Thái rực rỡ sắc màu với thịt đùi gà áp chảo mềm ngọt săn cạnh, quyện cùng dứa chín thơm mọng, ớt chuông đỏ và đậu Hà Lan giòn tươi trong lớp sốt chua ngọt cay nhẹ bóng mượt từ giấm gạo, đường nâu và nước mắm.', 'thai', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gà xào dứa","Chua ngọt","Thái Lan","Màu sắc","Cơm gia đình"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-b398545ca76325f1', 'canh-bap-cai-sa-thai', 'Canh bắp cải nấu sả chanh Thái chay', 'Tô canh bắp cải sả Thái chay thanh nhẹ trong veo, kết hợp vị ngọt mát tự nhiên của bắp cải xanh và cà rốt, đậu phụ non mềm mịn cùng hương thơm nồng dịu của sả đập dập và nước cốt chanh tươi rất dễ ăn.', 'thai', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Canh chay","Bắp cải","Sả chanh","Thanh mát","Thái Lan"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-9f9a3f24b4141acb', 'cua-chien-toi-ot-thai', 'Cua lột chiên giòn xóc tỏi ớt kiểu Thái', 'Cua lột chiên tỏi ớt kiểu Thái hấp dẫn với lớp vỏ ngoài giòn rụm vàng ươm bọc lấy phần thịt cua ngọt béo mềm tan, xóc đều cùng bộ ba hương liệu Thái gồm rễ ngò rí, tỏi chiên giòn và ớt hiểm cay nồng thơm lừng.', 'thai', 15, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cua chiên giòn","Cua lột","Tỏi ớt","Hải sản Thái","Món nhậu"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-8fecebfe6dc0f0a2', 'mi-y-rau-bina', 'Mì Ý sốt kem rau bina và hạnh nhân', 'Món mì Ý chay nhẹ nhàng nhưng đầy đặn dinh dưỡng với lớp sốt xanh ngọc mượt mà từ rau bina chần xay nhuyễn cùng phô mai ricotta béo thanh, parmesan đậm vị và hạnh nhân rang thơm bùi.', 'italian', 18, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì Ý","Rau bina","Sốt kem","Nhanh gọn","Thanh đạm"]', 12, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-20d3992a65cb17fd', 'mi-y-ga-nam', 'Mì Ý gà nấm sốt cà chua', 'Đĩa mì Ý đầy đặn dinh dưỡng cho bữa tối gia đình với ức gà mềm mọng thấm gia vị, nấm đùi gà xào lửa lớn giữ trọn độ giòn ngọt và vị chua thanh nhẹ tự nhiên từ cà chua chín tươi.', 'italian', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì Ý","Ức gà","Nấm đùi gà","Cà chua","Bữa tối"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-38137393c32d70d7', 'risotto-tom', 'Risotto tôm tươi nấu nước dùng vỏ tôm', 'Đĩa risotto chuẩn phong cách Ý với hạt gạo Arborio dẻo mềm nhưng vẫn giữ độ sần nhẹ ở lõi, tỏa hương ngọt biển sâu lắng nhờ nước dùng ninh từ vỏ và đầu tôm rang kỹ, kết thúc bằng bước đánh bơ tạo độ bóng kem mượt mà.', 'italian', 40, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Risotto","Tôm tươi","Cơm Ý","Hải sản","Sánh kem"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e61010e240534690', 'muc-om-ca-chua-y', 'Mực om cà chua kiểu Ý', 'Món mực om cà chua mang đậm hương vị vùng biển nước Ý với từng khoanh mực mềm mọng không hề bị dai, thấm đẫm nước sốt cà chua pelati chua thanh hòa quyện mùi tỏi, rượu vang trắng và ngò tây tươi.', 'italian', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Mực om","Cà chua","Hải sản","Ẩm thực Ý","Món chính"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-452ef6d0f8ec0de9', 'tom-om-ca-chua-y', 'Tôm om sốt cà chua kiểu Ý', 'Món tôm om sốt cà chua thanh nhẹ kiểu Ý hoàn thành chỉ trong 25 phút với nguyên liệu tinh gọn: tôm tươi bóc vỏ săn ngọt quyện trong sốt cà chua passata sánh mịn, điểm vị cay nhẹ từ ớt và hương thơm tươi mát của húng quế Tây.', 'italian', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Tôm om","Sốt cà chua","Nhanh gọn","Hải sản","Ẩm thực Ý"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-f44be7e8c88c20d3', 'sup-ca-hoi-kem-y', 'Súp cá hồi kem tươi kiểu Ý', 'Bát súp cá hồi nấu kem kiểu Ý sánh mịn tự nhiên nhờ khoai tây bở hòa cùng kem tươi béo dịu, tôn lên vị ngọt thơm đặc trưng của từng khối phi lê cá hồi tươi chín vừa tới.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Súp kem","Cá hồi","Khoai tây","Ẩm thực Ý","Mùa lạnh"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-e748a717f7250188', 'salad-ca-hoi-dua-leo', 'Salad cá hồi áp chảo dưa leo sốt chanh', 'Đĩa salad cá hồi thanh mát cân bằng dinh dưỡng với miếng phi lê cá hồi áp chảo vừa chín tới mềm ngọt, ăn cùng dưa leo ướp muối giữ độ giòn sần sật, rau xà lách tươi và nước sốt nhũ tương dầu ô liu chanh vàng dịu mát.', 'italian', 10, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Salad","Cá hồi","Dưa leo","Thanh mát","Ít tinh bột"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-957396bc647d3798', 'bong-cai-om-ca-chua-y', 'Bông cải xanh om cà chua kiểu Ý', 'Món rau ăn kèm giản dị chuẩn bếp nhà Ý với từng nhánh bông cải xanh mềm ngọt nhưng vẫn giữ độ chắc, quyện trong nước sốt cà chua bi chua thanh sánh nhẹ, dậy mùi tỏi phi thơm trong dầu ô liu nguyên chất.', 'italian', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Bông cải xanh","Cà chua","Món phụ","Món chay","Ẩm thực Ý"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-c98aa0f1ffe2f469', 'suon-om-ca-chua-y', 'Sườn heo om sốt cà chua kiểu Ý', 'Món sườn heo om cà chua đậm đà kiểu Ý với dẻ sườn áp chảo xém cạnh thơm phức, hầm liu riu cùng hành tây, rượu vang trắng, cà chua đóng hộp và ô liu đen cho đến khi thịt mềm tơi dễ dàng tách khỏi xương.', 'italian', 80, 5, 'hard', '/frigo/illustrations/delicious-meal.png', '["Sườn heo","Ragu Ý","Om cà chua","Ô liu đen","Cuối tuần"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a286f8724d79a504', 'ca-chua-tron-pho-mai', 'Cà chua trộn phô mai Mozzarella tươi kiểu Ý', 'Món khai vị lạnh thanh mát chuẩn phong cách Ý tôn vinh nguyên liệu tươi ngon nhất: cà chua chín mọng cắt lát dày quyện phô mai Mozzarella tươi mềm béo, dầu ô liu nguyên chất thơm nồng và lá húng quế Tây tươi mát.', 'italian', 5, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Khai vị","Cà chua","Mozzarella","Salad Ý","Mát lành"]', 10, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-83ed31fc537569a6', 'bo-cuon-rau-bina-y', 'Bò cuộn rau bina phô mai kiểu Ý', 'Những cuộn thịt bò involtini khéo léo ôm trọn phần nhân rau bina xanh mướt xào bơ tỏi, phô mai Mozzarella tan chảy và cà rốt ngọt thanh, áp chảo xém cạnh rồi om mềm cùng cà chua và rượu vang trắng.', 'italian', 40, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Involtini","Bò cuộn","Rau bina","Phô mai","Ẩm thực Ý"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-a92103c19952bcf0', 'ga-chien-chanh-y', 'Gà chiên giòn ướp chanh vàng kiểu Ý', 'Món gà chiên thơm mát hương chanh vàng vùng Địa Trung Hải: ức gà ướp rượu vang trắng, chanh tươi và tỏi thảo mộc giúp thịt mềm ẩm, bọc lớp bột chiên xù giòn rụm trộn phô mai Parmesan và vỏ chanh bào.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Gà chiên","Chanh vàng","Parmesan","Giòn rụm","Ẩm thực Ý"]', 20, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-afdcd866c1f92192', 'ca-om-ca-chua-y', 'Cá phi lê om cà chua bi kiểu Ý', 'Món cá om thanh tao kiểu ngư dân vùng biển Naples nước Ý với từng miếng phi lê cá thịt trắng mềm ngọt giữ nguyên thớ, nấu trong nước dùng cà chua bi tươi mát quyện hương tỏi, rượu vang trắng và quả ô liu đen.', 'italian', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cá om","Cà chua bi","Hải sản","Thanh nhẹ","Ẩm thực Ý"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-6d26ce6b0af4fb79', 'rau-bina-om-kem-y', 'Rau bina om sốt kem Béchamel kiểu Ý', 'Món rau ăn kèm sang trọng chuẩn cổ điển Ý với rau bina nấu chín bằng chính độ ẩm tự nhiên rồi vắt ráo, xào thơm cùng hành tây và hòa quyện trong lớp sốt kem trắng Béchamel sánh mịn, thơm vị bơ sữa, Parmesan và nhục đậu khấu.', 'italian', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Rau bina","Béchamel","Sốt kem","Món phụ","Món chay"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4),
('imp-bd34e8ea2eaa1cd4', 'sup-bap-cai-y', 'Súp bắp cải đậu trắng thịt xông khói kiểu Ý', 'Nồi súp bắp cải kiểu nông thôn Ý đầy đặn dinh dưỡng với nền rau củ xào thơm quyện thịt xông khói, ninh mềm cùng đậu trắng cannellini, bắp cải ngọt thanh và nui Ý hạt nhỏ, hoàn thiện bằng lớp phô mai Parmesan béo dịu.', 'italian', 45, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Súp Ý","Bắp cải","Đậu trắng","Thịt xông khói","Mùa lạnh"]', 15, 'curated', 'Takolio Culinary Standard V4', 'reviewed', 4)
